window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26331553"]={"book":{"id":26331553,"title":"非暴力沟通","author":"马歇尔·卢森堡","translator":"阮胤华","publisher":"华夏出版社","pubdate":"2015-1","isbn":"9787508081908","tags":["沟通","心理学","人际关系","心灵成长","心态","实用","生活","正能量"],"memCount":15},"np":1,"pb":[22],"idx":[{"i":16550,"t":"非暴力沟通表达愤怒四步法","l":"TF1-1","c":"张连英","g":1,"p":1},{"i":13395,"t":"“自我宽恕四步法”-回归本心，化消极为积极","l":"TF2-3","c":"张兮吾","g":1,"p":1},{"i":13329,"t":"“有效倾听四步法”-做一个合格的倾听者","l":"TF2-2","c":"张兮吾","g":1,"p":1},{"i":13305,"t":"表达愤怒四步法-用表达愤怒的方式来代替宣泄愤怒的情绪","l":"TF2-1","c":"张兮吾","g":1,"p":1},{"i":9455,"t":"如何用“三步感谢法”表达感谢","l":"TF1-1","c":"聚宝盆","g":1,"p":1},{"i":8342,"t":"用非暴力的方式交流","l":"TF1-2","c":"赵红","g":1,"p":1},{"i":8336,"t":"运用非暴力沟通的方式表达和倾听","l":"TF2-4","c":"叶叶","g":1,"p":1},{"i":7318,"t":"如何用非暴力沟通法反馈","l":"TF2-2","c":"王丽珍","g":1,"p":1},{"i":7204,"t":"如何做一个快乐的人","l":"TF2-1","c":"惊哲","g":0,"p":1},{"i":6700,"t":"非暴力沟通的方式表达感激","l":"TF2-1","c":"壹佳壹","g":1,"p":1},{"i":6124,"t":"非暴力沟通—倾听","l":"TF3-2","c":"gaogao高高","g":1,"p":1},{"i":5471,"t":"非暴力沟通观察和评论应用","l":"TF2-2","c":"fy","g":0,"p":1},{"i":4945,"t":"如何让别人理解你的意思","l":"TF1-2","c":"壹佳壹","g":1,"p":1},{"i":4048,"t":"如何提出请求，对方更易接受？——非暴力沟通的艺术","l":"TF2-3","c":"林佳鸿","g":1,"p":1},{"i":3877,"t":"让愤怒不再愤怒","l":"TF2-2","c":"慧吉","g":1,"p":1},{"i":1047,"t":"非暴力沟通四要素","l":"TF2-1","c":"水澜色","g":1,"p":1},{"i":1046,"t":"观察","l":"TF2-1","c":"水澜色","g":1,"p":1},{"i":1045,"t":"你会表达自己的感受吗","l":"TF2-2","c":"水澜色","g":1,"p":1},{"i":1044,"t":"赞扬","l":"TF2-3","c":"水澜色","g":1,"p":1},{"i":1043,"t":"请求","l":"TF2-4","c":"水澜色","g":1,"p":1},{"i":1042,"t":"倾听","l":"TF3-1","c":"水澜色","g":1,"p":1},{"i":1041,"t":"我的生活我做主","l":"TF3-2","c":"水澜色","g":1,"p":1}],"ms":[{"id":16550,"topic":"非暴力沟通表达愤怒四步法","learn_goal":"","remark":"用非暴力沟通表达愤怒，帮助你收获良好人际关系","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"张连英","city":"唐山市"},"club":{"name":"廊坊风陵分舵","city":"廊坊"},"prologue":"\u003cp>【自我介绍】1分钟\u003cbr> \u003cbr>大家好，我叫张连英，连队的连，英雄的英，妈妈希望我能当个连队里的英雄来着。哈哈！不过愿望没实现。我来自河北唐山，也希望能早日在唐山建立分舵。\u003cbr>\u003cbr>我将用三个标签来介绍我自己。\u003cbr>\u003cbr>1我的职业是护士，从事老年骨科工作十余年，对于老年骨科治疗护理有深入了解。\u003cbr>\u003cbr>2家有六岁男宝，擅长亲子教育方面及沟通方面。\u003cbr>\u003cbr>3对于亲子阅读总结了一套小方法。主理一个亲子读书会，在萌芽阶段。共情力强，擅长非暴力沟通。希望和我有相通之处的你和我链接呦！\u003cbr>\u003cbr>拆书法介绍\u003cbr>\u003cbr>拆书法是一种成人学习法，不同于传统的学院式学习，是一种以人为中心，反求诸己，拆解书中经验、方法为我所用的学习法。是一种更有助于解决问题和提升能力的方法。\u003cbr>\u003cbr>分为个人学习拆书法和组织学习拆书法\u003cbr>\u003cbr>个人学习拆书法是采用RIA便签法，即通过R（阅读原文）、I（重述知识）、A（演练应用）的过程，达到消化吸收书中的知识，最后应用到工作生活的方法。可以提高自己的学习能力，思维能力和逻辑能力。\u003cbr>\u003cbr>组织学习拆书法是拆书家拆书成课，在现场讲解，引导一群人的提升认知能力，是一种促进知识为我所用的方法。\u003cbr>\u003cbr>拆书帮介绍\u003cbr>\u003cbr>拆书帮是一个非营利性自组织。是一个陪伴赋能共同成长的组织。也是一个读书界的武侠世界，这里有武侠世界的豪情与仗义，有温暖与指导。在这里可以找到性格相投的的书友，可以找到倾囊相授的师父，可以找到相逢一笑的知己。并且来这里的都是积极乐观向上的优秀人才。所以也欢迎优秀的朋友快来加入哦！\u003c/p>","ratings_count":2,"texts":[{"id":20675,"quote":"\u003cp>接下来我们一起拆解一下今天的片段。今天想跟大家分享的是非暴力沟通中的表达愤怒，我们先用两分钟来看一下拆页。如果看完了，可以在屏幕上扣1。\u003c/p>\u003cp>《非暴力沟通》\u003c/p>\u003cp>主题:表达愤怒p159-160\u003c/p>","explains":"\u003cp>根据拆页呢，我来说一下自己对这个片段的理解。\u003cbr>\u003cbr>这个拆页讲的是如何用非暴力沟通的方式表达愤怒。具体来说就是面对自己的愤怒情绪时用暂停来觉知自己的想法，查看自己内心的需要，从而表达自己的感受和需求。换句话说可以表达愤怒但是不用愤怒的方式表达。\u003cbr>\u003cbr>这样做有什么好处呢？可以充分地顺利地表达出自己的情绪和需求。更容易达成一致，沟通更顺畅，并且不破坏双方关系。\u003cbr>\u003cbr>那具体有哪些步骤呢\u003cbr>1面对愤怒，暂停，让自己冷静（在面对孩子快开学了依然玩耍不写作业时，可以先让自己暂停一下，深呼吸，冷静下来）\u003cbr>2觉知自己的内心想法，生气的点在哪里（想一想是什么让自己生气，是孩子不写作业学不会知识，还是老师会在群里@自己使自己丢面子）\u003cbr>3找到自己的需要（自己需要的是有学识的孩子还是是在家长群里有面子）\u003cbr>4用平和的方式说出自己的感受或需求（如，妈妈希望你能按时完成作业，好能在未来的学习中不掉队，并且养成按时完成作业的好习惯）\u003cbr>\u003cbr>那我们看看都在哪些场合可以用呢？\u003cbr>只要我们在遇到自己即将发火的情况时都可以用，我来举几个例子说明一下\u003cbr>1面对孩子不写作业时\u003cbr>2面对家人的不配合不理解时\u003cbr>3面对工作伙伴的不配合时\u003c/p>","interaction":"\u003cp>【A1联系具体经验】\u003c/p>\u003cp>接下来我分享一个我自己用非暴力沟通表达愤怒的案例吧！\u003c/p>\u003cp>在前天上班的时候，需要给患者输液换液。因为工作量大，工作人员少，所以非常忙碌。而有一位护工在看护患者连续把四瓶液体都输空了，这样导致我在换液体时非常麻烦，又浪费时间。也导致整个换液过程都延迟，让其他患者也着急。\u003c/p>\u003cp>当时我的内心非常愤怒，也在心里抱怨这个护工不好好看液，给我带来麻烦。不过因为长时间练习非暴力沟通，所以我在第一时间就没说话，让自己冷静了几秒钟，在我一边给他换液一边觉察自己的想法（这个护工太烦人了，总给我找麻烦）。但是同时我也想到了我的需求，我愤怒是因为我想快速换液的需求没达到所以才愤怒，于是我收敛了怒气，冷静平和的跟她说“看液的时候注意不要光顾着看手机，别把液体有空，要不然会耽误给大家换液的进度”。\u003c/p>\u003cp>护工听了我直接而平和的要求也及时向我表达了歉意，并且在接下来的时间也有好好看液，没再走空。\u003c/p>\u003cp>反思:\u003c/p>\u003cp>1首先我在面对自己的愤怒情绪时，及时控制住了情绪，没有把愤怒的话冲口而出。\u003c/p>\u003cp>2我快速地在心中觉知了自己的想法，没有直接说那个护工是个不负责任的护工。\u003c/p>\u003cp>3我及时地确定了自己的内心需求，就是护工看好液，我好换起液来更快更顺利。\u003c/p>\u003cp>4最后选择用平和的语气来说出我的需求和这样做的好处。\u003c/p>\u003cp>选择了非暴力沟通的方式表达了我的愤怒，使护工更加明白了她工作的重要性，为我的顺利高效工作奠定了基础。\u003c/p>\u003cp>所以在我们日常工作生活中也可以多多练习使用这个方法。\u003c/p>\u003cp>【A2具体应用】\u003c/p>\u003cp>学习是为了更好地应用。所以接下来的重点就是把它更好的应用在未来。\u003c/p>\u003cp>比如说\u003c/p>\u003cp>我的目标是:在接下来的一个月内，在面对愤怒情绪时，利用非暴力沟通的方法表达愤怒，采用平和的方式说出自己的感受或者需求，以达到顺利沟通，保持良好关系的目的。\u003c/p>\u003cp>那么我的行动计划就是:\u003c/p>\u003cp>1在面对愤怒情况时，先给自己按下暂停键，深呼吸几秒，冷静下来（如，孩子在我下夜班睡觉时大喊大叫，内心非常生气暴躁时，先给自己积极暂停，深呼吸几秒）\u003c/p>\u003cp>2觉知自己批判性想法（觉知自己是否有这样的想法:真是一个不知道体谅人的孩子）\u003c/p>\u003cp>3找到自己的需求（我需要一个安静的环境补觉休息）\u003c/p>\u003cp>4平和的表达愤怒（宝宝，妈妈下夜班很累很困，需要一个安静的环境，可以请你配合一下吗）\u003c/p>\u003cp>如果计划完成，我就奖励自己买一条喜欢的裙子。\u003c/p>\u003cp>【结束语】1分钟\u003c/p>\u003cp>最后总结一下今天的拆书，非暴力沟通表达愤怒的几步:1按下暂停键，调整情绪2觉察自己的想法3找到自己真正的需求4平和的表达感受或需求。\u003c/p>\u003cp>好了，我今天的分享就到此结束了，希望这个片段会对各位小伙伴有帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1693793752000,"updated_at":1699360805000,"ria":true},{"id":13395,"topic":"“自我宽恕四步法”-回归本心，化消极为积极","learn_goal":"","remark":"当我们做错事、安排不当，或是某种糟糕的行为而产生羞愧、自责、沮丧等悲观情绪时，我们往往会对自己进行负面的自我评价，结果让自己陷于自我憎恨的状态，无法发现自责原因和行为初衷。而“自我宽恕四步法”主张为自己的负面情绪按下暂停键，通过找到自责的原因及做这件事的初衷，放下当前负面的自我评价，聆听自己的心声并发现心灵深处的需要。看到美好，遇见美好！","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"张兮吾","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp> 拆书帮的各位拆友，大家晚上好，我是张兮吾。三个标签介绍一下自己。简单来说我的标签就是“ETC”。为什么叫“ETC”呢？第一个，教育咨询（Education Consultant）、第二个是拆书帮理念践行者，这是我未来对自己的一个希望，我用了一个词佳作Thruster，他表示火箭的助推器，第三个是Calligraphy Amateur，我个人是一名书法爱好者，简称就是“ETC”。\u003c/p>\u003cp> 今天我的分享选自《非暴力沟通》第124-125页，分享内容为“自我宽恕四步法”，在跟随我完成今天的RIA现场学习后，当我们在生活、工作中产生负面的自我评价而自责时，学习者能够通过找到自责的原因及做这件事的初衷，运用“自我宽恕四步法”，放下当前负面的自我评价，聆听自己的心声并发现心灵深处的需要，从而原谅自己，露出对自己由衷的笑容。（学习目标）\u003c/p>\u003cp>【现场分组】\u003c/p>\u003cp> 为方便大家分享沟通，我们现场两人一组。\u003c/p>\u003cp>【书籍介绍】\u003c/p>\u003cp>下面我来简单介绍一下这本书。\u003c/p>\u003cp>F：本书的作者是国际非暴力沟通中心的创始人：马歇尔∙卢森堡博士。本书内容详细阐述了非暴力沟通的底层逻辑/沟通原则、基于此逻辑，让我们学会如何用“爱”相处。\u003c/p>\u003cp>A：《非暴力沟通》和其他沟通类书籍相比，不只是一本提高语言修养或者是沟通技巧的书，更是通过非暴力沟通的方式处理我生活中的“爱/倾听/宽恕/愤怒/感激/惩罚/热情”等，从而解决生命中的痛苦的一本书。\u003c/p>\u003cp>B1：为什么要读这本书？在此之前，我先分享一段话“如果我只看到痛苦，我的心难免会被乌云所笼罩，被绝望所吞没。在徘徊中，终于有一天，我发现，我的人生可以对生命的美丽作出反应。”这段话摘自本书的译者阮胤华写的译序。如果你感到生活是疲累的，工作是痛苦的，却苦苦找不到原因的时候，那么这是一本可以让你看到美好，遇见美好的书。\u003c/p>\u003cp>B2：有的时候，我们不仅要和他人沟通，还要懂得与自己沟通，尤其是当我们产生负面的自我评价时，我们往往会更多的关注到自身的缺陷，憎恨自己，也因此而看不到生命的美丽。今天我分享的片段正是通过“自我宽恕”的方式，让你懂得如何爱自己。（FAB介绍法）\u003c/p>","ratings_count":1,"texts":[{"id":17404,"quote":"\u003cp> 首先，请大家花1分钟时间看下我发给大家的拆页，如果完成阅读，请举手示意，现在开始！\u003c/p>\u003cp> 【拆页1 《非暴力沟通》P124-125 作者：马歇尔·卢森堡】 张兮吾 TF2-3\u003c/p>\u003cp>外衣染上墨水带来的启发\u003c/p>\u003cp>我想通过个人经历来说明非暴力沟通的忧伤及自我宽恕。在一个研讨班开始前的一天，我买了一套浅灰色的夏季外衣。这个研讨班很重要，出席的人很多。在结束时，许多人围着我询问地址及其他信息，并请我签名。为了赶下一场会面，我匆忙地回答问题，并紧张地签字和留言。当我飞快地冲出门时，我将笔放入了新外套的口袋。我居然忘了戴笔帽！等到了外面，我吓了一跳——那件雅致的浅灰色外套已染上了墨水！\u003c/p>\u003cp>有二十分钟的时间，我不停地训斥自己：“你怎么可以这么粗心？这么愚蠢的错误！”我刚损失了一套崭新的外衣，如果我在生活中需要得到体谅，那么，此刻正是时候。可是，我却是在训斥自己，这简直糟透了。\u003c/p>\u003cp>幸运的是，二十分钟后，我意识到自己正在做什么。我静了下来，开始想外衣染上墨水使我什么样的需要得不到满足。我问自己：“我责备自己‘粗心’和‘愚蠢’，是想要满足什么需要呢？”\u003c/p>\u003cp>我马上就明白了，其实我是想照顾好自己：在匆忙地回应他人的请求时，要多留意自己的需要。此时，我的心情也随即发生了变化。我不再感到恼怒、羞愧和内疚，身体也一阵轻松。我体会着损失一件新外衣及忘记戴笔帽的悲哀，以及照顾好自己的强烈愿望。\u003c/p>\u003cp>接着，我开始考虑，我为了满足什么样的需要而随手把笔放入口袋中。这使我意识到，回应他人的请求对我是多么地重要。遗憾的是，为了尽量满足他人的需要，我忽视了自己的一些需要。想到这些，我并没有责备自己，而是感到对自己深深的爱——即使在我心不在焉地把笔放入口袋的时候，我也是在满足自己服务他人的渴望。\u003c/p>\u003cp>这样，我做到了同时包容上述的两种需要：一方面，服务他人；另一方面，照顾好自己。我相信，在类似的情形中，只要能意识到这两方面的需要，我就能灵活地克服困难。反之，如果陷于内心的冲突，只会使情况更糟。\u003c/p>","explains":"\u003cp>我看到拆友们已经完成了阅读。\u003c/p>\u003cp> 【what】\u003c/p>\u003cp>“自我宽恕四步法”是通过找到自责的原因及做这件事的初衷，从而能够放下当下对自己的某种行为而产生的负面的自我评价，看到事物好的一面，从而理解自己、原谅自己的一种方法。\u003c/p>\u003cp> 【why】\u003c/p>\u003cp>为什么我们要学习“自我宽恕四步法”，当我们因某种糟糕的行为而产生自责、沮丧等悲观情绪时，我们往往会对自己进行负面的自我评价，结果让自己陷于自我憎恨的状态，无法发现自责原因和行为初衷。（错误做法）而该方法主张为自己的负面情绪按下暂停键，通过找到自责的原因及做这件事的初衷，放下当前负面的自我评价，聆听自己的心声并发现心灵深处的需要。这样，我们就会发现，虽然当下的结果可能暂不尽人意，但是做这件是的初衷是好的，从而消除自责，化消极为积极，看到美好，遇见美好。\u003c/p>\u003cp>如果不能够及时处理羞愧、自责、沮丧等悲观情绪，长此以往，会带来自我否定，从而让自己缺乏信心、自卑。（不这么做会怎样）\u003c/p>\u003cp>那么，如何自我宽恕呢？\u003c/p>\u003cp> 【how】\u003c/p>\u003cp> ①\u003cstrong>停止自责\u003c/strong>：首先我们要停下一切自责的行为，然后告诉自己“自责解决不了问题”；\u003c/p>\u003cp> ②\u003cstrong>寻找原因\u003c/strong>：接下来思考为什么我会自责？自责的直接原因是什么？ \u003c/p>\u003cp> ③\u003cstrong>重拾初衷\u003c/strong>：问自己，做这件事的初衷是什么；我了满足什么样的需要而做了让我感自责的这件事？也就是自责的间接原因。\u003c/p>\u003cp> ④\u003cstrong>自我宽恕\u003c/strong>：在找到需求、重拾初衷后，你看到了自责的直接原因和间接原因，看到事物好的一面，从而理解自己、原谅自己。 \u003cbr> \u003c/p>\u003cp> 【意译案例】\u003c/p>\u003cp> 我给大家举一个例子。\u003c/p>\u003cp>每年过年的时候，大家都知道，按常州的习俗一般要请亲戚们来家里吃个饭，这种年饭对于常州乡下是很重要的，很多关系好的亲戚都会出席，而今年老丈人说让我来掌勺，你来做给大家。为了更好地招待各位长辈，在年前我就拟出了一份菜品十分丰富的菜单，但是在宴会当天，因为我没有提前把老汤吊好，所以耽误了很多时间，本来11点开始的饭局，到了12点半才陆续开始上菜。\u003c/p>\u003cp>有十分钟的时间，我不停地责备自己“这么重要的场合，爸妈放心地交给了我，怎么可以这么疏忽，把吊老汤这件事给忘记了”因为我一个准备环节的疏忽，让长辈们饿肚子等，如果在生活中需要得到体谅，那么此刻正是时候。而我却是一直在自责。\u003c/p>\u003cp>幸运的是，十分钟后，我意识到自己在做什么。我冷静下来，告诉自己“自责是解决不了问题的”，于是我开始思考我为什么会自责？我问自己：“我责备自己疏忽，是要满足什么需要呢？”\u003c/p>\u003cp>我瞬间意识到，其实我是想在过年的时候，让长辈们吃到更美味的家常菜。因为吊老汤做菜更好吃。此时，我轻松了很多，不再内疚、不再自责。\u003c/p>\u003cp>接着，我开始考虑，是什么样的初衷让我去吊老汤，准备这么多的菜呢？这使我意识到想好好招待长辈，报答长辈们平时的关心和照拂对我是多么的重要。想到这些，我并没有继续自责，而是感受到自己的这份心—虽然我忘记吊汤这个环节，让长辈们等了很久，但我也是在满足自己报答长辈们平时的关心和照拂的渴望。\u003c/p>\u003cp>这样，我就找到了自责的直接原因和间接原因，也就是自责原因和行为的初衷：原因是想让长辈们吃到更美味的家常菜；初衷是好好招待长辈，报答他们的关心和照拂。意识到这些以后，我心情开始变得轻松开心。有了这份感恩的心，今后还会有更多的机会，我一定能做好。\u003c/p>\u003cp>我们简单总结一下： \u003c/p>\u003cp>整个过程，首先，\u003cstrong>停止自责：\u003c/strong>我先让自己静下来，告诉自己“自责是解决不了问题的”；\u003c/p>\u003cp>其次，\u003cstrong>寻找原因：\u003c/strong>开始思考我为什么会自责？我问自己：“责备自己疏忽，要满足什么需要呢？”\u003c/p>\u003cp>接着，\u003cstrong>重拾初衷：\u003c/strong>是什么样的初衷让我去吊老汤，准备这么多的菜呢？\u003c/p>\u003cp>最后，\u003cstrong>自我宽恕\u003c/strong>：虽然让长辈们等了很久，但我也是在满足自己报答长辈们平时的关心和照拂的渴望。\u003c/p>\u003cp> 【预防异议】\u003c/p>\u003cp>可能有人会说，你这属于“欲盖弥彰”，没做好就是没做好！做错了认，是没错，但是也没有解决问题，我们不能一直认错地活着。“自我宽恕四步法”的核心找到双重需求，自责原因和行为初衷，即使事情没做好，但是做事的初衷是好的，从而解开这个执念，并设法弥补没有做好的行为造成的后果\u003c/p>\u003cp>也许还会有人说，遇到自责的事情内心痛苦时很简单，找个闺蜜，找个兄弟，喝个酒，聊聊天，倾诉一下就好了。找人倾诉最终只是发泄了情绪，但是并没有找到自责原因和行为初衷，并没有解决问题。况且当你找人倾诉的时候，如果碰到一位没有来拆书帮听我讲过“有效倾听四步法”的人，估计可能还要添堵，这也是说不准的事情。\u003c/p>\u003cp> 【where】\u003c/p>\u003cp> 什么时候可以运用该方法呢？适用于当我们做错事、安排不当，或是某种糟糕的行为而自责时，可以运用“自我宽恕四步法”找到积极的一面；同时，可以用来引导他人进行自我宽恕。但不包括损坏社会及他人利益及违法行为，如恶意破坏，偷盗等行为。\u003c/p>","interaction":"\u003cp> 我们刚刚学习了解了可以用“自我宽恕四步法”来调节自责的情绪。现在我们一起做一个演练。请大家认真听一下我们将要演练的场景：刘主管是公司行政部门的主管，每年年底的表彰大会都是由刘主管来负责筹划及一应具体事务的。小张是他的下属，工作很积极，得力助手。今年因为疫情的原因，刘主管需要把大部分精力放在志愿者的安排上面，这个时候小张主动提出，希望可以为领导分忧。考虑到刘主管近期实在忙碌，为了更好地为领导分忧，就想着尽量不要去打扰领导，自己把事情做好。但是因为是第一次负责这项工作，经验不足，又没有和领导及时沟通细节，导致没有事先彩排，导致现场颁奖的时候出现了奖牌错领/荣誉错发的状况。小张因此感到十分的自责。\u003c/p>\u003cp>现在请大家把拆页翻到背面-“A3-运用自我宽恕四步法”现在按照之前的分组进行演练。一个人扮演刘主管，另一个人扮演小张。刘主管如何运用“自我宽恕四步法”引导小张消除自责。通过刘主管的引导，找到自责的需求及事情的初衷，并进行自我宽恕。\u003c/p>\u003cp>演练时间8分钟，8分钟后，我会选择一组来进行演绎，听听他们是如何运用“自我宽恕四步法的”，现在开始。\u003c/p>\u003cp>OK，我看大家演练的都很好，唐老师的那一组还演练了2遍。\u003c/p>\u003cp>刚刚我有关注丁舵和马老师的这一组，那我们就请丁舵和马老师分享一下你们的演练。\u003c/p>\u003cp>马老师：好的，我是小张。\u003c/p>\u003cp>丁老师：我就是刘主管。\u003c/p>\u003cp>马老师：这次的表彰大会我做的特别不好，因为本身自己经验也不足，结果酿成大祸，奖牌错领，荣誉错发这种事情。说实在话主管，我自己都不能原谅我自己。确实错的太离谱了。\u003c/p>\u003cp>丁老师：小张，你平时工作也挺积极的。首先这件事情我觉得你也不要过于自责。先停止这种想法，我们一起去想一想到底是什么情况？我们先想想到底是什么原因导致你现在的这种自责呢？有哪些直接的原因导致你自责的呢？\u003c/p>\u003cp>马老师：主要还是因为我们行政部门负责本次表彰大会，结果现实出现了很大的错误，我觉得会影响了同事们对于公司的看法，有损了部门领导和公司的形象，这些都是不好的。\u003c/p>\u003cp>丁老师：那间接的原因是什么？你会自责你自己？\u003c/p>\u003cp>马老师：还是想把这件事做好的，但是结果没有达到自己的预期，因为本身想主动承担这件事是想为领导分担一部分工作的，结果没想到还给领导添堵了。\u003c/p>\u003cp>丁老师：我觉得虽然确实也出了一点小小的差错，我想问问你，你当时做这件事情的初衷是什么呢？\u003c/p>\u003cp>马老师：我的初衷其实还是想替领导分忧，毕竟平时看你也是太忙了，所以在过程中也不好意思打扰您，也没有想着安排彩排，结果因经验不足导致了现在的这个结果。初衷还是希望能把这件事情做好，能给整个公司的年底表彰大会做一个表率，表率一下我们行政部门的做事的风格。\u003c/p>\u003cp>丁老师：所以我相信你的初衷还是希望能够帮助我缓解点工作上面的压力\u003c/p>\u003cp>马老师：对对对，这是肯定是的。\u003c/p>\u003cp>丁老师：另外也是希望能够在这个过程中展现一下我们部门的工作热情。不过是由于工作上面的经验问题，有一点小小的差错。我觉得在这个过程中间，你也不用太过于自责。因为首先从工作的态度和积极性上来讲，你是完全没有问题的。只是经验上面略有小小缺失。今后我希望你在这种关键问题上面，有的时候没有经验的话可以多找我沟通沟通，我也可以把我的信息及时给你提点提点。这样可以确保工作过程中间疏漏少一点。\u003c/p>\u003cp>马老师：好的，经过您这么一说，我就想到了我的初衷确实是想做好这件事的，下回再有这样的情况我及时反馈和沟通。\u003c/p>\u003cp> 【where】\u003c/p>\u003cp>确实是，我听了你们的对话我也会觉轻松很多。\u003c/p>\u003cp>好的，非常感谢两位老师的分享，今天我们共同分享学习了“自我宽恕四步法”分别为“停止自责-寻找原因-重拾初衷-自我宽恕”。希望通过今天的学习，在今后的工作和生活中，当我们做错事、安排不当，或是某种糟糕的行为而自责时，能够通过找到原因及做这件事的初衷，放下当前负面的自我评价，从而原谅自己，让自己重新露出喜悦的笑容！\u003c/p>\u003cp>以上是我今日分享，感谢大家的参与！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1652410606000,"updated_at":1652412454000,"ria":true},{"id":13329,"topic":"“有效倾听四步法”-做一个合格的倾听者","learn_goal":"","remark":"当我们在请对方诉苦的时候，通常会产生先入为主的想法和判断，常常在听了几句话之后，就急于提建议，安慰或者表达我们的态度和感受。而“有效倾听四步法”主张放下已有的想法和判断，通过了解对方的观察、感受、需要和请求，并给予反馈，从而让对方能够更充分、更彻底地表达情绪。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"张兮吾","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>【开场语】\u003c/strong>\u003c/p>\u003cp> 拆书帮的各位拆友，大家晚上好，我是张兮吾。三个标签介绍一下自己，首先我的第二职业是做“缘分”英语培训；其次我是一名书法爱好者，平时喜欢写写字；最后，我是一名新晋1级拆书家，今天是我的TF2-2拆书过级，希望可以在5月份成为一名2级拆书家。\u003c/p>\u003cp> 今天我的分享选自《非暴力沟通》第97页，分享内容为如何运用“有效倾听四步法”，在跟随我完成今天的RIA现场学习后，学习者能放下已有的想法，不再急于建议、安慰，表达自己的想法，而是通过了解对方的观察、感受、需要和请求，并给予反馈，让对方能够更充分、更彻底地表达情绪。（学习目标）为方便大家分享沟通，我会将现场分为两组，我们3个人一组，进行讨论。\u003c/p>\u003cp>\u003cstrong>【书籍介绍】\u003c/strong>\u003c/p>\u003cp>下面我来简单介绍一下这本书，这本书大家并不陌生。\u003c/p>\u003cp>F：本书的作者是国际非暴力沟通中心的创始人：马歇尔∙卢森堡博士。非暴力沟通又称为爱的语言，让沟通不产生“暴力倾向”。\u003c/p>\u003cp>A：本书在豆瓣网评分8.4分，《非暴力沟通》和其他沟通类书籍相比，最大的亮点是能够将“非暴力沟通”的底层逻辑阐述的很清楚，当你掌握了这个底层逻辑并加以应用，不但可以避免人与人之间的冲突、对立，同时还能增加人与人之间的感情。\u003c/p>\u003cp>B1：为什么要读这本书？我们都知道，语言是人类最重要的交际工具，如果沟通方式不当，很容易将语言变成利器，从而伤害到彼此，或者让对方不再想要继续沟通下去。\u003c/p>\u003cp>B2：尤其是当我们的亲友感到痛苦时，我们总是觉得自己应该做些什么，好让对方好受一点，解脱一些，于是我们急于建议、安慰。结果却是对方不再向你吐露心声。今天我分享的片段正是通过“全身心”倾听的方式，让你做一个“合格”的倾听者，让对方充分地表达情绪。（FAB介绍法）\u003c/p>","ratings_count":3,"texts":[{"id":17337,"quote":"\u003ch2>【拆页1 《非暴力沟通》P94 作者：马歇尔·卢森堡】 \u003c/h2>\u003cp>用全身心倾听\u003c/p>\u003cp>当他人遭遇不幸时，我们常常急于提建议，安慰，或表达我们的态度和感受。为了倾听他人，我们需要先放下已有的想法和判断，全心全意地体会对方。倾听他人有助于对他人的理解和接纳。\u003c/p>\u003cp>与此同时，不论别人用怎样的词语表达自己，我们都可以用心体会他们的观察、感受、需要和请求。有时，我们可以主动表达我们的理解，来帮助对方了解我们在何种程度上明白了他的意思。在交流的过程中，我们保持持续的关注，为对方的充分表达创造条件。\u003c/p>","explains":"\u003cp>我看到拆友们已经完成了阅读。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>“有效倾听四步法”是通过了解对方的观察、感受、需要和请求，并给予反馈，从而达到能够让对方充分表达自己情绪的一种方法。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>为什么我们要学习“有效倾听四步法”，因为当我们在请对方诉苦的时候，通常会产生先入为主的想法和判断，常常在听了几句话之后，就急于提建议，看到对方很伤心，就急于安慰对方，或者表达我们的态度和感受（错误做法）。而“有效倾听四步法”主张放下已有的想法和判断，通过了解对方的观察、感受、需要和请求，并给予反馈，从而让对方能够更充分、更彻底地表达情绪。如果不用该方法，倾诉者往往会因为被打断，被误解，从而无法充分表达自己的情绪。（不这么做会怎样）\u003c/p>\u003cp>\u003cstrong>【案例说明】\u003c/strong>\u003c/p>\u003cp> 首先我先举一个我自身的例子，\u003c/p>\u003cp>时间：2022年3月份 地点：家里 沟通对象：我和我的爱人\u003c/p>\u003cp>事件背景：我爱人是大客户经理（KAM），早上接到了老板的电话，因为工作的事情把她从头到脚数落了一通，她有点难受，吃早饭的时候就和我提起了这件事，对话大致如下：\u003c/p>\u003cp>她：“唉，我们老板真的是，大周末的一大清早就发火，关键还没什么道理。”\u003c/p>\u003cp>我：“又惹你生气了啊，你们这个老板真是，我也是没法说，又干啥了？”\u003c/p>\u003cp>她：“前两天送样，检查后说质量没过关，要我们重新做。我第一时间去约客户了，但是人家直接说你们先整改好了把样送过来了再谈。明明是质量的问题，结果老板刚才说是我们销售工作没做好，约不出来客户，我们老板就是这样，总是有的没的胡乱指责。\u003c/p>\u003cp>我：“其实你老板也没说错，虽然产品质量确实是有问题，你也确实没搞定人家采购，如果产品各方面性能都好，又有竞争力，还要你们销售干啥，几个销售支持服务服务就好了，所以说我建议你啊，还是要在平时下功夫，哪怕产品有问题，至少能约出来当面谈谈，这样老板不就说不到你了。”\u003c/p>\u003cp>她“嗯，说是这么说”\u003c/p>\u003cp>她说完这句，就转移了话题，没有再继续往下说了。\u003c/p>\u003cp>从这个例子可以看出，这是一个很典型的急于把自己的想法表达了出来的案例。\u003c/p>\u003cp>那么，如何做一个合格的倾听者呢？\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>①\u003cstrong>简单回应\u003c/strong>：放下已有的想法和判断，做到不建议、不安慰、不评判、不表达。只是全神贯注地听，用简单的“是的/嗯/确实/继续”等作为回应即可；\u003c/p>\u003cp>②\u003cstrong>体会需要\u003c/strong>：通过对方的陈述，去体会是什么需要，让对方有这样的表达。当对方的表达中没有陈述，更多的是评论时，例如“他总是这样有的没的胡乱指责。”，那么这时，我们需要通过询问来了解我们的猜测是否准确，例如“你生气，是你需要被理解？”。\u003c/p>\u003cp>③\u003cstrong>给予反馈\u003c/strong>：为了更好地确认，我们可以使用疑问句来给与反馈。例如“所以说你很生气，是因为你希望你的领导可以更体谅你工作的难处，是么？”。\u003c/p>\u003cp>④\u003cstrong>确认结果\u003c/strong>：当对方不再诉苦时，或者情绪已经平稳下来，露出了很轻松的表情，那么说明对方的“负能量”很可能已经释放完了。如果无法确认对方是否还有话要说，这时我们可以说“你还有什么话要告诉我吗？”或者“你还有什么需要表达的么？”进行确认。\u003c/p>\u003cp>\u003cstrong>【案例整改】\u003c/strong>\u003c/p>\u003cp>针对我和我老婆的这个案例，我们做一个整改，为此，我还特意找我老婆又模拟了一遍。\u003c/p>\u003cp>她：“唉，我们老板真的是，大周末的一大清早就发火，关键还没什么道理。”\u003c/p>\u003cp>我：“嗯，要不你说来听听。”（放下想法）\u003c/p>\u003cp>她：“前两天送样，检查后说质量没过关，要我们重新做。我去约客户了，但是人家直接说你们先整改好了把样送过来了再谈。明明是质量的问题，结果老板说是我的问题，约不出来客户，我们老板就是这样，总是有的没的胡乱指责。\u003c/p>\u003cp>首先我体会到了她的感受，她感觉被冤枉了，因为她需要老板能就事论事。（体会需要）\u003c/p>\u003cp>于是我说：“嗯，所以你生气是因为你需要老板能够更多的理解一下你的难处，是么？”（给予反馈）\u003c/p>\u003cp>她：“是的呀，每个人都希望自己的难处能被理解，这也是人之常情呀。”然后脸上的表情放松了很多。”\u003c/p>\u003cp>在我看到她表情舒缓的时候，我对她说“怎么样？好点了么？”（确认结果）\u003c/p>\u003cp>她：“嗯，和你这样说完是好多了”\u003c/p>\u003cp>（回到原文建议，反例变正例）。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能有人会问，这找人倾诉不就是想得到一些建议和解决办法吗？其实不然，人在生活的奔波中，总会因为工作/生活上遭到不友好的对待时，就会积聚一些“负能量”，而这些“负能量”需要定期地释放出来，很多倾诉的人并不是不知道这些道理和该怎么做，只是缺少理解和关爱。等她把身体中的“负能量”吐完了，平静下来了，自己也就知道该怎么做了。我们要知道，“倾听”本身并不是解决问题这件事，而是你能够真正解决这个问题的前提和基础。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>该方法适用于当你身边的人拥有痛苦/郁闷/不解等消极情绪时，找到你倾诉；或者你的孩子受了委屈/被人冤枉时，找你倾诉等场景。\u003c/p>","interaction":"\u003cp> 刚刚我们学习了用“有效倾听四步法”，那么接下来大家设想一下你们自己未来的生活中也有一些类似的情景。\u003c/p>\u003cp>例如①：马上下班了，你同事正和你开心的聊下班后到哪儿去玩，结果他领导急匆匆的走进办公室，又给他安排了一些额外的工作，说：“这个着急要，马上做出来给我。”你的同事在领导走后，气呼呼的向你抱怨，这时你是如何倾听的？例如②：你和你的闺蜜在喝下午茶，这时候她老公来电话说“晚上公司有应酬，晚上要很晚回来。”电话挂断后，你闺蜜把手机往桌子上一扔，气不打一处来，向开始你抱怨说她老公哪里哪里不好。这时，你是如何倾听的？（显性举例）\u003c/p>\u003cp>\u003cstrong>【A2-分布催化1-情景】\u003c/strong>\u003c/p>\u003cp> 请大家把你生活中极有可能发生的类似场景，写在便签上。这里，我们只需写出类似的场景即可。2-3分钟时间，现在开始！\u003c/p>\u003cp>刚刚两组我都参加了一下，听到了两组的分享，Luna老师和韩老师，两位老师看谁先来分享一下你们的故事？\u003c/p>\u003cp>\u003cstrong>【情景分享】\u003c/strong>\u003c/p>\u003cp>Luna老师：学生和我说“那个数学老师都凶死了，我就说错了一句话，她马上就让我滚出去，我最讨厌她了，我都不想上她的数学课了。”我就和她说“你这个学生真不懂事，老师这么说你她也是为你好啊，她是怕你上课讲话影响你听课啊，怕你讲话影响别人学习啊。你怎么就这么不理解老师呢？你也要懂点事啊！哇啦哇啦等等”后来他就不说话了，我以为是他被我说服了，其实是他不想说了。\u003c/p>\u003cp>韩老师：我分享的就是我老婆说我做鱼的事情，我老婆说“你当初追我的时候为了买我想吃的东西你可以跑遍整个半个丹阳城，但是现在做条鱼，做这么长时间，葱和辣椒都没放，这个鱼还这么重的腥味”因为做鱼女儿不吃辣，没放辣椒，她又不吃葱，所以油煎了后就只放了盐和酱油，可能腥味还是比较重。\u003c/p>\u003cp>张兮吾：“你当时是怎么回答她的呢？”\u003c/p>\u003cp>韩老师：女儿不吃葱，就没放葱，又不吃辣，就没放辣椒。\u003c/p>\u003cp>张兮吾：这里我还是想提醒一下各位老师，韩老师的例子是他老婆抱怨他，Luna老师的例子是学生跟她抱怨其他老师，我们该如何倾听，实际上韩老师你不是作为倾听者，是作为承受者，你是被指责的一方，而Luna老师确实是做一个倾听者的例子。\u003c/p>\u003cp>\u003cstrong>【A2-分布催化2-情境】\u003c/strong>\u003c/p>\u003cp>好！非常好的分享！接下来，我们进入到规划应用阶段。请大家反思自己之前做的不到位的地方，并结合“有效倾听四步法”，把你刚刚写下来作为“倾听者”的案例，加工成具体情境，在小组内进行讨论，5分钟时间，现在开始！\u003c/p>\u003cp>\u003cstrong>【情境分享】\u003c/strong>\u003c/p>\u003cp>下面，我们请丁老师和Luna老师的双人情境模拟一下。\u003c/p>\u003cp>Luna老师：丁老师，我有一件事情想和您说一下，我不想上数学课了；\u003c/p>\u003cp>丁老师：啊？为什么？\u003c/p>\u003cp>Luna老师：我觉得我们数学老师太不公平了！今天早上我和张兮吾两个人都没写作业。\u003c/p>\u003cp>丁老师：哦？\u003c/p>\u003cp>Luna老师：他就让我一个人去罚站，而且把试卷抄两遍，张兮吾却没事。\u003c/p>\u003cp>丁老师：嘿嘿\u003c/p>\u003cp>Luna老师：早上我就迟到了1分钟，他就没让我进教室，我就在外面站了一节课。\u003c/p>\u003cp>丁老师：你觉得老师对你不太公平是么？\u003c/p>\u003cp>Luna老师：嗯，是的。\u003c/p>\u003cp>丁老师：你觉得在这个过程中间老师对你太严厉了，还是什么？\u003c/p>\u003cp>Luna老师：他严厉一些没关系，你不要只对我一个人严厉。\u003c/p>\u003cp>丁老师：嗯，你希望老师可以公平一些，你希望你和其他的伙伴要有一样的待遇。\u003c/p>\u003cp>Luna老师：嗯。\u003c/p>\u003cp>丁老师：还有什么想要倾诉的么？\u003c/p>\u003cp>Luna老师：没有，我就觉得他这样吧，你就对我一个人不公平，同学们都笑话我，觉得老师就是针对我，一到数学课他们就说“呦~又是数学课了”，就搞得我上课开始就心情不愉快。\u003c/p>\u003cp>丁老师：我觉得你是希望老师能给你更多的包容感，能够让你和其他的伙伴都一样，即使你犯错了，也要有更公平的待遇。\u003c/p>\u003cp>Luna老师：嗯。\u003c/p>\u003cp>丁老师：我会跟老师沟通一下的，我觉得你能和我讲这么多我也很欣慰，也希望你能够好好地去理解老师，好么？你觉得是不是好受一点呢？\u003c/p>\u003cp>Luna老师：那我还是写个东西给老师说一下吧，把事情和他说一下吧，免得同学们总笑话我。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>好的，非常感谢两位老师的分享，所以说我们从对话可以看出，运用“有效倾听四步法”后，从倾诉者的角度可以更完整地倾诉他的情绪。今天我们共同分享学习了“有效倾听四步法”分别为“放下想法-体会需要-给予反馈-确认结果”。希望通过今天的学习，在今后的工作和生活中，当有人向我们倾诉时，我们不要急于提建议，安慰或者表达我们的态度和感受。而是通过了解对方的观察、感受、需要和请求，并给予反馈，从而让对方的倾诉更充分、情绪表达的更完整。我们也能成为一名合格的倾听者。\u003c/p>\u003cp>以上是我今日分享，感谢大家的参与！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1651225453000,"updated_at":1651283061000,"ria":true},{"id":13305,"topic":"表达愤怒四步法-用表达愤怒的方式来代替宣泄愤怒的情绪","learn_goal":"","remark":"当我们听到不中听的话或者别人做了让你愤怒的事时，我们难免会指责他人，甚至大发雷霆，或是选择了“忍”而“表达愤怒四步法”不主张宣泄愤怒，亦不主张忽视或者压抑愤怒，能够让你既表达了愤怒，而又不伤感情。","level":"TF2-1","duration":25,"status":30,"type":0,"chaishujia":{"username":"张兮吾","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>\u003cstrong>【开场&amp;分组】\u003c/strong>\u003c/p>\u003cp> 各位拆友，大家晚上好，我是张兮吾。三个标签介绍一下自己，首先我的第二职业是做“缘分”英语培训，所谓缘分英语培训就是我只接受适合在我这里学习的学生和认同我教学理念的家长；其次我是一名书法爱好者；最后，我是一名新晋1级拆书家，4月份开启我的2级拆书家之路，希望可以尽快打怪升级，做出更大的贡献。\u003c/p>\u003cp>今天我的分享选自《非暴力沟通》第140-141 页，分享内容为如何运用“表达愤怒四步法”，在跟随我完成今天的RIA现场学习后，学习者能够掌握如何\u003cu>表达\u003c/u>你的愤怒，而不是宣泄或者压抑你愤怒的情绪。（学习目标）为方便大家分享沟通，现在我们进行现场分组，由于线上拆书的原因，今天我们分为2组。\u003c/p>\u003cp>\u003cstrong>【书和作者介绍】\u003c/strong>\u003c/p>\u003cp> 下面我来简单介绍一下这本书。\u003c/p>\u003cp>F：本书作者是国际非暴力沟通中心的创始人：马歇尔∙卢森堡博士。非暴力沟通又被称为爱的语言，让沟通不产生“暴力倾向”。\u003c/p>\u003cp>A：本书在豆瓣网评分8.4分，《非暴力沟通》这本书是我认为所有“沟通方式”类书籍的基础，本书最大的亮点是能够将“非暴利沟通”的底层逻辑阐述的很清楚，当你掌握了这个底层逻辑并加以应用，不但可以避免人与人之间的冲突、对立，同时还能增加人与人之间的感情。\u003c/p>\u003cp>B1：为什么要读这本书？我们都知道，语言是人类最重要的交际工具之一，如果沟通方式不当，很容易将语言变成利器，从而伤害到彼此。\u003c/p>\u003cp>B2：尤其是当你处于愤怒的状态时，表达愤怒的方式不当，很可能就会变成一种情绪的宣泄，而对方也会因此而忽略了你愤怒的真正原因。今天我分享的片段正是通过“表达”愤怒的方式来代替宣泄愤怒的情绪，用不伤害感情、不挑起争端的方式表达了你的愤怒。（FAB）\u003c/p>","ratings_count":1,"texts":[{"id":17309,"quote":"\u003cp>\u003cstrong>【原文拆页】-《非暴力沟通》P140-141 \u003c/strong>\u003c/p>\u003cp>表达愤怒的四个步骤\u003c/p>\u003cp>现在让我们看看非暴力沟通表达愤怒的具体步骤。首先，停下来，除了呼吸，什么都别做。我们避免采取行动去指责或惩罚对方。我们只是静静地体会自己。接着，想一想是什么想法使我们生气了。例如，无意中听到某个人的谈话后，我们认为由于种族的原因自己遭到了排斥。这时，我们体会着愤怒，并留意脑海中盘旋的想法：“这太不公平了！她这是种族歧视！”我们知道，像这样的想法是尚未满足的需要的可悲表达。于是，接下来，就去了解自己想要满足的需要。如果我把某个人当作种族主义者，我的需要也许是接纳、平等、尊重或联系。为了充分表达自己，我们现在需要张开嘴，说出我们的愤怒——怒火此时已被转化为需要以及与需要相联系的情感。然而，表达此时的感受也许需要很大的勇气。对我来说，生气并冲着人们嚷“你们这是种族歧视”是很容易的。事实上，我甚至还会觉得高兴。但是，倾听心底深处的感受和需要却很可能引发不安。为了充分表达愤怒，我们也许会对那个人说：“你走进房间后，和其他人都打了招呼，却没有和我说话，现在你又在议论白种人，注意到这些，我的胃有些不舒适，而且很害怕，因为我很看重平等。我想请你告诉我，听到我说这些，你的感觉怎么样？”\u003c/p>","explains":"\u003cp>\u003cstrong>【I便签】 \u003c/strong>\u003c/p>\u003cp> 我看大部分拆友已经完成了阅读，下面我们进行下一个片段。\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp> 首先我想讲一下什么是“表达愤怒四步法”，“表达愤怒四步法”是以非暴力沟通四要素为基础，通过深入地了解愤怒，从而充分表达内心的渴望，是一种“化愤怒为渴望”的方法。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp> 为什么我们要学习“表达愤怒四步法”，因为当我们听到不中听的话或者别人做了让你愤怒的事时，我们难免会指责他人，甚至大发雷霆，或是选择了“忍”（错误做法）。而“表达愤怒四步法”不主张宣泄愤怒，亦不主张忽视或者压抑愤怒，能够让你既表达了愤怒，而又不伤感情。如果不用“表达”的方式处理愤怒，结果可能是指责、争吵、宣泄等方式会恶化彼此的矛盾，而一味的隐忍也只会为你自己带来更多的积怨，终有一天是会爆发。（不这么做会怎样）\u003c/p>\u003cp>\u003cstrong>【案例说明】\u003c/strong>\u003c/p>\u003cp>首先我先举一个我的例子，人们都说婆媳关系不好相处，那么其实丈母娘和女婿有时候也会有矛盾，孩子2岁多的时候，每次去外婆家，外婆都会准备很多好吃的来讨好孩子，像米饼/糖/面包/饼干等我眼中的垃圾食品，我觉得孩子还是要少吃一些。有一次带孩子去外婆家，刚一进门，外婆就送上了“旺旺至尊大礼包”，我本身就担心这个，去之前就很担心，当我看到的时候，当时心情就不大好了， \u003c/p>\u003cp>我说：“妈，这些东西都不太健康，我们在家都不吃的，以后还是少给他买这些”\u003c/p>\u003cp>我岳母的回答十分霸道“这个怎么了？有什么不能吃的？”\u003c/p>\u003cp>我说：“这都是垃圾食品，对孩子身体不好啊！”\u003c/p>\u003cp>我岳母说“季吉小时候也是吃这些长大的，我就是这么喂她的，有什么不好的？”\u003c/p>\u003cp>这句话着实是点燃我了，不过面对长辈，我只能选择隐忍，但是心里很难受。以至于有一段时间我和我岳母的沟通、包括她的做法，我都有一些意见，所以关系一度十分紧张。（举例说明）\u003c/p>\u003cp> 那么，如何做到“表达愤怒”呢？\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>①平息愤怒：保持安静，不要有任何的言语和行为，避免指责和惩罚对方。\u003c/p>\u003cp>②寻找原因：想一想，是对方的哪一句话，哪一个举动，或者是那一句话刺激到了你，让你产生愤怒的情感。\u003c/p>\u003cp>③体会需要：我的什么需求或者需要会造成我愤怒的原因。\u003c/p>\u003cp>通过前3个步骤的情绪平复和自我分析后，接下来我们可以进行第4步骤，就是你要表达你的感受\u003c/p>\u003cp>④表达感受：我看到/你刚刚说…（陈述事实），让我感到很担心/生气/愤怒（表达心情），因为我需要…（提出需求），听到我说这些，您的感觉怎么样？（请求反馈）\u003c/p>\u003cp>\u003cstrong>【案例整改】\u003c/strong>\u003c/p>\u003cp>针对我之前的案例，我们做一个整改，如果运用“表达愤怒四步法”来复盘一下这件事：\u003c/p>\u003cp>①平息愤怒：首先，什么都不要做，什么都不要说，不要埋怨父母总买这些东西；\u003c/p>\u003cp>②寻找原因：为什么我愤怒，是因为我岳母是从“历史经验”来带孩子，而不是从孩子本身出发，并且她认为自己没有任何问题；\u003c/p>\u003cp>③体会需要：因为我希望我的孩子有一个健康的体魄，可以多吃一些有营养的东西；\u003c/p>\u003cp>④表达感受：妈，我看您给孩子准备了一个大礼包，让我感到有些担心，因为我们希望孩子能够多吃些有营养的健康食品，大礼包里面的食品有很多添加剂，热量很高，不是很健康，多给孩子买些水果、牛奶更好。听到我说这些，您的感觉怎么样？当然，如果可以的话，考虑到毕竟是女婿，我可能会让我老婆去这样说。如果一定要我说，我也会这样去表达。（回到原文建议，反例变正例）\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp> 该方法多适用广泛，尤其是当双方因为观点不一致而争吵，或者当你当你受到言语/行为的伤害到你，让你产生了担心、生气、愤怒等情绪时，这种方法就很适用了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1便签-激活经验】\u003c/strong>\u003c/p>\u003cp>为了巩固和实践今天分享的知识点内容，现在邀请大家回顾一下，过去一个月左右发生在你身上让你愤怒的事情。比如你的孩子在玩玩具，把家里弄的到处都是，连下脚的地方都没有，你走到他面前，很严肃且大声的和他说：“现在，马上把玩具收掉，快点！”，这时候老人过来说“孩子那么小，让他收拾什么啊？”；我说“妈，你不能这么惯着孩子啊”岳母没有理睬我，对孩子说“我们不听爸爸的！我们还小，我们不要收拾”。当你听到这样的回复，你当时是怎么做的？再比如平时孩子和你在一起都是自己吃饭的，家里老人来了之后就开始追着孩子喂，不断地塞喂，孩子到哪里喂到哪里；你告诉他们不要喂，孩子可以自己吃的，他们却回复说“喂一次两次又没什么，不快点吃饭就凉了，凉的东西吃到肚子里能好的？再说了，你老婆就是我这么喂到大的。” 请大家想想有没有类似的场景，是如何做的？（显像提问）请从时间/人物/经过/结果以及你当时的想法几个要素出发，将关键字写在便笺上，请大家在小组内进行讨论分享，这里我们只需要回顾之前你是怎么做的。2-3钟时间，现在开始！请大家进入小组讨论。\u003c/p>\u003cp>刚刚我分别去两个组参与了一下，我看大家都还蛮有感触的，刚刚在1组听的比较多，我们请2组的李老师分享一下，当时是什么样的一件事，你当时又是怎么做的？\u003c/p>\u003cp>时间：上周末\u003c/p>\u003cp>对象：我和孩子\u003c/p>\u003cp>背景：上周末我和孩子在楼下玩，她和其他小朋友一起玩，有两个孩子在打羽毛球，玩着玩着她就跑到两个打羽毛球的孩子中间去跳绳，我一看，诶~你这站在别人打羽毛球的中间跳绳不是打扰人家么？我就把她喊过来了，\u003c/p>\u003cp>李老师：“你这咋回事？你站中间啥意思啊？”我语气严肃地说；\u003c/p>\u003cp>李老师孩子：“你闭嘴！”她跑过来跟我说，“我是和大家讲好的，我这是在表演花样跳绳”\u003c/p>\u003cp>我当时热血上脑了，这家伙，你怎么能和我说让我闭嘴呢？况且旁边还有其他的家长。\u003c/p>\u003cp>（拆书家追问“你当时是怎么回答的呢？”）\u003c/p>\u003cp>李老师：“你可以直接跟我说是怎么回事，不要跟我‘你闭嘴’”。当时还有其他的家长在，我是硬冷静下来了，我不能在外面发脾气，我发起脾气来也收不住场，可能也会影响到她今天下午玩的情绪。\u003c/p>\u003cp>\u003cstrong>【A1+便签-反思加工经验】\u003c/strong>\u003c/p>\u003cp>非常清晰！感谢李老师的分享，我能看出来，李老师包括大家还是有些遗憾的，那么如果时间可以倒流，同样的场景，运用“表达愤怒四步法”， 你会怎么做呢？请大家在小组内进行讨论分享，4钟时间，现在开始！\u003c/p>\u003cp>刚刚我两个小组都去看了一下，大家讨论的都很好，大家对于之前的做法和今后的做法，那么我们请2组的李老师分享一下，如果时光倒流，你会怎么做？把你的案例分享给大家。\u003c/p>\u003cp>李老师“首先我会深呼吸，平静一下自己的心情，然后我会陈述一下事实，‘听到你和我说让我闭嘴，我感到比较难受，心情比较愤怒，因为我需要你的尊重，听到我说这些，你的感受是怎么样的？’我下次会平静的跟她说”\u003c/p>\u003cp>非常好！我相信孩子听到你这样和他沟通的话，她一定也会很平静，而且会进入一个反思的阶段。感谢李老师的分享！\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>今天我们共同分享学习了“表达愤怒四步法”，其实这是两部分内容，首先你要做到“表达愤怒”而不是宣泄情绪，分别为“平息愤怒-寻找原因-体会需要-表达感受”。同时，我们也学习了“如何表达愤怒情绪”分别为：陈述事实-表达感受-提出需求-请求确认。\u003c/p>\u003cp>希望通过今天的学习，在今后的工作、生活的日子里，我们可以更多地用“表达”来代替“宣泄”，用“体会”来代替“指责”，化愤怒为渴望，化争吵为和谐。让我们的生活更美好，以上是我今日分享，感谢大家的参与！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1650614081000,"updated_at":1650616356000,"ria":true},{"id":9455,"topic":"如何用“三步感谢法”表达感谢","learn_goal":"学习者能够在向他人表达感谢时，让对方感受到谢意，拉近距离。","remark":"现实生活中，我们经常会不经意地遭遇到言语上的指责、嘲讽、否定、说教以及任意打断、拒不回应、随意出口的评价和结论，这些给我们带来的情感和精神上的创伤，甚至比肉体的伤害更加令人痛苦。 \r\n著名的马歇尔·卢森堡博士发现了一种沟通方式，依照它来谈话和聆听，能使人们情意相通，和谐相处，这就是“非暴力沟通”。\r\n","level":"TF1-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"聚宝盆","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是王小芳，昵称“聚宝盆”，有近15年的工作经验。轮过的岗位有HR、财务、销售等工作，在目前就职的这家公司已经工作了11年。在工作之余，我喜欢看书，但是我有惰性，1本书经常要读1-2个月，有一天看到一篇文章说：有人1年读了100本书，平均3天读1本，当时我不相信，心想肯定是吹牛。可当我在十点课堂听了赵周老师的《升级你的学习力》课程后，才知道真的有一种方法，可以做到1年读100本书，那就是RIA学习法，我被这种独特的方法吸引。于是，我在微信上关注了拆书帮，关注常州龙城分舵，我主动与分舵取得了联系，开始积极地关注分舵的活动，我参加过4次线下活动，1次21天线上训练营。我是一个好学和要求上进的人，参加拆书是想练就拆书技能，解决工作和生活中的问题。参加拆书帮是因为一个人学习很孤单，而一群人学习可以相互赋能、相互促进。&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;那么到底什么是拆书？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 拆书：是一种学习方法，适用于成人学习，主要用于提升个人学习和解决问题的能力，是把知识关联到我们过往的工作经验并进行反思，从而规划未来的具体运用。\r\n拆书分为个人学习拆书法和组织学习拆书法。个人学习应用RIA便签法，R是指阅读原文的片段，I是指用自己的话重述，A1关联到过往的经历反思，A2规划应用。读一本书的效果等同于参加同主题的培训。\r\n组织学习拆书法是一位拆书家拿一本书加工成一场现场学习，引导和促进一群人把知识拆为已用。学习效果上，一位拆书家不亚于一位培训师。&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 什么是拆书帮？&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 拆书帮：是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵（也叫拆书帮俱乐部）。它是公益性青年自组织，主要是帮助更多学习爱好者成长为拆书家。&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;今天我和大家分享的这本书是《非暴力沟通》，作者是著名的心理学家马歇尔卢森堡博士。他早年成长于动荡不安的底特律市，这使他对于怎样运用新的沟通方式，在面对暴力时，可以和平解决分歧，发展出浓厚的兴趣。19世纪60年代，他发现了神奇而平和的沟通方式：非暴力沟通，至今为止已经影响了全世界数百个国家，甚至被联合国教科文组织评定为“解决冲突的最佳实践”。&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; 今天我分享的是来自于非暴力沟通中“表达感激”的片段：\u003c/p>\u003cp>&nbsp; &nbsp; 接下来，请大家花2分钟的时间阅读手中的拆页，主要关注我用上下箭头标注的中间部分，读完请举手示意。现在开始：&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":13265,"quote":"\u003cp>《非暴力沟通》 179页&nbsp;\u003c/p>\u003cp>非暴力沟通表达感谢的方式包含三个部分：\u003c/p>\u003cp>1. 对方做了什么事情使我们的生活得到了改善；\u003c/p>\u003cp>2. 我们有哪些需要得到了满足;\u003c/p>\u003cp>3. 我们的心情怎么样？\u003c/p>\u003cp>在表达感激时，这三个部分的先后次序并不重要；有时，我们甚至可以通过微笑或说声“谢谢”来表达着三个部分。然而，如果我们要确保对方能够明白我们的意思，那么用语言具体地描述这三个部分是值得的。\u003c/p>","explains":"\u003cp>【WHAT】原文拆页，讲述了表达感谢时，为了让对方能够感受到我们的谢意，我们要清楚地告诉他们：因为他们所做的事，给我们带来了哪些帮助，我们又是什么感觉。\u003c/p>\u003cp>【WHY】别人帮助了我们，我们用“三步感谢法”表达我们的谢意，会让对方觉得自己的帮助有价值，也会认为我们是值得帮助的人，进而拉近双方的关系。下次再请他帮忙，应该会更容易些。如果不这样做，我们的感谢就是泛泛而谈，浮于表面，纯粹是应付，双方都不会留下深的印象。下次再请他帮忙，他不一定乐意。\u003c/p>\u003cp>【HOW】那么，如何用“三步感谢法”表达自己的感谢呢？我们分为以下三步：\u003c/p>\u003cp>第一步，原因：说出对方做了什么对我们有帮助的事,可以用这样的句式“因为你做了…….”； \u003c/p>\u003cp>第二步，结果：说出这件事给我们带来的帮助，可以用这样的句式“这件事，对我最大的帮助是……”；\u003c/p>\u003cp>第三步，感受：说出我们的感受是怎么样的，可以用这样的句式“我感受到……”。\u003c/p>\u003cp>【WHERE】“三步感谢法”，不适用于表示礼貌、客气的场合，比如对方说请座、您先请、出示证件等。这些场合是不适用的。其他日常工作、生活中别人给我们提供了帮助，我们都可以用这种方法表达谢意。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>下面我分享一个我的经历：\u003c/p>\u003cp>去年冬天的一个下午，外面下着大雪，路湿滑难走，物流几乎是停运的状态，只有短距离的少量车在运行。我们急需要从离工厂100米左右的外仓拨货到工厂使用，物流上根本找不到车，我急得像热过锅上的蚂蚁。正好有一辆扬州车给我们厂里送货，抱着死马当活马医的心态，我向驾驶员提出了请求，告诉他事情的紧急程度，希望他能够帮忙。没想到驾驶员爽快地答应了，解了我的燃眉之急。我当即向驾驶员表示了感谢，我说：“师傅，太感谢你了！”。师傅也礼貌性地说：“不用谢！”。我也没有多想。可是，今年3月份，我又有事请他帮忙，但他好像不太乐意。\u003c/p>\u003cp>【反思】现在回想当时，应该是我的感谢太敷衍，没有让对方感受到我的谢意。我其实可以这样说：“师傅，太感谢你了！因为你在这么恶劣的天气帮我拨了最紧急的物料，这件事，对我最大的帮助是让我解了燃眉之急!要是没有你，我这货不知道怎么才能弄过来，有可能会导致停产。我感受到你就是雪中送炭！本来我非常着急，现在我悬着的心终于放下了！非常感谢！”\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>通过上面的案例分享，我相信大家也联想到自己曾经也有过类似的经历。\u003c/p>\u003cp>那我们应该如何去规划应用呢？下周我正好要向我的朋友表示感谢。事情是这样的：\u003c/p>\u003cp>我妈有比较严重的风湿，朋友知道后，很热心。他认识一个祖传的医生，专做这种手工药膏，帮我弄了10片，下周三准备给我送过来。我们见面时，我打算这样说：\u003c/p>\u003cp>“大卫，谢谢你！\u003c/p>\u003cp>1.原因：“ 因为你热心地帮我找祖传中医，专门做了手工药膏，还特意送过来。”\u003c/p>\u003cp>2.结果：“ 这件事，对我最大的帮助是我妈的风湿有救了，终于可以让我妈减轻病症了，说不定还能治好。”\u003c/p>\u003cp>3.感受：“我感受到你的热心。我太感动了！非常感谢！”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我想朋友听了以后，一定会感受到我的谢意。\u003c/p>\u003cp>&nbsp; &nbsp;好，我相信通过今天的分享，我们已经知道如何用“三步感谢法”表达感谢了。\u003c/p>\u003cp>&nbsp;那就是清楚地告诉对方：因为他们所做的事，给我们带来了哪些帮助，我们又是什么感觉。\u003c/p>\u003cp>&nbsp;学以致用，方能致远！今天我的TF1-1分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1576211292000,"updated_at":1576240779000,"ria":true},{"id":8342,"topic":"用非暴力的方式交流","learn_goal":"学习使用表达愤怒的四个步骤","remark":"本《非暴力沟通》作者是马歇尔·卢森堡，是一位国际非暴力沟通中心创始人，全球首位非暴力沟通专家。这本书介绍了以 一种以4要素为核心的可以让爱融入生活当中的非暴力沟通模式。\r\n这本书是社会心理学的入门畅销书，2003年出版，至今畅销不衰。该书中文版已入选香港大学推荐的50本必读书籍。","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"赵红","city":"青岛"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家晚上好，很开心，再次来开发区参加拆书活动，开始自己的成长之旅，我是赵红，一个心态年轻的知天命的人，一个永远在学习路上的人，一个追求健康幸福的人。\r\n下面我给大家介绍，今天我要拆的这本书《非暴力沟通》。\r\n作者马歇尔博士在2000年获得国际倾听组织年度倾听者；\r\n2004年，获得健康快乐神圣组织颁发的国际和平祈祷者和平者奖；\r\n2006年获得地球村基金会和平之桥奖和国际联合教会协会神眼之光社会奖。\r\n这本书名的来历是因为60年代正处于冷战时期，在那种环境下，马歇尔借用了甘地的非暴力这个词，因为这个学问与语言有紧密关系，于是他把暴力和语言结合在一起变成了一个学问。\r\n马歇尔博士说非暴力沟通这个名称不能涵盖这本书的含义，这个含义应该称为基于需要的意识。 \r\n这本书在豆瓣的评分达到8.5分，并被选入香港大学推荐的50本必读书籍之列。 \r\n对比其他的沟通类书籍，这本书不仅仅有实用的沟通技巧，而且更侧重于挖掘语言背后双方所蕴含的情感与期望。 \r\n通过看到、听、到感觉到自己和他人的内在需要,来找到策略的一种沟通方式.\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":11976,"quote":"\u003cp>表达愤怒的四个步骤\u003c/p>\u003cp>现在让我们看看非暴力沟通表达愤怒的具体步骤\u003cstrong>。首先\u003c/strong>，停下来除了呼吸，什么都别做。我们避免采取行动去指责或惩罚对方。我们只是静静地体会自己。\u003cstrong>接着\u003c/strong>，想一想是什么想法使我们生气了。例如，无意中听到某个人的谈话后，我们认为由于种族的原因自己遭到了排斥。这时，我们体会着愤怒，并留意脑海中盘旋的想法:“这太不公平了！她这是种族歧视!”我们知道，像这样的想法是尚未满足的需要的可悲表达。于是，\u003cstrong>接下来\u003c/strong>，就去了解自己想要满足的需要。如果我把某个人当作种族主义者，我的需要也许是接纳、平等、尊重或联系。\u003c/p>\u003cp>为了充分表达自己，我们现在需要张开嘴，说出我们的愤怒——怒火此时已被转化为需要以及与需要相联系的情感。\u003cstrong>然而\u003c/strong>，表达此时的感受也许需要很大的勇气。对我来说，生气并冲着人们嚷“你们这是种族歧视”是很容易的。事实上，我甚至还会觉得高兴。但是，倾听心底深处的感受和需要却很可能引发不安。为了充分表达愤怒，我们也许会对那个人说:“&quot;你走进房间后，和其他人都打了招呼，却没有和我说话现在你又在议论白种人，注意到这些，我的胃有些不舒适，而且很害怕，因为我很看重平等。我想请你告诉我，听到我说这些，你的感觉怎么样？”\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>WHAT\u003c/p>\u003cp>朋友们，在生活中你愤怒过吗？\u003c/p>\u003cp>但自己有愤怒的情绪时，你是怎样处理这份愤怒的情绪？\u003c/p>\u003cp>你自己处理愤怒的情绪的方法，让你与对方的关系是更近还是更远了？\u003c/p>\u003cp>WHY\u003c/p>\u003cp>很多人认为愤怒是不好的，其实情绪没有好坏对错之分，只是一份礼物。愤怒也是份礼物，激发我们去了解，引起我们这种反应的未被满足的需要是什么？是对自己一份很好的提醒，提醒自己外在的人或事与自己的内在价值观和规条发生矛盾了，就像汽车仪表盘上的警示灯，它提供了关于引擎的需要方面的有关信息，看到警示灯亮时，你不会去隐藏、也不会忽略，而是会减速，弄明白这灯想要告诉你什么，愤怒与警示灯的功能一样。\u003c/p>\u003cp>HOW\u003c/p>\u003cp>今天主要分享觉察到自己对人或事有愤怒情绪时怎么做？\u003c/p>\u003cp>第一步，觉察到自己愤怒了，先让自己停下来，除了呼吸什么都不做，或是自己离开让愤怒的环境。\u003c/p>\u003cp>第二步，是什么让自己生气了？是对方这个人还是这件事情？外在的世界与自己内在的价值观和规条，哪个部分发生了冲突？\u003c/p>\u003cp>第三步，去看到并了解自己想要满足的需要，与自己的内在连接，去看到自己愤怒背后的需要是什么。\u003c/p>\u003cp>第四步，表达自己的感受和需要，表达时知道对方所做的什么事与满足你的需要相冲突，表达你此刻的感受，表达你的需要没有得到满足时的感受，最后表达你想要对方怎么做。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>A1:\u003c/p>\u003cp>拆书家提问：\u003c/p>\u003cp>下面我们有请胡老师来讲一下他在生活中遇到的这个让他感觉到愤怒的事情\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>半个月前，教体局来学校现场勘查，指出了一些问题，要求我们整改，原本教体局方面的很多事情都是由夫人去对接的，但是她一转身去成都学习了，在去成都学习之前在家里的时候说好，去成都学习没有问题，需要把需要解决的事情，提前联系好，夫人表达说：与教体局沟通的所有事情由她来解决，可是到了成都以后，来电话说上课太忙，没有时间，无法和教体局的人员进行沟通，所以这件事情需要我来出面解决，听到这个消息的时候，我很生气也很愤怒，没有办法，自己也是硬着头皮去和教体局方面去沟通相关事宜，最终的沟通效果也没有达到我们想要达到的预期。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>今天在听到了表达愤怒的这4个步骤以后，在夫人回到青岛的时候你会怎么做呢？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>首先我会让自己的情绪平复下来，去欢迎她回到青岛。我知道我生气和愤怒的原因是源于他不负责任的这份表现，你一拍屁股走了，家里还有十几个人需要吃饭呢，需要我们把我们这个学校办好，要对所有的员工负责。同时我也看到自己，我也不喜欢去做这种求人的事情，我也需要尊重我自己。我也会向他表达，如果你再和在工作中有为难的事情的时候，有你不想做的事情可以提出来，我们可以商量着来。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1562555958000,"updated_at":1562556321000,"ria":true},{"id":8336,"topic":"运用非暴力沟通的方式表达和倾听","learn_goal":"学习者能够运用非暴力沟通四要素表达自己的不满和倾听他人的不满","remark":"","level":"TF2-4","duration":30,"status":30,"type":0,"chaishujia":{"username":"叶叶","city":"济南"},"club":{"name":"济南海右分舵","city":"济南"},"prologue":"\u003cp>不破不能立，不拆不成器。欢迎大家来拆书，我是叶叶。我的三个标签是三个生——拆书生，学生，医生。今天能和大家一起在这里学习，可谓三生有幸，希望今天我分享的内容可以对大家有所帮助。\r\n因为过一会儿会有小组讨论的环节，我们先分一下组，每桌为一组，跟你的神队友击一下掌吧。&nbsp;\u003c/p>\u003cp>\u003cstrong>【介绍图书】\u003c/strong>\u003c/p>\u003cp>我先为大家介绍一下今天的书籍。\u003c/p>\u003cp>F特征（Feature）：我先为大家介绍一下《非暴力沟通》这本书。他的作者是马歇尔 卢森堡博士。他是非暴力沟通的创始人。他写《非暴力沟通》这本书的目的是想帮我们减少生活中普遍存在的语言暴力，比如气话、狠话、各种不中听的话、自责的话等等。《非暴力沟通》认为，语言暴力，其实是披着狼皮的爱。看似暴力的语言背后，是人们没有被满足的需要和请求。采用非暴力沟通的方式，恰当地表达或倾听人们的需要和请求，那么狼皮就可以被揭开，爱，就会在沟通中自然地流淌。\u003c/p>\u003cp>A 优势（Advantage）：这本书是沟通类图书中的畅销经典，是香港大学推荐的50本必读书籍之一。与其他同类书籍相比，这本书更注重实际成效，也就是读者的沟通水平是不是真的得到提升。每讲一章作者就提供一些示范和自测，方便读者边读边练，实现知行合一。\u003c/p>\u003cp>B利益（Benefit）：\u003c/p>\u003cp>B1这本书可以在积极的情绪、关系和成就两大方面提升我们的幸福指数。如果你经常自责、沮丧，可以读读这本书，它可以教你如何让积极情绪多一点；如果你在生活和工作中经常遇到人际关系危机，它可以教你如何预防和化解这些危机，让我们在生活中拥有幸福美好的关系，在工作中聚集人脉能量，创造让自己满意的成果。\u003c/p>\u003cp>B2我们今天学习的重点放在关系和成就这个层面。你会在亲密关系中经常和最亲爱的人冷战或是大吵一架吗？你会在工作中与合作伙伴因为一点小事就闹得不欢而散吗？今天我们学习的两个拆页就会告诉我们，如何用不带伤害的方式化解人际间的冲突，从而打造出好的关系和工作成果。\u003c/p>\u003cp>今天的两个拆页分别讲沟通中的两个方面——表达自己和倾听他人。\u003c/p>\u003cp>先来看第一个拆页。\u003c/p>","ratings_count":2,"texts":[{"id":11967,"quote":"\u003cp>\u003cstrong>【拆页一】\u003c/strong>\u003c/p>\u003cp>现在请大家用1分钟的时间阅读。读完后请举手示意我一下。\u003c/p>\u003cp>\u003cstrong>选自《非暴力沟通》P\u003c/strong>6\u003c/p>\u003cp>为了彼此能乐于互助，我们专注于四个方面——非暴力沟通模式的四个要素。\u003c/p>\u003cp>首先，留意发生的事情。我们此刻观察到什么？不管是否喜欢，只是说出人们所做的事情。要点是，清楚地表达观察结果，而不判断或评估。接着，表达感受，例如受伤，害怕，喜悦，开心，气愤等等。然后，说出哪些需要导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。&nbsp;\u003c/p>\u003cp>举例来说，一位母亲可能对她处于青春期的儿子说：“菲利克斯，看到咖啡桌下的两只脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。”&nbsp;\u003c/p>\u003cp>接着，她立即提出非暴力沟通的第四个要素——具体的请求：“你是否愿意将袜子拿到房间或者放进洗衣机？”这一要素明确告知他人，我们期待他采取何种行动，来满足我们。\u003c/p>\u003cp>这样,这位母亲就清楚地说出非暴力沟通的四个要素。借助这四个要素诚实地表达自己,是非暴力沟通的一个方面。\u003c/p>","explains":"\u003cp>【学习目标一】希望学完这个拆页后，我们在对别人表示不满时，能够运用&quot;观感需求&quot;四步法进行表达，既不委屈自己，也不伤害他人。\u003c/p>\u003cp>\u003cstrong>【W\u003c/strong>\u003cstrong>HAT\u003c/strong>\u003cstrong>】\u003c/strong>作者借助一个母亲和儿子沟通的案例向我们展示了，如何在自己对别人感到不满时，利用非暴力沟通的四个要素清楚地表达自己。是哪四个要素呢？观察、感受、需要和请求。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>HOW】\u003c/strong>具体怎么运用这四个要素呢？有四个步骤——\u003c/p>\u003cp>（1）描述观察的结果；（2）表达内心的感受；（3）说出真正的需要；（4）提出具体的请求。简称“观感需求”。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>当我们大多数人发现自己对别人的言行不满时，通常会怎么做？\u003c/p>\u003cp>第一种是直接发泄自己的不满；\u003c/p>\u003cp>第二种是憋着不说，忍忍过去了。\u003c/p>\u003cp>可是，这两种做法的结果是很糟糕的，它不止没有解决问题，还会对双方都造成伤害。\u003c/p>\u003cp>【意译原文案例】\u003c/p>\u003cp>给大家举一个例子，我们可以如何把非暴力沟通的方式运用在生活中：小张是一名干练的白领，工作很认真，领导也很器重她，上个月把一个很重要的项目交给她负责，小张很重视这项任务，连续一个月天天加班，也没顾得上给家里打电话。昨天，小张在工作的时候突然接到爸爸打来的电话，爸爸说，女儿啊，你最近有回家的打算吗？小张当时正忙得焦头烂额，被这一通电话打断了思路，就对爸爸说，&quot;爸爸，我正忙着呢，哪有功夫回家？不跟你说了，先挂了啊……&quot;留下爸爸一个人在电话那头落寞。小张虽然当时生气，可是事后也觉得有些后悔。\u003c/p>\u003cp>（正例）那如果按照书中的建议，小张可以运用“非暴力沟通”的方式去沟通了：首先，客观观察：爸爸，我在有很多工作需要处理、非常紧张、压力非常大的时候接到你的电话问我关于回家的事，然后表达真实感受：我感到有点着急和生气，表达根本需求：因为我需要安静的环境专注地工作，我很看重工作的质量：最后提出请求：所以以后你可不可以晚上七点以后给我打电话？这样说完，小张的火气可能就能消一半，爸爸也会理解女儿的紧张，并配合女儿的工作。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>你可能会觉得，这么说话真费劲。确实，一开始应用的时候会觉得别扭，但是如果可以学会并运用这种方法，从长远来看，它是在为你的关系账户里存款而不是取款，是投资而不是负债。总之，虽然麻烦，但是值得。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1 激活经验】\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>现在我们来趁热打铁，练习一下刚刚学到的技能，请大家认真回忆一下有没有这样的经历:你排了很久的队，突然有人插队到你的前面；或者，你跟朋友约好一个时间见面，结果他晚到了半个小时；又或者，你勤勤恳恳地工作，但是你的领导却把升职加薪的机会给了另一个偷奸耍滑的同事，类似的，请你回想一下，上个周，有没有某个人做的某件事让你感到不满？那是什么时候，又是因为什么事情呢？请想一想，你当时是怎么跟对方沟通的？\u003c/p>\u003cp>【指令】下面给大家1分钟时间思考，然后在小组内分享。\u003c/p>\u003cp>\u003cstrong>【A1+\u003c/strong>\u003cstrong>反思加工】学习者拆为己用\u003c/strong>\u003c/p>\u003cp>如果你可以穿越到过去，回到那个时候，你会如何运用非暴力沟通的4个步骤跟对方沟通呢？\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>学习者一：我孩子课外辅导班的老师这两个月总是调课，我对此非常不满，上周末我跟他交流的时候情绪有些激动，跟他抱怨了一通，我看他也挺尴尬的。如果我可以回到过去，我会对他说，老师你最近两个月上课，总是提前十分钟通知我们，这个月你已经调了六次课了，这样非常影响我们家长时间的安排，希望下次你可以提前通知我们家长。\u003c/p>\u003cp>拆书家：谢谢你的分享，非常棒！你对自己的观察和请求都描述地非常清晰准确，为你点赞！如果能把自己的感受（比如是生气还是着急？）以及需要或是价值观（比如我看重守时/承诺/效率/计划）说出来，相信对方会更容易理解你并相应地做出改变。\u003cbr>\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>刚刚我们已经学会理解自己的不满并表达自己的不慢了，接下来我们就要学习用非暴力沟通倾听他人的不满并给出反馈了。非暴力沟通不仅能用于表达自我，而且还能用来倾听他人。这两个学习目标是递进关系。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":11969,"quote":"\u003cp>这个拆页来自《非暴力沟通》第90-91页。现在请大家用2分钟的时间阅读。读完后请举手示意我一下。\u003c/p>\u003cp>\u003cstrong>选自《非暴力沟通》P\u003c/strong>90-91\u003c/p>\u003cp>非暴力沟通建议我们使用疑问句来给予他人反馈。这将便于他人对我们的理解作出必要的补充。我们的问题可以集中于以下几个方面：&nbsp;\u003c/p>\u003cp>1．他人的观察：“上周我有三个晚上不在家，你说的是这回事？\u003c/p>\u003cp>&nbsp;2．他人的感受及需要：“你很灰心？你希望得到肯定是吗？”\u003c/p>\u003cp>&nbsp;3．他人的请求：“你是不是想请我帮你预订酒店？”\u003c/p>\u003cp>&nbsp;请注意上述问题与以下问题的区别：\u003c/p>\u003cp>&nbsp;1．“你说的是什么事？”\u003c/p>\u003cp>2．“你现在心情怎么样？”“为什么你会有那样的感觉？\u003c/p>\u003cp>&nbsp;3．“你希望我怎么做？”\u003c/p>\u003cp>&nbsp;第二组问题并不需要我们用心体会他人。这些问题看起来很直接，但根据我的经验，它们并不是获得信息的最佳方式。这样的提问方式，就像心理咨询师在帮助客户，容易产生距离感。如果我们真的要这么问，在提问前先提及我们的感受和需要，将鼓励人们主动表达自己。例如，如果我们想问别人“你说的是什么事，我们可以说“我有些困惑。我想知道你是指哪件事。告诉我好吗”虽然，这并不是必要的———有时，我们的语气已经表明了我们的感受和需要；但我还是建议主动表达感受和需要，特别是情绪很激烈的时候。\u003c/p>","explains":"\u003cp>【学习目标二】希望学完这个拆页后，我们在遇到别人表示对我们的不满时，我们能够运用“事情要做”四步法倾听他人并给出反馈。\u003c/p>\u003cp>WHAT：倾听他人，是沟通中被很多人忽略但却至关重要的环节。 但是，非暴力沟通告诉我们，倾听并不是竖着耳朵听就完事了，而是要用合适的语言引导对方说出来让我们听。\u003c/p>\u003cp>WHY:&nbsp;因为大多数人没有接受过非暴力沟通的训练，不能清晰理性地表达出自己的需求。这就需要我们通过非暴力沟通的方式帮助他们梳理出背后真正的需求。\u003c/p>\u003cp>【HOW细化步骤】具体怎么做呢？书中虽然没有详细的步骤，我总结了一下，其实它的步骤可以用4个字来概括——“事情要做”，他们分别对应四个问题。\u003c/p>\u003cp>事，指的是事情，对方是因为什么事情有负面情绪的？————你说的是这个事情吗？\u003c/p>\u003cp>情，指对方的感受，你是不是感到很————？比如生气，委屈，恼火？\u003c/p>\u003cp>要，指需要，价值观，你是不是需要/看重————？比如需要聆听，理解，肯定？\u003c/p>\u003cp>做，指对方希望自己做什么，你是不是希望我能够————做？\u003c/p>\u003cp>当然，我们在实际应用的时候，不要求面面俱到。可以只针对其中的一两个方面来进行提问反馈。\u003c/p>\u003cp>【适用边界】这种非暴力沟通的倾听和反馈的方式什么时候用呢？我认为它适用于非紧急情况下，对方对我们表示不满的情境中。\u003c/p>\u003cp>【举个例子】\u003c/p>\u003cp>举个例子，一位新邻居因为急事借走了小明家的车，小明的爸爸知道这件事后骂他，你怎么能把车借给陌生人？你这个蠢货！如果用非暴力沟通的方式，小明可以这样反馈——爸爸，我把车借给了咱们的新邻居，你是不是感到很担心，很着急，很生气呀？因为你很看重安全对吗？你希望我现在就把车要回来吗？\u003c/p>\u003cp>【预防异议】也许你会担心，如果我们反馈得不准怎么办呢？会不会引起对方的反感？这取决于你的初心，如果你是真诚地关心对方，全然地接纳对方，而不带评价和指责，那么你的反馈会让对方感到安全舒适并愿意与你交流。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3 促动学习者现场演练】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场\u003c/strong>\u003cstrong>景设\u003c/strong>\u003cstrong>计\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>我们刚刚学习了非暴力沟通的倾听反馈法。现在一起做个演练！请大家认真听一下要演练的场景：\u003c/p>\u003cp>相信大家都记得《西游记》中“孙悟空三打白骨精”的故事，唐僧对悟空不分青红皂白就杀害了3条生命感到非常不满。于是，他生气地说：“你走吧！我不要你这个徒弟了。”\u003c/p>\u003cp>面对这样的情况，请大家思考一下，孙悟空是如何运用“非暴力沟通”的方式给唐僧反馈呢？\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>现在，请两个人一组，进行演练。一个人扮演唐僧，另一个人扮演孙悟空，讨论和编写剧本的时间为15分钟，编写完之后，请分享一下。\u003c/p>\u003cp>【剧本案例】\u003c/p>\u003cp>唐僧：你走！一点出家人的思想都没有！走！\u003c/p>\u003cp>悟空：师父，你看到我滥杀无辜了三个人，你是不是很生气？\u003c/p>\u003cp>唐僧：你……你……出家人走路不伤蝼蚁命，你一下打死了三个人……你不是我的徒弟！你走吧！\u003c/p>\u003cp>悟空：师父，你是希望我在打死他们之前向你证明他们是妖怪吗？\u003c/p>\u003cp>唐僧：他们明明是三个人！你说他们是妖怪，他们就是妖怪了？\u003c/p>\u003cp>悟空：师父，以后我们再遇到这样的情况时，经过你的确认他是妖怪并且同意之后，我再打死他们可以吗？\u003c/p>\u003cp>【反馈】\u003c/p>\u003cp>好的，谢谢分享，非常精彩。“悟空”能够运用到我们刚刚所学到的非暴力沟通的方法来给人反馈，比如针对唐僧的感受提问“你是不是很生气？”、针对唐僧的请求“以后征得同意获得准许以后再打死妖怪可以吗？ ”。如果在需要或是价值观的层面也反馈一下的话效果可能会更好。\u003c/p>\u003cp>【A2 催化学习者应用】\u003c/p>\u003cp>下面我们进入规划应用环节。\u003c/p>\u003cp>【分步催化1】&nbsp;日常生活中有很多时候会遇到别人对自己不满的情况，比如客户会因为你没有提供给他满意的产品或服务而不满，领导会因为你没有按时完成项目进度而发怒、家人会因为你整天忙着工作没时间陪他们而抱怨……我们设想一下，在未来一周的生活中，你将会遇到以上哪类场景呢？\u003c/p>\u003cp>给大家2分钟时间思考一下，一会请小伙伴们进行分享。注意：只需要说出场景即可。\u003c/p>\u003cp>【分步催化2】\u003c/p>\u003cp>刚刚各位已经跟小伙伴分享了未来可能会发生的一个情景，假如这个场景真的发生了，你来设想一下对方会跟你说什么？你的反馈又是什么呢？你能不能运用今天学到的非暴力沟通的方式来反馈一下呢？接下来，请小伙伴先在小组内分享一下。\u003c/p>\u003cp>【学习者案例一】\u003c/p>\u003cp>场景：B未来一周可能会遇到他回家后晚睡，妻子（A扮演）抱怨他。\u003c/p>\u003cp>应用：\u003c/p>\u003cp>A：你看看这都几点了，你老是这么晚睡都影响宝宝了！\u003c/p>\u003cp>B：老婆，你是不是觉得很生气？\u003c/p>\u003cp>A：当然了，你这样影响宝宝会影响他的发育的！\u003c/p>\u003cp>B：老婆，你是不是希望我早点睡？\u003c/p>\u003cp>A：是啊，你从店里回来也没多少事情啊，就不能早些睡觉？这样对你自己的身体也好啊。\u003c/p>\u003cp>B：老婆，你希望我几点以前睡觉？\u003c/p>\u003cp>A：10点半以前我觉得比较合适。\u003c/p>\u003cp>B：好的老婆，我安排一下时间，明天尽量10点以前睡觉。\u003c/p>\u003cp>\u003cstrong>【回应反馈】\u003c/strong>\u003c/p>\u003cp>谢谢你的分享，丈夫已经在有意识地运用我们刚刚所学到的非暴力沟通的方法来给妻子反馈了，“是不是觉得很生气？”询问了妻子的感受；“是不是希望我早点睡？”询问了妻子具体的请求。非常棒！如果说还有可以提高的空间，可以把“事情要做”里面的“事”和“要”完善一下，比如“老婆，你是不是在说我这几天回来总是11点以后才睡觉？”询问事情；“你是不是很重视我们的健康？”询问需要或是价值观。这样一来给对方的反馈更明确，沟通效果可能会更棒。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>强\u003c/strong>\u003cstrong>有力的结\u003c/strong>\u003cstrong>语】 \u003c/strong>\u003c/p>\u003cp>我们今天的学习就接近尾声了。一起来回顾一下，我们今天一共学习了两个拆页，讲到了非暴力沟通四要素在表达自己的不满和倾听他人的不满这两种情境中的应用。具体来讲，在第一个拆页里，我们学习了如何用“观感需求”四步法表达自己的不满，在第二个拆页里，我们学习了如何用“事情要做”四步法倾听他人的不满并给出反馈。希望大家在今后的生活和工作中多多练习我们今天学到的方法，成为非暴力沟通的达人，建立和谐的生命体验。感谢大家的配合与支持，谢谢大家！\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1562508080000,"updated_at":1563162193000,"ria":true},{"id":7318,"topic":"如何用非暴力沟通法反馈","learn_goal":"2-3过级","remark":"用非暴力沟通法反馈，减少误会，让沟通更融洽。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"王丽珍","city":"邯郸"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>技能点要求：设定学习目标，学习目标包含学习者可被观察到/测量到的行为或动作，现场学习者设计清晰体现了该学习目标。\u003c/strong>\u003c/p>\u003cp>【开场】大家好，我是美丽人生，愿大家在拆书过程中有一个美丽心情。在接下来的拆书活动我们依然会有小组内讨论分享环节，按照今天的到场人数以及活动的需要，每两认为一组，分为4组，这边的最后一组为3人，组长分别为我的师姐常乐和我们的舵主刘犇。\u003c/p>\u003cp>今天的拆书主题是“给他人反馈”。选自《非暴力沟通》这本书第90---91页。\u003c/p>\u003cp>\u003cstrong>（观察点二：所选图书是实用类或理论类图书）\u003c/strong>\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次的RIA现场学习后，学习者能够通过他人的观察、感受、需要和请求进行疑问句反馈他人四步法进行反馈，让表达者更深的认识自己当下的状态以及给与聆听者补充和纠正，从而建立和谐的沟通关系。\u003c/p>\u003cp>(\u003cstrong>观察点四：学习目标包含学习者可被观察到/被测量到的行为或动作，现场学习者设计清晰体现了该学习目标。)\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点要求：介绍图书FAB，清晰辨别出F、A、B\u003c/strong>\u003c/p>\u003cp>我今天要拆解的片段来自《非暴力沟通》一书。\u003c/p>\u003cp>【F特征】《非暴力沟通》这本书的的作者是马歇尔.卢森堡，美国著名心理学家。这本书讲了沟通时的具体步骤：观察+感受+需求+请求。被联合国誉为全球非暴力沟通的实践之一。\u003c/p>\u003cp>【A优势】本书与其他沟通类图书相比，这本书每个章节都有练习的设置和具体的实例演示，能够帮助读者轻松掌握书中的非暴力沟通方式。\u003c/p>\u003cp>【B1利益】这本书告诉我们，通过运用非暴力沟通，我们不再试图分析自己或他人有什么毛病，而是用心去了解我们的需要，这样我们的内心将逐渐变得温和。\u003c/p>\u003cp>【B2利益】通过今天的片段学习，你可以学会在沟通中如何更加有效的给他人进行反馈，进而建立更加和谐的沟通体验。\u003c/p>\u003cp>（\u003cstrong>观察点五：在\u003c/strong>\u003cstrong>FAB\u003c/strong>\u003cstrong>介绍法中，能够清晰辨别出\u003c/strong>\u003cstrong>F\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>A\u003c/strong>\u003cstrong>、\u003c/strong>\u003cstrong>B\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>接下来就让我们进入今天的拆书学习，请大家用2分钟时间阅读原文片段，阅读完毕后请举手示意我。\u003c/p>","ratings_count":1,"texts":[{"id":10755,"quote":"\u003cp>\u003cstrong>技能点要求：所选拆页包括HOW的内容，且总内容未超过2页图书内页\u003c/strong>\u003c/p>\u003cp>在倾听他人的观察、感受、需要和请求之后，我们可以主动表达我们的理解。如果我们已经准确领会了他们的意思，我们的反馈将帮助他们意识到这一点。反之，如果我们的理解还不到位，他们也就有机会来纠正我们。此外，这样做还有助于人们体会自己的状况，从而深入了解自己。\u003c/p>\u003cp>非暴力沟通建议我们使用疑问句来给予他人反馈，这将便于他人对我们的理解作出必要的补充。我们的问题可以集中于以下几个方面：\u003c/p>\u003cp>1.他人的观察：“上周我有三个晚上不在家，你说的是这回事儿？”\u003c/p>\u003cp>2.他人的感受及需要：“你很灰心？你希望得到肯定是吗？”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3.他人的请求：“你是不是想找我帮你预定酒店？”\u003c/p>","explains":"\u003cp>\u003cstrong>新技能：【I】拆书家讲解引导，给出比原书拆页更加细化的行动步骤，或者将书中的案例进行了意译\u003c/strong>\u003c/p>\u003cp>【what】这个片段教会我们使用疑问句来给与他人反馈，就是在倾听后，通过观察、感受、需要、请求四个方面使用疑问句进行反馈，确认我们是否完全get到对方表达的点。\u003c/p>\u003cp>【why】为什么要用疑问句式进行反馈？第一个方面是：如果我们已经准确无误的完全领会对方表达的意思，我们的反馈可以让对方意识到我们完全get到了她讲的点，有利于深入沟通。第二个方面是：在倾听内容的理解上有了偏颇或者遗漏项，可以得到表达者的及时的补充与纠正。\u003c/p>\u003cp>第三个方面是：可以让表达者觉察当下自己的状态，深入了解自己要表达的内容是否按照内心深处的想法表达出来。\u003c/p>\u003cp>【how】细化原文步骤：那具体我们应该如何进行反馈呢？具体包含以下4步：\u003c/p>\u003cp>\u003cstrong>第一步、关注当下自己的情绪。尽量做到让自己的心情平和，这样避免开口情绪对话（参\u003c/strong>\u003c/p>\u003cp>\u003cstrong>考句式：亲爱的自己当下你还好吗？———一定是有原因的，我们一起听听缘由好吗？你真棒。（给出对应对方的情绪的事。例如：\u003c/strong>亲爱的自己你还好吗？她着急一定有原因，静下来听听好吗？你做的真棒。（目的是让自己情绪温和\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步、确认他人的观察。\u003c/strong>\u003cstrong>（参考句式：————你说的是这回事吗？（给出对应的事件。例如：\u003c/strong>上周我没能赴，你是不是说的这件事？\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步、确认他人的感受和需要：\u003c/strong>\u003cstrong>（参考句式：你是不是感到--------\u003c/strong>\u003cstrong>？你希望得到需求的----------\u003c/strong>\u003cstrong>？（给出能够对应对方感受和需要的反馈词，比如：1\u003c/strong>\u003cstrong>、受到尊重感觉很高兴、失望、沮丧、灰心、难过、开心、愉悦、满足…..\u003c/strong>\u003cstrong>）（2\u003c/strong>\u003cstrong>、给出能够满足对方需求的反馈词。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>例如：“\u003c/strong>你是不是很不高兴？因为你觉得我没有尊重你的一片好意？\u003cstrong>）\u003c/strong> \u003c/p>\u003cp>\u003cstrong>第四步、确认他人的请求：\u003c/strong>\u003cstrong>（参考句式：你是不是想请我帮你做----------\u003c/strong>\u003cstrong>（给出能够表达具体需求的相关行为词）例如：\u003c/strong>你是不是想让我跟她们也成为朋友？\u003c/p>\u003cp>通过以上的步骤，我们就可以做到非暴力沟通给他人反馈，进而达到高效沟通，建立和谐的关系。值得注意的是，我们也要根据倾听内容的不同，也可以反馈其中的某一方面。\u003c/p>\u003cp>【意译案例】如何应用，举个例子。\u003c/p>\u003cp>&nbsp; 过年期间，我的朋友蔡姐打电话告诉我，她和同学聚会，邀请我也过去参加。曾经蔡姐说过有机会把她要好的朋友介绍给我，想让我融入她们的朋友圈有更多交流。由于我需要在家照顾老妈，另外我也不太喜欢和陌生人聚，所以没去参加聚会。事后一周蔡姐突然打电话来跟我吼道：“你现在是不认我这个姐了啊，请也请不动，样儿大了啊。我当时就给予蔡姐这样的反馈：\u003c/p>\u003cp>我：亲爱的自己静下来，慢慢听一下对方的情绪来自哪里好吗？你真棒。（照顾自己的情绪）\u003c/p>\u003cp>我：“上周你让我参加你和同学的聚会我没去，你说的是不是这回事？（他人的观察）\u003c/p>\u003cp>蔡姐：跟你说了一定过来，一定过来，结果你还是没来。\u003c/p>\u003cp>我：你心里是不是很失落，是不是感觉我没有领会你一片好意?（他人的感受和需要）\u003c/p>\u003cp>蔡姐：对啊，我都跟人家说了，我要带上我的好朋友跟你们互相认识。这样我们再去郊游、k歌、聚餐都可以一起了。\u003c/p>\u003cp>我：你是不是想让我跟她们也成为朋友，有更多沟通、交流和接触？（他人的请求）\u003c/p>\u003cp>蔡姐：对啊， 我很看重你们这些朋友，你却不怎么上心。\u003c/p>\u003cp>我：“放心吧蔡姐，以后有的是机会，等三月你家过会的时候说不定就能见到，那时候介\u003c/p>\u003cp>绍认识、交流也不迟，出去一起玩的机会也会很多的。\u003c/p>\u003cp>蔡姐：情绪好很多，急忙说，别忘记你说的啊，三月会一定来啊。\u003c/p>\u003cp>\u003cstrong>【where\u003c/strong>\u003cstrong>】\u003c/strong>疑问句给他人反馈的适用范围，在倾听他人观察、感受、需要和请求之后在我们用心体会他人时使用。当然，也不是什么场合都需要这样的反馈，比如时间紧迫，或者情况紧急亦或者是集体会议室时间时，都不适合我们用这样的方式反馈。\u003c/p>\u003cp>（防止异议）有的小伙伴也许会说，这样的反馈方法太浪费时间了，以前都是直截了当的问对方说的是什么事情？以及有啥想法那不是也挺好的吗？请你试着回忆一下是否出现过这样的情况，当对方跟你描述她的观察和感受时，我们很认真的听完后，掏心掏肺的直接给出自己的评论观点，结果惹得对方很生气，觉得我们不够理解她此时的心情和感受，让人觉得交流不在一个平台上，这时最好的结果也只是对方停止与我们的进一步交流。\u003c/p>\u003cp>\u003cstrong>（观察点六：【I】环节，给出了比原书拆页更加细化的行动步骤，或者将书中的案例进行了意译。\u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>【新技能点要求1】给出了一个非常具体、确定场景，学习者可以在此场景中演练、讨论或应用新学技能。\u003c/strong>\u003c/p>\u003cp>通过刚才的学习，我相信大家对“疑问句给他人反馈四步法”有了一定的理解。现在让我们进入指定场景演练环节，看看我们学习的效果如何？请大家认真听一下要演练的场景，运用刚学的“疑问句给他人反馈四步法”组织对话演练。\u003c/p>\u003cp>过年期间，小王的右脚后脚跟处不知什么原因疼的不能着地，走起路来一瘸一拐的。她父亲催促我每天泡脚并用理疗灯烤烤（老爸家有一个理疗灯）嘱咐小王回家时把灯也带走，由于走的匆忙小王就忘记带回去了，第二天一进父亲的家门，小王就遭到她父亲一顿发脾气：“还是疼的轻，说啥没听过……..\u003c/p>\u003cp>针对小王这样的一个状况，如果你是小王的话应该如何运用“疑问句给他人反馈四步法”给予父亲反馈呢？现在，请两人一组，进行演练。一个人扮演小王的角色，另一个人扮演父亲角色，你们在小王和父亲见面开始有情绪抱怨的时候，用“疑问句给他人反馈四步法”对他进行反馈。下面给大家5分钟时间进行演练。\u003c/p>\u003cp>现在排练结束，演练正式开始。时间为5分钟。\u003c/p>\u003cp>\u003cstrong>（观察点七：【\u003c/strong>\u003cstrong>A3\u003c/strong>\u003cstrong>】环节，给出了一个非常具体、确定场景，学习者可以在此场景中演练、讨论或应用新学技能\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点要求2：】使用【A3】技能点的环节指令清晰，学习者可以根据拆书\u003c/strong>\u003c/p>\u003cp>\u003cstrong>家设定的案例场景，进行小组讨论、应用知识点并能形成一个解决方案，或者应用知识点进行组内角色扮演\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者演练\u003c/strong>记录：\u003c/p>\u003cp>\u003cstrong>彦晴：\u003c/strong>( 内心默默的说：“亲爱的自己我爱你，静下来，一起听听老爸情绪背后的需要好吗？（目的：让自己面对情绪时不被对方所带入情绪，让自己静下来。背景：一进门面对突如其来的发脾气)\u003c/p>\u003cp>\u003cstrong>彦晴-：\u003c/strong>“爸，昨天您让我拿走理疗灯我却没拿，您说的是这回事吧？--\u003cstrong>确认他人的观察\u003c/strong>\u003c/p>\u003cp>\u003cstrong>向日葵：\u003c/strong>昨天还一直提醒你带回去晚上接着理疗，还告诉你别少于半小时，这可倒好，你带也没带。\u003c/p>\u003cp>\u003cstrong>彦晴-\u003c/strong>\u003cstrong>：\u003c/strong>“您心里是不是又心疼又很担心，怕拖的时间久了不好恢复？\u003cstrong>-----\u003c/strong>\u003cstrong>确认他人的感受\u003c/strong>\u003c/p>\u003cp>\u003cstrong>向日葵：\u003c/strong>“是啊，每天看你的脚疼的不敢着地，赶紧让它好了不清了。如果理疗不见轻还得再去医院看看，拖的时间久了不好恢复可咋整呀？\u003c/p>\u003cp>\u003cstrong>彦晴-：\u003c/strong>“所以您希望我对自己的脚疼重视起来，是吗？\u003cstrong>--\u003c/strong>\u003cstrong>确认他人的需要\u003c/strong>\u003c/p>\u003cp>\u003cstrong>彦晴-\u003c/strong>\u003cstrong>：\u003c/strong>“如果不见好转您希望我能及时的再找大夫好好复查一下，得到及时的治疗对吗？\u003cstrong>--\u003c/strong>\u003cstrong>确认他人的请求\u003c/strong>\u003c/p>\u003cp>\u003cstrong>向日葵\u003c/strong>：“是啊，有病赶紧治，不能拖着，越拖越麻烦。\u003c/p>\u003cp>\u003cstrong>彦晴-\u003c/strong>\u003cstrong>：\u003c/strong>“嗯，知道了爸，我让姐姐重新咨询了另一个大夫，说可以能是肌肉拉伤，问题不大，让继续静养、泡脚、理疗，一周后看看情况是否好转，如果不见好转再过去拍个片，应该问题不大。\u003c/p>\u003cp>\u003cstrong>向日葵\u003c/strong>\u003cstrong>：\u003c/strong>“嗯，那这段时间就按医生讲的去做，别不当回事。（老爸的情绪好了很多，态度也和蔼亲切不少）\u003c/p>\u003cp>\u003cstrong>（观察点八：使用【\u003c/strong>\u003cstrong>A3\u003c/strong>\u003cstrong>】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并能形成一个解决方案，或者应用知识点进行组内角色扮演\u003c/strong>\u003c/p>\u003cp>【结尾】：谢谢小伙伴的精彩分享，通过今天的拆书学习，我们大家学会了运用疑问句给与他人反馈四步法，希望在你的生活和工作中能够积极的运用起来，让你和他人的对话变得更加顺畅，沟通更加和谐，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1551671755000,"updated_at":1551673253000,"ria":true},{"id":7204,"topic":"如何做一个快乐的人","learn_goal":"如何做一个快乐的人","remark":"大道","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"惊哲","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"df","ratings_count":0,"texts":[],"created_at":1549941013000,"updated_at":1549941013000},{"id":6700,"topic":"非暴力沟通的方式表达感激","learn_goal":"学习者能够运用感激三步骤向他人正确表示感谢，从感谢中双方获得","remark":"","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"壹佳壹","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"等下会有小组讨论，我们先分下组，糖果和毕风一组，千水和吴孟蒋一组，刚介绍过自己，简单介绍一下，一句话说，我是一个爱旅游，有好奇心的1级拆书家壹佳壹。\r\nB：介绍下图书是《非暴力沟通》，书中通过13个章节告诉我们如何退去精神暴力，用爱与人沟通，建立链接，并彼此理解。今天带给大家的片段关于如何更好的表达感谢，平时道歉会比较注意，感谢不会注意到。 \r\nA：本书在沟通艺术类书籍中位居第一名，在亚马逊的沟通艺术类排名中第一，豆瓣网有8.5的评分。 \r\nF: 作者马歇尔.卢森堡博士是国际和平非暴力沟通中心的创始人。书中指导我们在工作和生活中运用非暴力沟通方式，消除分歧，提高沟通效率。 \r\n【学习目标】：通过本次拆页的RIA现场学习后，达到学习效果，能够向他人正确表示感谢，让双方获得满足，提高人际关系。\r\n现在进入阅读原文片段环节，大家用1分钟阅读片段，阅读完后给我一个眼神，让我知道你已经读完啦","ratings_count":1,"texts":[{"id":10045,"quote":"\u003cp>片段《非暴力沟通》&nbsp;&nbsp;&nbsp;&nbsp;非暴力沟通表达感激的方式\u003cbr>\u003cbr>\u003c/p>\u003cp>非暴力沟通表达感激的方式包含三个部分：\u003c/p>\u003cp>1.对方做了什么事情使我们的生活得到了改善；\u003c/p>\u003cp>2.我们有哪些需要得到了满足；\u003c/p>\u003cp>3.我们的心情怎么样？\u003c/p>\u003cp>在表达感激时，这三个部分的先后次序并不重要；有时，我们甚至可以通过微笑或说声“谢谢”来表达这三个部分。然而，如果我们要确保对方能够明白我们的意思，那么，用语言具体地描述这三个部分是值得的。\u003c/p>","explains":"\u003cp>我用自己的话来理解并复述原文，进入我们的I&nbsp;环节。\u003c/p>\u003cp>\u003cstrong>【通常做法】\u003c/strong>\u003c/p>\u003cp>通常我们表达感谢会用谢谢，或者你真棒等普通的表扬方式。\u003c/p>\u003cp>\u003cstrong>【这样做的坏处】\u003c/strong>\u003c/p>\u003cp>如果用这样赞扬人方式，会带给人误解，不一定能get到你的意思，会引发以下3个反应：产生逆反心理，心存疑虑或误解我们的意思。\u003c/p>\u003cp>\u003cstrong>【负面例子】\u003c/strong>\u003c/p>\u003cp>举个我生活中未正确表达感激的例子，前段时间我在外面拆书，突然下起大雨，家人说送伞给我，当时很开心，有被照顾的感觉，见到家人时笑着走过去，这样做的坏处就是之后再也没有这样类似的行为。\u003c/p>\u003cp>\u003cstrong>【拆页行动建议】\u003c/strong>\u003c/p>\u003cp>如何正确表达感激，从3个方面：\u003c/p>\u003cp>1、事情（事情你做对了）：\u003cstrong>句式\u003c/strong>：你为我****，\u003c/p>\u003cp>2、影响（这件事情有什么影响）：\u003cstrong>句式：\u003c/strong>让我****，\u003c/p>\u003cp>3、情绪（我的情绪是什么）：\u003cstrong>句式：\u003c/strong>我感受到****。\u003c/p>\u003cp>表达感激的三个部分顺序可根据实际情况调整，可以先是心情，心情容易被发现及记住，再是对方做了什么，最后是提供了什么帮助，满足我的需求。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>：三个部分适用范围，比如家人、同事、朋友等等，像下属做了某件事情，进行赞扬，改善下属的工作积极性。当然如果是举手之劳的事情，比如毕风帮我递个笔等简单的事情上，可以简单说声谢谢或微笑。\u003c/p>","interaction":"\u003cp>\u003cstrong>【分享A1便签（激活经验）显象提问】\u003c/strong>\u003c/p>\u003cp>现在回想一下，在过去的一段时间里，有没有同事的一个举手之劳，给你的忙碌减轻松，想感谢他；朋友的一个贴心行为，让手足无措的自己倍感温馨，想让他知道自己有多暖心；家人无意识的一个帮忙，让孤独的你感受到来自家人的温暖，想鼓励他继续做类似的事情，这里的3个场景，哪个是你近期经历的，是什么时候，什么事情，请用30秒思考一下，在小组里用2分钟分享下。\u003c/p>\u003cp>现在请一个小伙伴分享一下自己的故事，用1分钟简洁分享自己经历的事情。\u003c/p>\u003cp>毕风案例分享：\u003c/p>\u003cp>家里对吃的不是特别的在意，很少做饭，如果老婆做饭，我一般会用谢谢、你是个好厨师等来称赞老婆，没有这么具体的表扬过老婆，在心里账号存了很多钱，但未表达出来。\u003c/p>\u003cp>\u003cstrong>【分享A1+便签（反思加工）】\u003c/strong>\u003c/p>\u003cp>曾经是否有遇到类似的经验，坐上时光机，回到当时场景，用今天学到的方式：\u003c/p>\u003cp>1、事情&nbsp;2、情绪&nbsp;3、影响 这三个方面描述，结合我之前的案例。\u003c/p>\u003cp>\u003cstrong>【正面例子】\u003c/strong>正确的对家人感谢，可以和家人这样说：“我感受到温暖（情绪），你为我送伞（事情），让我避免淋雨感冒（影响）”可以用自己舒适的说话方式来表达，不一定用我给的句式。\u003c/p>\u003cp>案例是否对你们有启发？现在用2分钟时间在组内讨论下，怎样更好表达。\u003c/p>\u003cp>接下来，请一位小伙伴分享自己的运用。\u003c/p>\u003cp>毕风案例分析：\u003c/p>\u003cp>之前老婆做饭，没有特别感谢，现在可以这样说：“你给我做饭，让我感觉很幸福，有家的感觉”。\u003c/p>\u003cp>谢谢小伙伴今天的参与和分享，大家参与感很强，都get到我的分享点，能活学活用，本次拆书已完成，谢谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1544169453000,"updated_at":1544169453000,"ria":true},{"id":6124,"topic":"非暴力沟通—倾听","learn_goal":"非暴力沟通—倾听","remark":"非暴力沟通—倾听","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"gaogao高高","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>（分发拆页）大家好，我是爱学习爱分享的高高，为了让各位更好进行拆为己用，我们来分组，从我的左手边开始，两两为一组，今晚一同分享，一同学习！\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>通过本次RIA学习，我们在倾听他人时候，如何应用（行为）3个步骤，分别是\u003cstrong>停听说\u003c/strong>进行全身心倾听。也就是说当他人跟我们倾诉后，我们需要停止说话，望着对方，认真听对方所讲，适时说：嗯…你刚说的是…这样才是全身心倾听。（澄清）从而我们可以倾听对方所感所受，让对方可以宽心把要倾诉的一一诉说，直到倾诉所有后，对话结束后，对方会感觉到很轻松，我们也会感到很放松。（界定）\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>【事件场景】\u003c/p>\u003cp>每个人都会遇到不顺心，需要找一个垃圾桶倾诉的时候，可是我们不难发现，总会出现这样的场景：比如母亲学会了拼多多，跟你倾诉，你满不在乎在一边玩手机，一边说“那是骗人的”母亲不说话了。又比如你的闺蜜失恋了..她刚说了她分手了，你马上义愤填膺的说：“这就是个渣男，你那么好，肯定会找到更好的…”你的闺蜜点点头没再说话…\u003c/p>\u003cp>【提问】你是否遇到过呢？你有什么感受呢？你会想些什么？\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>我们不难发现，往往他人需要向别人倾诉时候，想要的或许仅仅是一个肩膀，一个垃圾桶…可是作为倾听者的我们，又是如何做的呢？我们马上给予建议，给予安慰…这些只会让对方无法继续倾诉…我们无法获知对方的感受需要，更谈不上请求呢…\u003c/p>\u003cp>【解决】《非暴力沟通》这本书籍向我们叙述了如何去倾听，让我们学会运用科学有效的方法去倾听对方，从而达到彼此和谐共处的状态。所以，当他人向我们倾诉时候，我们可以运用三个步骤去倾听对方从而舒缓对方情绪。\u003c/p>\u003cp>【A1】请大家自测\u003c/p>\u003cp>在阅读原文片段前，先请大家来做一个简单的测试，看看我们在倾听他人时的表现如何 。以下5个题目，请按照1~6分的标准给自己打分，1代表完全不符合，6代表非常符合。请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示非常符合，请用“√”方式）。\u003c/p>\u003cp>【I】解释自测题\u003c/p>\u003cp>通过刚才简单的自测题，让我们更加清晰看到我们平常到底是如何倾听的。\u003c/p>\u003cp>在这个表格，我们不难发现：分数越高，我们的倾听越需要加以改善。如果分数是在12-18分，是属于聆听中等级别，聆听的中级段位，如果低于12分，那么你就是聆听高手啦~属于聆听的高级段位~~如果是高于18分的话，我们的聆听属于初级段位，需要努力加强聆听的技能哦~\u003c/p>\u003cp>那现在我们来看看我们的分数~~~诶~~我们发现好多小伙伴们的分数其实都是偏中等的~~说明我们的倾听还是有很大的空间可以改进的~~\u003c/p>\u003cp>当然，这仅仅是现在的一个对自己过去的评分，我们相信，通过今日的拆书以及后续的刻意练习，我们可以改变~倾听做得越来越好~\u003c/p>","ratings_count":1,"texts":[{"id":9382,"quote":"\u003cp>法国作家西蒙娜·薇依(Simone Weil)写道:“倾听一个处于痛苦中的人,不仅十分罕见,而且非常困难。那简直是奇迹;那就是奇迹。有些人认为他们可以做到,实际上,绝大部分的人还不具备这种能力。”遭遇他人的痛苦时,我们常常急于提建议,安慰或表达我们的态度和感受。可是,倾听意味着全心全意地体会他人的信息一这为他人充分表达痛苦创造了条件。有一句佛教格言恰如其分地描述了这种能力:“不要急着做什么,站在那里。\u003c/p>\u003cp>如果一个人想要别人了解他的处境,听到的却是安慰和建议,那么,他就有可能觉得不太舒服。我和女儿的一次对话提醒我,在安慰他人或提建议前,先看看那是否是他们想要的。\u003c/p>\u003cp>有一天,我女儿在照镜子时说:“我丑得像一只猪”“你是世界上最美丽的女孩！”我大声宣布。女儿很不高兴地看了我眼,喊了声“爸呀”,然后摔上门出去了。我的安慰看来不合时宜。\u003c/p>\u003cp>也许,她只是希望我留意她的感受。也许当时我最好问她:“你对你今\u003c/p>\u003cp>天的形象感到很失望吗？”\u003c/p>","explains":"\u003cp>what】其实这个片段就是讲了如何去全身心倾听，我们会发现文中不仅给予了我们倾听步骤，还用了女儿跟父亲的例子去进一步阐述如何去倾听，错误的倾听方式会带来什么后果…\u003c/p>\u003cp>【互动】\u003c/p>\u003cp>（1）想问问各位，大家刚才在画线的过程当中，画的关键词有哪些啊？\u003c/p>\u003cp>（站在那里、全心全意体会他人的信息）\u003c/p>\u003cp>（2）按照原文，我们来看看到底作者让我们注意什么？\u003c/p>\u003cp>①我们需要用全身心去___倾听_______\u003c/p>\u003cp>②倾听意味着全心全意地_____体会____他人的信息\u003c/p>\u003cp>所以就像是我们第2个填空，如何去体会，让对方觉得我们懂他，那么，在听的过程当中适当给予反馈“恩，恩/你想表达的是（重述对方所说）”或者是眼神交流…那么其实这样的倾听就能够达到全身心倾听了。\u003c/p>\u003cp>所以，要如何做到倾听？做一个最佳的聆听者呢？\u003c/p>\u003cp>① 停：闭上嘴，停止安慰和建议\u003c/p>\u003cp>② 听：放下手中事情，望着对方去聆听\u003c/p>\u003cp>③ 说：\u003c/p>\u003cp>听的过程适时表达“嗯、嗯/我理解” \u003c/p>\u003cp>当对方说完，重述对方所说+是么?\u003c/p>\u003cp>【案例】\u003c/p>\u003cp>说一个我自己的例子吧…上两个月，我闺蜜失恋了，她跟我说：“我好不开心，他…”我听完，直接很理性跟她说：“那种男的就是要不得的，别再想了，我带你去吃好吃的？！”结果呢？闺蜜就这样闷闷不乐…\u003c/p>\u003cp>看了今天的片段，我终于明白为什么好多人都说我的同理心好差，其实不怪什么同理心，真的是自己太冲动，没做好倾听。\u003c/p>\u003cp>所以，如果回到那个时候，我会停，啥都不发言，等她倾诉，我会停下来去听她说，等她说完时候，我会回应：“嗯嗯，我理解，你刚提到你的心情不好是因为…”让我闺蜜可以倾诉她自己所有想要说的话。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>当然我们会发现并不是所有的倾听都需要用到这三个步骤：\u003c/p>\u003cp>一、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 对方诉说的事情是经常性提及的惯性事情时，好比如反复提及“从现在开始，我要减肥”…对于这种，并不需要如此温柔倾听\u003c/p>\u003cp>二、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 对方诉说的事情是不怀好意的为难自己，例如带有讥讽、炫耀等，那么这种事情，肯定也是不需要三个步骤\u003c/p>\u003cp>那么到底什么情况下需要用到三个步骤进行倾听呢？\u003c/p>\u003cp>当对方很认真跟你说一件事情，表达自己感受/需要/请求，极度需要你作为倾听者的角色，往往是欣喜的事情、悲伤的事情，那么我们都需要认真对待，都需要用到三个步骤。\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>【场景设计】现在，让我们现场来学以致用~\u003c/p>\u003cp>C和M是情侣，今天，C特别郁闷，C今天的工作很忙碌，老板吩咐了她去寄快递给客户，结果，老板忘记把发票放进快递里面…C就寄过去了…客户直接怼了老板，当然C也被老板给叼了一番，她特别的郁闷…明明是老板的责任，背锅的却是她…她闷闷不乐，决定要回家跟M好好吐槽一番…\u003c/p>\u003cp>C：亲爱的，我好背啊今天，好郁闷啊！！！\u003c/p>\u003cp>【问题】如果大家是M先森，该如何通过三个步骤去倾听C呢？\u003c/p>\u003cp>【角色扮演】接下来请每组小伙伴们，进行演练，时间是5分钟。其中一个扮演C小姐，一个扮演男友M。运用日三个步骤，倾听C.\u003c/p>\u003cp>【演练】\u003c/p>\u003cp>一会儿我会邀请一组展示你们的对话，展示时间只有4分钟。\u003c/p>\u003cp>（案例记录）\u003c/p>\u003cp>学习者1：哎呀，我今天真的好郁闷啊，我本来就很忙，老板还要我去寄快递哦，老板自己放发票在里面，我就寄出去了。然后，老板回来骂我了，说快递没有发票，有没有搞错我，但是明明是他自己把发票放在里面的，是他自己的错，虽然我觉得有可能是我的疏忽，但是我不可能拆我老板的包裹啊。\u003c/p>\u003cp>学习者2：一边回应：是的，是的，对对。\u003c/p>\u003cp>学习者1：所以，他叫我寄出去，我就寄出去啦。但是老板骂我，我就是还是很不爽啊。。。\u003c/p>\u003cp>学习者2：所以说，老板忘记放发票在里面了，老板让你去寄快递，然后客户投诉没有发票，老板就骂你了…是么？\u003c/p>\u003cp>学习者1：是的，就是！\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>今天我们是学习了通过三个步骤更好去倾听对方，但是往往知道和做到之间还是存在着无法逾越的鸿沟，我们需要的是日后的刻意练习，更好运用到我们的生活里面去。\u003c/p>\u003cp>接下来的一周里面，请大家刻意练习我们的三个步骤，留心身边的人是否有向我们倾诉，选择其中一个向你倾诉的小伙伴，你运用三个步骤来加以倾听，把这件事情的详细经过记录下来，分享到我们今天建立的群上，让我们所有的小伙伴们一起见证，卓越的进步！\u003c/p>\u003cp>（学习者群上分享）\u003c/p>\u003cp>老刘今天情绪很不好，我就走过去，问他怎么了…他说昨晚跟他老婆吵架了，哎…我说来，你想说就跟我说说。然后他就说起昨晚他就是吃完饭累了，歇了下来看看电视，然后她就开始说我忘记了昨天说过的今天要搞卫生。我就说:“今天干活太累了，忘记又咋地”\u003c/p>\u003cp>我就想起倾听，说：“嗯嗯嗯”\u003c/p>\u003cp>他又继续说：“她就开始喋喋不休了，不断说…天啊”\u003c/p>\u003cp>我就说：“你指的是你跟你老婆说你不记得，她就各种说你？”\u003c/p>\u003cp>他又继续说：“是啊…天啊”\u003c/p>\u003cp>最后，整个过程持续了20分钟…\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1537623345000,"updated_at":1537623695000,"ria":true},{"id":5471,"topic":"非暴力沟通观察和评论应用","learn_goal":"现场让学习者非暴力沟通四步骤拆为己用","remark":"非暴力沟通四步骤，观察、感受、需要、请求","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"fy","city":"厦门"},"club":{"name":"厦门鹭见欢喜分舵","city":"厦门"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1531019343000,"updated_at":1531019343000},{"id":4945,"topic":"如何让别人理解你的意思","learn_goal":"让别人理解你的意思","remark":"","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"壹佳壹","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"大家好，介绍下我自己，我是周盛佳大家可以叫我佳佳，给大家带来1-2片段。用三个标签介绍自己：1、名字介绍：爸妈的姓+我的生日，我的生日是双十一，买东西送的；2、爱好想环游全世界，受飞屋环游记的影响，现在在努力中；3、拆书目标，今年10月份拆到3级，正在努力中；介绍完自己，开始介绍今天带来的书——非暴力沟通，在介绍书之前先用3个问题让小伙伴思考一下，\r\n1）如果想知道对方是否明白你的意思时，会如何表达？\r\n2）如果想得到对方明确表态，会如何表达？\r\n3）如何让别人理解我们的意思，当说出我们的小建议；\r\n这3个问题在生活中比较常见，书中作者马歇尔.卢森堡博士，用两个维度讲这些问题，告诉我们诚实的表达自己，关切的倾听别人的沟通方式，改变自我。请大家用1分钟时间阅读片段。","ratings_count":1,"texts":[{"id":8029,"quote":"\u003cp>片段《非暴力沟通》P70&nbsp;&nbsp;&nbsp; 请求反馈\u003c/p>\u003cp>我们的意思和别人的理解有时可能是两回事。如果无法确定对方是否已经明白，我们可能就需要得到反馈。请求反馈能确保对方准确把握我们的意思。有时，问一句“我的意思清楚吗”，然后，对方表个态就足够了。在另一些时候，听到“是的，我明白你的意思”这样的回答，我们并不放心。为了确保对方确实明白我们的意思，我们希望他充分表达他的理解。这样，一旦他的理解与我们的意思有所不同，我们就有机会作适当的补充。\u003c/p>\u003cp>例如，一位老师和她的学生说：“托尼，今天批改作业时没有看到你的作业本。我想知道，你是否清楚我上次布置的作业。放学时，来我办公室一下好吗？”托尼咕噜了一句：“好，知道了。”然后，他就转过身去，准备离开了。老师站在那里，不清楚学生是否已经明白她的意思。于是，她叫住他：“麻烦你说一遍我刚才请你做的事情好吗？”托尼回答说：“放学后，我没法看足球赛了，因为你要把我留下来做作业。”老师发现托尼并没有听明白她的意思，她准备作出解释。这时，她很注意她的方式。\u003c/p>","explains":"\u003cp>当我们在表达自己请求的时候，对方会出现理解偏差，如何让对方正确接收我们的信息，概括成3点，1）提出请求，2）提问确认，3）请求复述；&nbsp;\u003c/p>\u003cp>片段中老师如果没有向学生进行提问确认，学生可能根据自己的理解完成老师的要求，会出现问题。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>书中的例子因为职业差异，会有理解上的不同，举个职场例子，前几天我需要相关部门配合做数据核对，发信息说：“某某，数据已发您，请核对下数据，如需要改进的地方请告诉我”，其中A部门简洁的回答“好”。我默认为已经知道这件事情， 数据整合好交上去，部门A和我领导反应我没有讲这件事情，当时我有点炸毛，有点不爽，什么，不是已经通知过你。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;【A1+】: 做个深呼吸，反思下自己的行为，用3个步骤反思这件事，复盘一下\u003c/p>\u003cp>1、提出请求：\u003c/p>\u003cp>如果把我的目的说的更清晰：“核对数据可以提高大家的效率，找出错误，提高数据的正确率。”\u003c/p>\u003cp>2、提问确认：\u003c/p>\u003cp>如果用“我说明白了吗？“更好会有反馈\u003c/p>\u003cp>3、请求复述：&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;将我的理解复述给他听，“数据是晚点给我吗？是在明天下班前16点前给我吗？“ 更清楚我是否理解他的意思。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>【适用边界】：方法有适用边界，在工作中上下级、老师与学生，父母与孩子之间，比较适用。刚开始用请求反馈技能时会不适应，多加练习\u003c/p>\u003cp>&nbsp; &nbsp;听完我的分享，脑海中是否有类似的经历？可能是上周与同事讨论工作不欢而散，上上周领导布置任务，你做出的结果与领导想要的不一样，和小伙伴沟通中出现的小事情。回想下当时的场景，在什么情况下，和谁，为了什么事情，思考1分钟。我分下组，延续之前的分组，分享下你的经历。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>分享个失败例子，周一开早会，安排工作周四、周五发课程推文，以为会按照计划做，星期三培训的人出差，今天下午（周四）才发现连海报还没做，意识到问题，我以为他们都懂，其实我应该周二或周三问下进度。得出两个结论，和90后相处要从零的心开始的，让他们喜欢你才会做事，第二，事情进展到一半的时候要督促一下。\u003c/p>\u003cp>小伙伴建议：沟通关注结果，我们做目标分解，通过目标分解来把控工作进度。\u003c/p>\u003cp>【A2】:小伙伴设想在未来的一周，或者更久的时间半个月，可能是公司同事出现同样工作讨论或是朋友在类似的小事情上，你会在什么样的场景下应用刚才学的三个步骤，将如何解决写在便签上。\u003cbr> 小伙伴都写好，来分享一下，用三句话总结下\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>1、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 放养式\u003c/p>\u003cp>2、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 圈养式，过程管理\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1522636075000,"updated_at":1522636075000,"ria":true},{"id":4048,"topic":"如何提出请求，对方更易接受？——非暴力沟通的艺术","learn_goal":"学习者能在对他人不满时，根据自己真实动机，提出具体地肯定请求","remark":"","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"林佳鸿","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"今天我要拆解的片段来自这本书《非暴力沟通》\r\n【F】有多少人读过这本书？这么多，好，那我来考考大家。什么是“暴力”？这本书里的前言就讲到对“暴力”的定义。分为“身体的暴力”和“隐蔽的暴力”，后者就是精神伤害。大家刚才讲的很多是“身体的暴力”，但我们生活中“隐蔽的暴力”其实非常普遍，而它的主要传播方式就是沟通。社会的法制及教育能减少“身体的暴力”，但却没有人教我们如何避免沟通上的暴力。这就是作者马歇尔博士写这本书的目的。\r\n【A】 这本书也是拆书帮里的经典书籍。我们拆书帮有一个官网，上面有一栏是图书，你点进去能看到，每一本书被拆了多少次，每位拆书家的逐字稿。通常一本书能被拆50次，已经很了不起了，大家猜猜《非暴力沟通》被拆了多少次？388次。可见这是经典中的经典！【B1】联系到我们生活，大家会不会觉得跟关系越亲密的人，沟通就越容易“暴力”？ 《非暴力沟通》从观察、感受、需要、请求四个要素，帮助我们从本质上改变沟通方式，提升亲密关系【B2】我们今天要学的是“请求的艺术”，我们将学会如何提出具体请求，大大提升请求的成功率！","ratings_count":0,"texts":[{"id":7006,"quote":"\u003cp>\u003cstrong>提出具体的请求\u003c/strong>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>首先，清楚地告诉对方，我们希望他们做什么的。如果我们请求他人不作什么，对方也许会感到困惑，不知道我们到底想要什么？而且这样的请求还容易引起别人的反感。\u003c/p>\u003cp>有一次，我应邀去协调一些高中生与他们校长的矛盾。这些高中生对校长极为不满。他们认为他是种族主义者，并准备找机会报复他。一位牧师担心会出现暴力，就请我去协调矛盾。出于对这位牧师的尊重，他们表示愿意与我见面。\u003c/p>\u003cp>一开始，他们就举例说明为什么他们认为校长是种族主义者。听完几个例子后，我请他们讲讲他们希望校长具体怎么做。\u003c/p>\u003cp>此时，一位学生不屑地说：“这有什么用吗？每一次和他说我们的想法，他总是说，’离开这里，我不需要你们这些人告诉我该做什么!‘ ”\u003c/p>\u003cp>接着，我向他们了解，他们向校长提出了什么请求。他们回忆说，他们希望校长不要对学生的长发说三道四。对此，我的看法是，如果她们说出希望校长做的事，而不是不希望他做的事，他们就较有可能得到积极的回应。\u003c/p>\u003cp>此外，他们还提出他们希望得到公平的对待。然而校长的答复是，他对学生十分公平。我评论说，如果他们请求的是具体的行动，而非抽象的“公平对待”，那么，他们就较有可能得到满足。\u003c/p>\u003cp>于是，我和学生们一起列出了他们的具体请求，共有38项。其中包括：“我们希望黑人学生代表可以参加校服标准的制定。”“在你家提到我们时，我们希望你用黑人学生，而不是你们这些人。”第二天，他们向校长提交了书面请求。当晚，他们就在电话中兴高采烈地告诉我，校长同意了所有的请求！\u003c/p>\u003cp>\u003cstrong>练习一：\u003c/strong>\u003c/p>\u003cp>1.&nbsp; 我希望你理解我\u003c/p>\u003cp>2.&nbsp; 关于昨天的会议，请不要隐瞒你的看法\u003c/p>\u003cp>3.&nbsp; 我希望你能在规定的时速内驾驶\u003c/p>\u003cp>4.&nbsp; 我希望你尊重我的个人隐私\u003c/p>\u003cp>5.&nbsp; 我希望你经常做晚饭\u003c/p>\u003cp>\u003cstrong>练习二：现场演练\u003c/strong>\u003cstrong>\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>","explains":"\u003cp>片段里讲的是一个简单的故事。黑人学生与校长的矛盾，那我来考考大家看的仔不仔细。这些黑人学生一开始给校长提的第一个请求是什么？\u003c/p>\u003cp>“不要对学生的长发说三道四”\u003c/p>\u003cp>我们想一下，当我们看到对方做某件事，我们很不满，想提出请求，我们会用肯定句式还是否定句式？\u003c/p>\u003cp>通常是否定的。但用否定句式，常常会带来负面效果。\u003c/p>\u003cp>比如说，我现在在上面分享，我看到恩强正在跟别人交头接耳地聊天，我就直接说“恩强，你可以不要说话吗？”\u003c/p>\u003cp>恩强，你会不会有不开心的感觉？对，说“不做什么”的句式，往往会让人觉得是一种命令，要么服从要么反抗，现代人都非常礼貌，口头上，“好的”；内心里“切，不理你”\u003c/p>\u003cp>用否定句式还有第二个坏处，就是让别人不知道你请求的目的。\u003c/p>\u003cp>比如说，老婆看老公吃完饭一直玩游戏，她就直接说“亲爱的，不要玩王者荣耀啦” 老公就说，“好吧，那我去把公司的邮件处理一下。”老婆就更郁闷了。她请求的目的是什么？得到关注和陪伴，但表述的方式却太委婉，不要玩王者荣耀。我们常常认为对方应该懂我，尤其是情侣，但我是你老公，不是你肚子里的蛔虫啊。所以女士们，不要把希望寄托在直男的情商上。\u003c/p>\u003cp>不过有时候，我们的请求用的是肯定句式，但效果也不好，有可能是因为提的请求太过抽象！\u003c/p>\u003cp>片段里，黑人学生对校长的请求，有哪一个是太过抽象的呢？\u003c/p>\u003cp>“公平对待”\u003c/p>\u003cp>大家觉得这种抽象的请求导致的结果是什么？\u003c/p>\u003cp>让听的人很模糊，不知道具体该怎么做。比如，家长经常跟小孩子说，你现在长大了，要懂事一点。大家觉得，懂事一点那到底该做什么？帮爸妈做家务？按时写完作业？见到长辈主动问好？\u003c/p>\u003cp>这都是嘛，那我怎么可能都做到呢？好吧，我听听就好，不会当真的！\u003c/p>\u003cp>所以我们可以看到，如果我们提到请求，用的是否定句式或者太过抽象，会让对方产生不满，或者不清楚要做什么。\u003c/p>\u003cp>那大家觉得怎么样的请求才是高效的呢？“要具体‘\u003c/p>\u003cp>我根据文中的案例，总结了三个步骤。\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp; 当产生不满时，先忍住，冷静一下\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp; 想清楚自己的动机，希望对方做什么具体的事\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp; 说出具体的请求（肯定句式），多用动词、名词，少用形容词，提升请求的可操作性。\u003c/p>\u003cp>我举一个自己过去发生的真实案例哈。\u003c/p>\u003cp>我的工作是运营高中生的经济学比赛，我每天会用官方邮箱，发报名确认的邮件给学生。有一天我发邮件忘了附上附件，就把邮件撤回，结果上司知道了。\u003c/p>\u003cp>上司对我有不满，但他没有直接说”哎呀，hubert，你怎么这么不小心，下次别再这么粗心大意啦“\u003c/p>\u003cp>相反，他并没有任何责怪我意思，他很清楚自己的动机，是要帮助我准确无误地发每一封邮件，这样团队效率才会高。\u003c/p>\u003cp>所以，他就说，“hubert呀，你可以把发邮件的流程写在清单上，以后看着清单发，就不会有遗漏了”\u003c/p>\u003cp>我的上司这样说，我就很清楚该怎么做，到现在就再没有发生发错邮件的情况。\u003c/p>","interaction":"\u003cp>【A3】现场演练\u003c/p>\u003cp>大家都理解如何提出具体请求了吗？\u003c/p>\u003cp>可能有小伙伴疑问，我们如何评估请求是否具体明确？\u003c/p>\u003cp>我们来做一个小练习。请大家以小组为单位，讨论一下，以下5个句子，哪一些是明确的请求，对于不明确的，可以讨论一下，如何修改成得具体明确。时间是3分钟。\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;我希望你理解我。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;关于昨天的会议，请不要隐瞒你的看法。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;我希望你能在规定的时速内驾驶\u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp;&nbsp;我希望你尊重我的个人隐私\u003c/p>\u003cp>5.&nbsp;&nbsp;&nbsp;&nbsp;我希望你经常做晚饭\u003c/p>\u003cp>哪一个小组愿意派一个代表分享一下？&nbsp;2分钟\u003c/p>\u003cp>学习者小白：\u003c/p>\u003cp>只有第三个是明确的，其他可以修改得更明确。\u003c/p>\u003cp>公布书中修改答案。\u003c/p>\u003cp>1.我希望你能复述出我讲的话。\u003c/p>\u003cp>2.&nbsp;关于昨天的会议，希望你可以反馈你觉得我哪里需要提高。\u003c/p>\u003cp>4.我希望你在进我办公室之前，能敲一下门。\u003c/p>\u003cp>5.我希望你每周日晚上都能做晚饭。\u003c/p>\u003cp>那我们接下来要进入到很好玩的现场演练环节！\u003c/p>\u003cp>不过开始之前，我们再来复习一下，提出具体请求的三个步骤是什么？\u003c/p>\u003cp>（大家回应）\u003c/p>\u003cp>现在，我们先每两人为一组，会饰演一对夫妻，建议男女搭配啊。\u003c/p>\u003cp>请大家认真听一下要演练的场景：\u003c/p>\u003cp>马上双11就要到啦！在一对年轻夫妻的家里，老婆正在刷淘宝，她已经在购物车里放了100件商品。她觉得，双11就是要买买买，反正东西便宜，买着先存着，以后说不定能用上。\u003c/p>\u003cp>但是，老公对此非常抱怨。去年双11买的东西有的根本没用，就都压箱底了。他希望老婆不要买这么多没用的东西。\u003c/p>\u003cp>每组要排练出两组对话，第一组对话，是负面案例，老公用平时一般的直接地沟通方式，向老婆提出请求。\u003c/p>\u003cp>第二组对话，就是一个正面案例，老公要用今天学的提出具体请求的三步骤，来向老婆提出请求。\u003c/p>\u003cp>大家清楚该怎么排练了吗？\u003c/p>\u003cp>演练时间是4分钟。\u003c/p>\u003cp>邀请一组上台分享。（3分钟）\u003c/p>\u003cp>【场景一：暴力式沟通】\u003c/p>\u003cp>虫子（老公）：你看你购物车一百多件商品了啊，去年买的东西有一些放在那里，还没有开封呢。今年别再买那么多东西啦！\u003c/p>\u003cp>小燕（老婆）：老公，你之前不是这样对我的，你之前对我可好啦，给我买口红、买花，今年什么都没有！你能不能对我体贴一点？\u003c/p>\u003cp>（互怼模式…）\u003c/p>\u003cp>【场景二：非暴力式沟通】\u003c/p>\u003cp>小燕（老婆）：老公，你看我们都没有之前那么甜蜜了，你看我们能不能每周吃一次西餐，每个月开一次电影呀？我愿意把我的购物车减半。\u003c/p>\u003cp>虫子（老公）：我很感动你做的让步，我们是不是也可以把购物车剩下来一半的钱花在我们共同的幸福上，比如吃饭看电影或者旅游？\u003c/p>\u003cp>我们把更多的时间金钱花在互相的交流，而不是买更多的东西。购物车里有哪些是必须用的，该买咱们还是要买。\u003c/p>\u003cp>【总结】\u003cbr>\u003c/p>\u003cp>今天我们从非暴力沟通学中学到了如何提出具体请求，其实真的每一天都用得上。不过，就像我们练肌肉一样，一开始，我们练习得少，可能对别人有不满，就直接说，“你别怎么怎么样了”。但我们只要反复多次地练习，相信大家一定可以快速提升沟通能力！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1511173115000,"updated_at":1511173115000,"ria":true},{"id":3877,"topic":"让愤怒不再愤怒","learn_goal":"用四个步骤认识愤怒并理性表达愤怒","remark":"","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"慧吉","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"大家好。我是一级拆书家慧吉。今天给大家带来的是TF2-2的拆解。拆解片段摘自《非暴力沟通[珍藏版]》。《非暴力沟通》的作者是马歇尔.卢森堡，是美国著名的心理学大师。作者认为是不良的言语模式屏蔽了人们心中彼此的积极，温暖和关爱。书中设计了大量练习，帮助人们改变这样的模式，学会观察，感受，了解情感和表达需要。依照这样的沟通方式来谈话和聆听，能使人们情义相通，互助友爱。","ratings_count":0,"texts":[{"id":6825,"quote":"\u003cp>《非暴力沟通》p140\u003c/p>\u003cp>表达愤怒的四个步骤\u003c/p>\u003cp>现在让我们看看非暴力沟通表达愤怒的四个步骤。首先，停下来，除了呼吸，什么也别做。我们避免采取行动去指责或惩罚对方。我们只是静静地体会自己。接着，想一想是什么想法使我们生气了。例如，无意中听到某个人的谈话后，我们认为由于种族的原因自己遭到了排斥。这时，我们体会着愤怒，并留意脑海中盘旋的想法：“这太不公平了！”“她这是种族歧视！”我们知道，象这样的想法是尚未满足的需要的可悲表达。于是，接下来，就去了解自己想要满足的需要。如果我把某个人当作种族主义者，我的需要也许是接纳、平等、尊重或联系。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;为了充分地表达自己，我们现在需要张开嘴，说出我们的愤怒。怒火此时已被转化为需要以及与需要相联系的情感。然而，表达此时的感受也许需要很大的勇气。对我来说，生气并冲着人们嚷“你们这是种族歧视”是很容易的。事实上，我甚至还会觉得高兴。但是，倾听心底深处的感受和需要却很可能引发不安。为了充分表达愤怒，我们也许会对那个人说：“你走进房间后，和其他人打了招呼，却没有和我说话，现在你又在议论白种人，注意到这些，我的胃有些不舒适，而且很害怕，因为我很看重平等。我想请你告诉我，听到我说这些，你的感觉怎么样？”\u003c/p>","explains":"\u003cp>\u003cstrong>生活中我们会因很多事情不如意就生气发火。比如，孩子不听话，看到另一半熬夜的习惯老不改，受到别人的冤枉，你提出的请求得不到回应，约会被对方放了鸽子，别人停车挡住了出路，等等，等等。比如有一次，有人把车停在了我们单元门口的阶梯前，我很生气。我见到车主就发脾气了，吼着她说“没张眼睛看见这是通道吗？，甚至还骂她有病。但是对方除了感受到我身上的火气外，并不明白我窝的是什么火。因为生气时，吼叫骂人，甚至打人之类的表达方式无法真正传达我们的心声。如果真的很生气，我们就需要找到更有力的方式充分表达自己。拆页就给到我们这个有力的方式。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来，就我生气发火的例子，我们一起来学习拆页“表达愤怒的四个步骤”：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：静下来，深呼吸\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当我见到停车时，顿生愤怒。这时要意识自己冷静下来，深呼吸，体验心中的愤怒。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：找出想法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>想一想是什么想法让我生气。当我见到停车时，我认为车主自私，把车停在公共道口，缺德。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>然而我的想法暗示着我的什么需要没有被满足呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：找出需要\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们的想法常常对应着自己想要被满足的需要。当我认为一个人是自私的时候，他可能就不顾我的利益，那么我的需要可能是被尊重，利益被考虑\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四步：表达需要\u003c/strong>\u003c/p>\u003cp>\u003cstrong>愤怒走过了前三步就转化为\u003c/strong>需要以及与需要相联系的情感\u003cstrong>。这时我可以鼓起勇气对车主把自己内心的需要表达出来。我说“我看见你的车停在阶梯口前面，妨碍了我们大家的出入（客观事实），我很生气（情感），因为我很看重自己和大家的出入畅通（需求）。我想你告诉我，听到我说这些，你的感觉怎样？（询问对方的感觉）这样的表达是不是更好呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>大家可能会想，当人很生气的时候，就是要出这口气，怎么还能走完这四步呢？我想说，其实只要你有意识，能意识到第一步静下来，深呼吸，体会心中的愤怒，就有\u003c/strong>\u003cstrong>可能阻止你的小宇宙爆发。这不算难做到吧。你也许还会问，我意识到第一步后，能不能接着完成二三步呢？这就需要平时不断的自我反省和刻意训练。每次大小的生\u003c/strong>\u003cstrong>气愤怒之后，问自己什么想法使我生气，我要被满足的需求是什么？形成这样的习惯后，你就有可能在生气之中完成二三步。你是不是还想问，到了第四步，我们要表\u003c/strong>\u003cstrong>达的不再是愤怒而是需要了？对的。\u003c/strong>做到\u003cstrong>这四步不容易，需要我们刻意训练。用非暴力沟通的方式表达愤怒不仅能有效改善你和别人的沟通效果，更能充分表达内心的\u003c/strong>\u003c/p>\u003cp>\u003cstrong>需要。所以，这样的刻意练习是值得的。\u003c/strong>\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>当然不是所有的生气愤怒都用得上这四个步骤来。比如说排队购物时，有人踩你一脚，\u003c/p>\u003cp>很痛，你很生气，再比如，小区突然停电，你很愤怒，等等。只有当生气和愤怒是指\u003c/p>\u003cp>向重要的人和事的时候，我们才需要使用这种技巧帮助我们深入了解愤怒，充分表达\u003c/p>\u003cp>内心的渴望。\u003cstrong>&nbsp;\u003c/strong>\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>【A2】催化应用1：\u003c/p>\u003cp>&nbsp;我们设想在未来的一段时间（一周/一个月）里，你跟你的家人、朋友、同事相处的时候，可能会发生哪些不愉快的事情，他们会让你的情绪失控。会有哪些场景呢？与领导同事讨论方案,无论怎么说他都不理解你！与家人或者恋人沟通事情，\u003c/p>\u003cp>总感觉很难达成一致意见，和孩子说话，就是不听！等等。生活中还有很多其他这样让人生气的场景。接下来给大家一分钟想一想，然后将你设想会生气的场景写在便签纸上，并在已分好的小组内分享。\u003c/p>\u003cp>之后会请到一位小伙伴给我们分享一下自己写的场景。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录\u003c/p>\u003cp>芳芳：下周三要外出上培训课，我还没敢与老公商量。估计商量时会出现激烈争 &nbsp; &nbsp; &nbsp; 吵，情绪失控。\u003c/p>\u003cp>琳琳：下周一要与装修公司对面，我估计会因为他们拖延工期的问题发生争执，\u003c/p>\u003cp>&nbsp; &nbsp; 生气愤怒\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>【A2】催化应用2：\u003c/p>\u003cp>面对这样的场景，你情绪有些失控。这时你想起今天学习的拆书，你会如何去表达你的愤怒呢？接下来，请小伙伴按照“表达愤怒的四个步骤”在小组内分享一下，限时5min。\u003c/p>\u003cp>之后会请到几位小伙伴给我们一一分享\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录\u003c/p>\u003cp>琳琳：下周一要与装修公司对面，我估计会因为他们拖延工期的问题发生争执，生气愤怒。如果这样，我会按照今天学习的“表达愤怒的四个步骤”先\u003cstrong>冷静下来，深呼吸，接着想一想让我愤怒生气的想法是什么，然后清理出我的想法中没有被满足的需要是什么，最后清楚表达出自己的需求。我想，这样做一定可以收到较好的沟通效果。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1508630984000,"updated_at":1508630984000,"ria":true},{"id":1047,"topic":"非暴力沟通四要素","learn_goal":"能够有效运用片段中非暴力沟通模式的四个要素，提升自身沟通效果","remark":"这本书《非暴力沟通》，作者是马歇尔•卢森堡博士，他是一位临床心理学博士，师从人本主义心理学之父-卡尔•罗杰斯。是国际非暴力沟通中心创始人。\r\n    这本书入选香港大学推荐的50本必读书籍之一。也是拆书帮大力推荐和多次拆解的书籍，行文简单易学，列举了大量案例帮助我们理解和运用。\r\n    相信各位都一定认同沟通的重要性，好的沟通往往给我的们带来好的人际关系，从而直接影响到我们的幸福感。","level":"TF2-1","duration":25,"status":0,"type":0,"chaishujia":{"username":"水澜色","city":"广州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"▼大家好！我是水澜色，是一名职场妈妈。目前的工作是在汽车制造工厂负责成本管理，兼任培训担当。我崇尚的生活是：健康、有趣和成长。成为最美好的自己。\r\n▼今天带来的拆解主题是关于非暴力沟通，希望大家在跟随我完成本次RIA的现场学习后，可以改善现有沟通模式，从而提升沟通效果。\r\n 而我要拆解的片段:来自这本书《非暴力沟通》，作者是马歇尔•卢森堡博士，他是一位临床心理学博士，师从人本主义心理学之父-卡尔•罗杰斯。是国际非暴力沟通中心创始人。\r\n 这本书入选香港大学推荐的50本必读书籍之一。也是拆书帮大力推荐和多次拆解的书籍，行文简单易学，列举了大量案例帮助我们理解和运用。\r\n 相信各位都一定认同沟通的重要性，好的沟通往往给我的们带来好的人际关系，从而直接影响到我们的幸福感。可是在现实生活中，大家是否有遇到过沟通不畅的情况呢？例如，我明明表达的是这个意思，而对方为什么却理解成另外的意思？再例如，我原本想跟对方好好分享自己的感受，然而对方的反馈，让我彻底关上了心门。例如，我希望对方可以按照自己的方式去做，结果对方并未如我所愿。且在生活中因为沟通不畅导致人际关系出现矛盾的事就更是比","ratings_count":0,"texts":[{"id":3236,"quote":"\u003cp>非暴力沟通的要素\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;为了彼此能乐于互助，我们专注于四个方面——非暴力沟通模式的四个要素。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;首先，留意发生的事情。我们此刻观察到什么？不管是否喜欢，只是说出人民所做的事情。要点是，清楚的表达观察结果，而不是判断或评估。接着，表达感受，例如受伤、害怕、喜悦、开心、气愤等等。然后，说出哪些需要导致那样的感受。一旦用非暴力沟通诚实地表达自己，前三个要素就会得到体现。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;举例来说，一位母亲可能对他处于青春期的儿子说：”费力克斯，看到咖啡桌下的两只\u003c/p>\u003cp>脏袜子和电视机旁的三只，我不太高兴，因为我看重整洁。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;接着，她立即提出非暴力沟通的第四个要素——具体的请求：“你是否愿意将袜子拿到房间或放进洗衣机？”这一要素明确告知他人，我们期待他采取何种行动，来满足我们。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;这样，这位母亲就清楚地说出非暴力沟通的四个要素。借助这四个要素诚实地表达自己，是非暴力沟通的一个方面。非暴力沟通的另一方面是借助它们关切的倾听。我们首先通过体会他人此刻的观察、感受和需要，与它们建立联系，然后聆听它们的请求，来发现做什么可以帮助他们。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;保持对这两方面的关注，并帮助他人也这么做，双方便可持续互动，直至情意相通：我此刻的观察、感受和需要是什么；为了改善生活，我的请求是什么；你此刻的观察、感受和需要是什么；为了改善生活，你的请求是什么......\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;使用非暴力沟通时，表达自己或倾听他人，都是好的开端。但需要牢记的是，非暴力沟通不是固定的公式，它可以适应不同的情况，并根据个人风格及文化环境做出调整。为了叙述的方便，我将非暴力沟通称为“沟通方式”，但有时语言是多余的。非暴力沟通的精髓在于对其四个要素的觉察，而不在于使用什么字眼进行交流。\u003c/p>","explains":"\u003cp>非暴力沟通其实也可以被称作爱的语言，依照它来谈话和聆听，能使我们与沟通的对象更好的情意相通，乐于互助。\u003cbr>&nbsp;&nbsp;&nbsp; 回到书中的例子，母亲看到儿子乱丢臭袜子时的情景， 让我们回想一下，在我们还未接触非暴力沟通方式时，如果你是妈妈，或你的妈妈，通常会怎样说呢？一般的妈妈的第一反应可能是:“你怎么老是到处乱扔，我都说过你多少次了？！怎么就是改不了呢？你要我说多少遍你才能听呢？”然后边说边收拾臭袜子。在当时你或者是你的儿子会有何反应，可能会立马反抗，和妈妈发生正面冲突;可能逃避，当作没听到,但内心觉得妈妈很烦;总之，妈妈的话可能不会改变儿子乱丢的习惯，反而会影响母子间的关系。由此可以看出，当我们没有学习有意识的运用非暴力沟通方式时，不但没有办法让对方欣然接受，甚至会起到相反的作用。\u003cbr>&nbsp;&nbsp;&nbsp; 那究竟该如何运用四个要素呢？首先是表达你所观察到的，“菲利克斯，我看到咖啡桌下的两只脏袜子和电视机旁的三只，”其次是表达你的感受，“我不太高兴，”再次说出导致自己有这种感受背后的原因，“因为我看重整洁。”最后是提出具体的请求。“你是否愿意将袜子拿到房间或放进洗衣机呢？”\u003c/p>","interaction":"\u003cp>接下来进入A1环节，让我们一起回忆一下，最近在我们家庭、工作、或是其他场合，我们在与自己的另一半、孩子、父母、领导、同事、朋友相处的过程中，是否有亲身经历过让你觉得难以沟通或沟通效果不佳的情况呢？例如对方的行为做法让我们难以忍受，希望对方可以改变；或是否你一直有个想法希望能取得对方的配合；\u003cbr>&nbsp;&nbsp;&nbsp; 那我先举一个我的例子:近段时间，我发现我的一个同事因为心思放在股票投资上，工作不太上心，该做的报告等到最后截止日才不得不选择周末义务加班来完成。为此我希望他以后能事前做好日程，避免加班来完成。\u003cbr>&nbsp;&nbsp;&nbsp; 再例如，在我和妈妈的相处过程中，我发现妈妈特别的操心，家里大小事物都会帮忙考虑和做，就连洗完衣服都会帮我叠好放到衣柜。但她放的方式和我不一样。好几次早上起床我都找不到要穿的衣服，很恼火。而且我已经几次跟妈妈说:妈妈，麻烦你以后不要给我收衣服啦~但几乎没有效果，妈妈依然会帮我收放。我希望运用非暴力沟通来寻求她的合作。\u003cbr>&nbsp;&nbsp;&nbsp; 刚刚大家的例子都非常具体和生动。那接下来的A2环节，就是让我们结合片段中的非暴力沟通4个要素：表达观察的现象，感受，感受背后未满足的需求，具体的请求。想想下次你再遇到这种情况，你会如何沟通，或针对你目前想要沟通的情况，你可以如何运用。请分享出具体的说法。\u003cbr>&nbsp;&nbsp;&nbsp; 例如，我针对妈妈收拾自己衣服，我会改成这样表述：“妈妈，我很感谢你每天辛苦的帮我叠放衣服。可是每次我在预定的地方找不到时，我就会非常着急和老火。因为我希望自己的事情都是在自己的掌控和安排下进行的。以后是否可以让我自己来叠放衣服呢？”\u003cbr>&nbsp;&nbsp;&nbsp; 针对同事的情况，我将会这样与他沟通：“小阳啊，我看到你这次为了赶报告，还周末义务加班来对应，真是太辛苦啦。其实我也挺着急和替你担心的，我希望工作的推进可以稍微提前完成，留出一定的时间来灵活处理突发事件。你看以后可否调整日程的安排，在每件日常工作的截止日前都预留出至少半天时间呢？”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475892735000,"updated_at":1475892735000,"ria":true},{"id":1046,"topic":"观察","learn_goal":"能够正确区分观察和评论，从而开启非暴力沟通的第一步。","remark":"这本书行文简单易学，列举了大量案例帮助我们理解和运用。被入选香港大学推荐的50本必读书籍之一。也是拆书帮大力推荐和多次拆解的书籍，\r\n    大家在现实生活中，是否有遇到过沟通不畅的情况呢？例如，我明明表达的是这个意思，而对方却理解成另外的意思？再例如，我本想给对方提出善意的建议，然而对方却认为我在指责他。如果是，那么这本书就正好适合您。书中提出的非暴力沟通方式，让我们在轻松、愉快沟通的同时拥有充满爱与和谐的关系。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"水澜色","city":"广州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"▼大家好！我是水澜色，是一名职场妈妈。目前的工作是在汽车制造工厂负责成本管理，兼任培训担当。\r\n▼今天的拆解主题是关于如何开启非暴力沟通的第一步:观察。希望大家在跟随我完成本次RIA的现场学习后，能够正确区分观察和评论，学会正确的基于观察来表达评论。\r\n 我要拆解的片段:来自这本书《非暴力沟通》，作者是马歇尔•卢森堡博士，他是一位临床心理学博士。是国际非暴力沟通中心创始人。\r\n 这本书行文简单易学，列举了大量案例帮助我们理解和运用。被入选香港大学推荐的50本必读书籍之一。也是拆书帮大力推荐和多次拆解的书籍，\r\n 大家在现实生活中，是否有遇到过沟通不畅的情况呢？例如，我明明表达的是这个意思，而对方却理解成另外的意思？再例如，我本想给对方提出善意的建议，然而对方却认为我在指责他。如果是，那么这本书就正好适合您。书中提出的非暴力沟通方式，让我们在轻松、愉快沟通的同时拥有充满爱与和谐的关系。","ratings_count":0,"texts":[{"id":3235,"quote":"\u003cp>&nbsp;&nbsp; 非暴力沟通的第一个要素是观察。我们仔细观察正在发生的事情，并清楚地说出观察结果。非暴力沟通并不要求我们保持完全的客观而不作任何评论。它只是强调区分观察和评论的重要性。将观察和评论混为一谈，人们将倾向于听到批评，甚至会产生逆反心理。同时，非暴力沟通不鼓励绝对化的评论，而主张评论要基于特定时间和环境中的观察。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 区分观察和评论\u003c/p>\u003cp>在以下表格中，我举例说明如何区分观察和评论。\u003c/p>\u003cp>&lt;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>表达方式\u003c/td>\u003ctd>观察和评论被混为一谈\u003c/td>\u003ctd>区分观察和评论\u003c/td>\u003c/tr>\u003ctr>\u003ctd>使用的语言没有体现出评论的人对其评论负有责任。\u003c/td>\u003ctd>你太大方了。\u003c/td>\u003ctd>当我看到你把午饭的钱都给了别人，我认为你太大方了。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>把对他人思想、情感或愿望的推测当作唯一的可能。\u003c/td>\u003ctd>她无法完成工作。\u003c/td>\u003ctd>我不认为她能完成工作。或她说：我无法完成工作。”\u003c/td>\u003c/tr>\u003ctr>\u003ctd>把预测当作事实。\u003c/td>\u003ctd>如果你饮食不均衡，你的健康就会出问题。\u003c/td>\u003ctd>如果你饮食不均衡，我就会担心你的健康会出问题。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>缺乏依据\u003c/td>\u003ctd>米奇花钱大手大脚。\u003c/td>\u003ctd>米奇上周买书花了一千元。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>评论他人能力时，把评论当作事实。\u003c/td>\u003ctd>欧文是各差劲的前锋。\u003c/td>\u003ctd>在过去的5场比赛中，欧文没有进一个球。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>使用形容词和副词时，把评论当作事实。\u003c/td>\u003ctd>索菲长得很丑。\u003c/td>\u003ctd>索菲对我没有什么吸引力。\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 注意：“每次”“曾”等词语在以下句子中表达的是观察结果。\u003c/p>\u003cp>&nbsp; &nbsp; 我看安迪打了几次电话，每次都至少打半小时。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 我不记得你曾写信给我。\u003c/p>\u003cp>&nbsp; “总是”、“从不”等词语在以下句子中表达的是评论。\u003c/p>\u003cp>&nbsp; &nbsp; 你总是很忙。\u003c/p>\u003cp>&nbsp; &nbsp; 在需要她的时候，她从不出现。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 如果我们的表达言过其实，别人就可能产生逆反心理，而不愿做出友善的回应。\u003c/p>\u003cp>&nbsp; “经常”和“很少”这样的词语也可能混淆观察和评论。\u003c/p>\u003cp>&lt;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>评论\u003c/td>\u003ctd>观察\u003c/td>\u003c/tr>\u003ctr>\u003ctd>你很少配合我。\u003c/td>\u003ctd>我最近组织了三次活动，每次你都说你不愿参加。\u003c/td>\u003c/tr>\u003ctr>\u003ctd>他经常过来。\u003c/td>\u003ctd>他每周最少过来三次。\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>&nbsp;&nbsp;&nbsp; 这个片段给我们讲述了关于如何表达观察及观察和评论的区分要点。在片段中，大家是否要找到了表达观察的要点呢？有谁愿意来分享一下？在开篇中就有提到该如何表达观察，我归纳为如下三个步骤：①仔细观察正在发生的事②清楚的说出特定时间、情景下的观察结果③适当表达评论（基于观察结果）。\u003cbr>&nbsp;&nbsp;&nbsp; 大家了解了观察的三步骤以后，想想我们平时说的很多话是否是观察还是评论呢？文中表格归纳了如何区分观察和评论的。大家可能觉得表格的描述有点不太好理解，那我们可以与正确表达观察的三个步骤结合起来看。其实他强调了三点：首先就是在描述观察结果时，一定要有依据，即描述具体的时间或情景。其次就是我们说出的观察结果一定要是事实，而非推测、预测或评论。最后在表达评论时要记得在评论前加上评论的主语是谁。例如:“小王在和我说话时爱发牢骚”。“爱发牢骚”就是评论。“这周小王给我打了三次电话，每次都说别人不尊重他，我觉得他很难受。”这就是观察。\u003cbr>&nbsp;&nbsp;&nbsp; 另外，大家可能会对片段中提到的“每次”“曾”这样的字眼来描述也算作观察而非评论会心存疑惑。因为听起来与”从不&quot;、“总是”、“经常”、“很少”都一样，这可能是中西方表达方式的差异造成的。在西方，这两个字眼在表达时间频率上比后者几个词是具体的。其实重点是我们的表达是否言过其实。例如:如果有个人抱怨对方有很多次不接电话的情况，说“你为什么每次都不接电话？！”那如果对方并不是每次，只是因为几次特殊原因没接，那就会认为对方是在指责，这就属于评论。如果事实就是每次都没接到，或换成:“我每次给你打电话时，你都没有接我电话”。那这样就是在表达观察。\u003c/p>","interaction":"\u003cp>接下来，让我们一起回忆一下，最近在家庭、工作中，我们与另一半、孩子、父母、同事、朋友相处的过程中，是否有听到过或自己向对方表达过自己对某件事或某个人的看法、判断、推测或陈述。比如有没有跟老公分享家里熊孩子的各种调皮捣蛋~有没有跟同事讨论某位领导的管理方式~有没有跟闺蜜抱怨老公或男朋友的种种难以忍受的生活方式~而当时你或对方是如何表达的，而对方或你又是如何回应的。请把他写在纸上。\u003cbr>例如，我曾经跟我的老公抱怨说“你总是不守时”，结果他立马就反抗到“我怎么不守时啦？我只是……”\u003cbr>&nbsp; 大家看看刚刚写在纸上的案例是观察还是评论呢？如果是评论，请想一下，如果下次你再遇到这种情况，你会如何沟通，请结合片段中的正确表达观察的三个步骤“仔细观察正在发生的事，描述具体的时间和情景，说出观察的结果。”来进行分享。如果是观察，请你设想一下，在未来的一周你有没有需要和某某人谈论一个人或一件事，请试着运用观察的要点来谈论。例如，“老公，每周四和你约定晚上10点来地铁站接我。可是每次你都会晚15分钟才到。”\u003cbr>&nbsp;&nbsp;&nbsp; 最后留给大家一个小作业:请在未来一周内，收集3个用观察来表达的小案例在我们群里分享，并和大家说说你用观察的方式来描述后的体悟。\u003cbr>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475892419000,"updated_at":1475892419000,"ria":true},{"id":1045,"topic":"你会表达自己的感受吗","learn_goal":"能够正确认识感受，并能用正确的方式来表达感受与自身的关系。","remark":"《非暴力沟通》，作者是马歇尔•卢森堡博士，他是一位临床心理学博士。是国际非暴力沟通中心创始人。\r\n    这本书行文简单易学，列举了大量案例帮助我们理解和运用。被入选香港大学推荐的50本必读书籍之一。也是拆书帮大力推荐和多次拆解的书籍，\r\n    大家在现实生活中，是否有遇到过沟通不畅的情况呢？例如，我明明表达的是这个意思，而对方却理解成另外的意思？再例如，我本想给对方提出善意的建议，然而对方却认为我在指责他。如果是，那么这本书就正好适合您。书中提出的非暴力沟通方式，让我们在轻松、愉快沟通的同时拥有充满爱与和谐的关系。","level":"TF2-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"水澜色","city":"广州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我是水澜色，是一名职场妈妈。目前的工作是在汽车制造工厂负责成本管理，兼任培训担当。\r\n▼今天的拆解主题是你会表达自己的感受吗？希望大家在跟随我完成本次RIA的现场学习后，在面对不中听的话时，能够对感受有正确的认识，并学会正确的表达我们的感受及其根源。\r\n 我要拆解的片段:来自这本书《非暴力沟通》，作者是马歇尔•卢森堡博士，他是一位临床心理学博士。是国际非暴力沟通中心创始人。\r\n 这本书行文简单易学，列举了大量案例帮助我们理解和运用。被入选香港大学推荐的50本必读书籍之一。也是拆书帮大力推荐和多次拆解的书籍，\r\n 大家在现实生活中，是否有遇到过沟通不畅的情况呢？例如，我明明表达的是这个意思，而对方却理解成另外的意思？再例如，我本想给对方提出善意的建议，然而对方却认为我在指责他。如果是，那么这本书就正好适合您。书中提出的非暴力沟通方式，让我们在轻松、愉快沟通的同时拥有充满爱与和谐的关系。","ratings_count":0,"texts":[{"id":3234,"quote":"\u003cp>听到不中听的话：四种选择\u003c/p>\u003cp>&nbsp;非暴力沟通强调，感受的根源在于我们自身。我们的需要和期待，以及对他人言行的看法，导致了我们的感受。\u003c/p>\u003cp>&nbsp; 听到不中听的话时，我们有四种选择。\u003cbr>\u003c/p>\u003cp>&nbsp; 第一种是认为自己犯了错。例如，有人气愤地说：“我从没见过像你这么自私的人！”这时，我们可能会自责：“哦，我没有考虑别人的感受，真是太自私了！”这会导致我们内疚、惭愧，甚至厌恶自己。\u003c/p>\u003cp>&nbsp; 第二种是指责对方。这时，我们也许会驳斥对方：“你没有权利这么说！我一直都很在乎你的感受。你才自私！”在争吵时，我们一般会感到恼怒。\u003c/p>\u003cp>&nbsp; 第三种是了解我们的感受和需要。这时，我们可能会发现我们有些伤心，因为我们看重信任和接纳。\u003c/p>\u003cp>&nbsp; 第四种是用心体会他人的感受和需要。这时，我们也许就会想“他伤心可能是因为他需要体贴和支持。”\u003c/p>\u003cp>&nbsp; 通过了解我们的需要、愿望、期待以及想法，我们不再指责他人，而承认我们的感受源于自身。\u003c/p>\u003cp>&nbsp; 请注意以下例句表达失望的方式有何不同。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;&nbsp; 甲：你昨晚没来令我很失望。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 乙：昨晚你没来，我很失望，因为我想和你说一些烦心事。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 在上面的例句中，甲认为，她的感受是由他人的行为引起的。而乙认为，她感到失望，是因为她的愿望没有得到满足。\u003c/p>\u003cp>&nbsp;&nbsp; 例2：&nbsp;&nbsp; 甲：他们取消了合同让我很不高兴。&nbsp;&nbsp; 乙：他们取消了合同，我很不高兴，因为我对自己说这是极不负责任的行为。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp; 在这个例子中，甲认为，他人的行为使她不高兴；而乙认识到，她的观点使她不愉快。在非暴力沟通中，我们还鼓励乙进一步了解她的愿望；她的哪些需要、期待或价值取向没有得到满足？我们把愿望说得越清楚，他人也就越可能作出积极的回应。例如，乙可以这样表达她的愿望：\u003c/p>\u003cp>&nbsp;&nbsp; “他们取消了合同，我很不高兴，因为我想重新聘用我们在去年解聘的员工。”&nbsp; \u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; 如果我们想利用他人的内疚，我们通常采取的办法是：把自己不愉快的感受归咎于对方。家长也许会和孩子说：”你成绩不好让爸妈伤透了心！“言下之意是，他们的快乐或不快乐是孩子的行为造成的。看到父母的痛苦，孩子可能会感到内疚，并因此调整行为来迎合他们。遗憾的是，这种调整只是为了避免内疚，而非出自对学习的热爱。\u003c/p>\u003cp>&nbsp;&nbsp; 使用以下表达方式时，我们可能就已经忽视了感受与自身的关系。\u003c/p>\u003cp>&nbsp;&nbsp; 1）只提及相关的事情。&nbsp;&nbsp;&nbsp;&nbsp; “公司海报出现拼写错误使我很生气。”“这件事令我心神不宁。”\u003c/p>\u003cp>&nbsp;&nbsp; 2）只提及他人的行为。“我生日那天你没打电话，我很伤心。”&nbsp; “你没有把饭吃完，妈妈很失望。”\u003c/p>\u003cp>&nbsp;&nbsp; 3）指责他人。“我很伤心，因为你说你不爱我。”&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “我很生气，因为老板说话不算数。”\u003c/p>\u003cp>&nbsp;&nbsp; 我们可以通过“我（感到）......因为我......”这种表达方式来认识感受与自身的关系。例如：&nbsp;&nbsp; 1）“看到公司海报出现拼写错误，我很不高兴。因为我重视公司的形象。”\u003c/p>\u003cp>&nbsp;&nbsp; 2）“你没把饭吃完，妈妈感到失望。因为妈妈希望你能健康成长。”&nbsp;&nbsp; 3）“老板说话不算数，我很生气。因为我想有个长假去看弟弟。”\u003c/p>","explains":"\u003cp>&nbsp;我们的感受是来源于自身未被满足的需要、期待、和价值观。那大家平时在听到不中听的话时，会是哪种反应呢？一般是不是第一、二种，而这时我们要么是自我的内疚和自责，更通常的是双方的争吵或不欢而散。因为我们常常认为是他人的行为（对方没有按照我们的要求去完成事情）、他人的言语（你真是一个自私的人）导致我们恼怒、难过、委屈。而事实上这些外界事情只是刺激了我们，促使我们有这样那样的感受和情绪。而我们强烈感受、情绪的根源其实是我们自身未被满足的需要、期待和价值观等（我需要互相信任、需要被理解和包容）。\u003cbr>&nbsp;&nbsp; 而片段中第三、四种反应，是我们少用的，这也正是非暴力沟通中关于“感受根源于自身”这个观点的两个方面的运用，一个是体会并表达自己的感受及根源，另一个是体会并表达对方的感受及其根源。而一旦我们这样去思考和表达时，我们就会停止指责对方，怒气也会不再那么强烈。\u003cbr>&nbsp;&nbsp; 那接下来，我举一个例子来说明下为什么感受根源于我们自身。例如：我们约了人，可是时间到了，对方迟迟没有出现。如果我们彼此的关系正处于较微妙的时期，我们可能会忧心忡忡；而如果我们看重诚实守信，我们就会觉得不耐烦；而如果我们正好想休息一下，我们就不会介意对方来晚了。因此同一件事情，由于自己的不同需要导致了不同的感受。若我们意识不到自己尚未满足的需要，一心只是考虑别人的过错，就难免会生气，指责对方。\u003cbr>&nbsp;&nbsp; 那大家如何将感受与需要相关联，并去表达。片段中提到了一个句式，那我从中归纳了几个步骤：①觉察发生的事实给自己带来的感受。②挖掘感受背后未被满足的需要、期望等。③用“....事情，我感到....，因为我....”的句式来表达这件事情给你带来的感受及感受的根源。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp; 在这四个步骤中，要特别注意几点：①在觉察自己的感受时，要注意区分哪些是真正的感受，哪些是想法。附一中列举了感受的词汇表，供大家参考。在实际应用时，大家可能会说:&quot;我觉得我被人误解了/被人欺负了/被忽略了/老板很卑鄙/他很负责”类似这种都是在你的想法、判断而非感受。真正的感受是“很难过/很气愤/很伤心/很不满/很高兴”。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp; 注意②哪些属于感受背后的需要，附二中列举了我们每个人都有的基本需要。凡是有助于生命健康成长的要素，就可被当做需要。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp; 注意③在描述自己感受时，一定不能只提及相关事情/他人行为。而是要强调感受与自身的关系，而非与外界事情的关系。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp; \u003cbr>\u003cbr>\u003c/p>","interaction":"\u003cp>接下来，我会设计一个场景让大家进行情景角色扮演。大家先在小组内进行扮演，然后我会让大家来展示。\u003cbr>&nbsp;&nbsp;&nbsp; 场景：老公每天工作、应酬、各种活动到很晚才回家。妻子很希望得到对方的陪伴。其中一人，扮演老公、一人扮演老婆。扮演要求：1.妻子用第一、二种方式回应，老公用“...事，我感到...，因为...”句式来表达听到老婆抱怨的感受及其根源。老婆给予适当回应。2.妻子用“...事，我感到...，因为...”句式来表达对老公晚归的感受及根源。老公给予回应（可尝试用同样句式回应）。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 大家通过刚刚的角色扮演，相信对于怎样表达感受和需要，以及为什么要用这种方式表达有了更深的体会。那接下来，我想请大家回到片段一中，大家分享的自己的亲身经验。请思考一下，如果下次你再遇到被指责或想要去责备他人的情况，你会如何沟通。请结合片段二中的四个步骤来表达感受和需要。\u003cbr>&nbsp;&nbsp;&nbsp; 例如：针对老公迟到的情况，我下次会说：“老公，你好几次来接我都会比约定时间晚，我感到有点恼火，因为我很看重守时，没有守时我会认为不被尊重。如果下次你因为特殊情况会迟到，可否提前打电话告诉我呢？”\u003cbr>&nbsp;&nbsp;&nbsp; 大家也可以继续在我们的群里来分享你对于这几个步骤实施的情况，并分享你应用的感受。大家一起共同学习和交流。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475891731000,"updated_at":1475891731000,"ria":true},{"id":1044,"topic":"赞扬","learn_goal":"能够有意识的留意生活中的积极面，看到他人对赞扬的渴望。","remark":"这本书行文简单易学，列举了大量案例帮助我们理解和运用。被入选香港大学推荐的50本必读书籍之一。也是拆书帮大力推荐和多次拆解的书籍，\r\n    如果大家在现实生活中，也像我一样有遇到过沟通不畅的情况。例如，我明明表达的是这个意思，而对方却理解成另外的意思？再例如，我本想给对方提出善意的建议，然而对方却认为我在指责他。那么这本书就正好适合您。\r\n▼本次的拆解主题：今天，您会赞扬了吗？希望大家在跟随我完成本次RIA的现场学习后，能够拥有一双善于发现美的眼睛，会用非暴力沟通的方式来表达赞扬。\r\n  而非暴力沟通是马歇尔.卢森堡博士发现的一种沟通方式，依照它来谈话和聆听，能使人们情意相通，和谐相处。","level":"TF2-3","duration":50,"status":0,"type":0,"chaishujia":{"username":"水澜色","city":"广州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"▼今天我要拆解的片段:来自这本书《非暴力沟通》，作者是马歇尔•卢森堡博士，他是一位临床心理学博士。早年师从心理学大师卡尔.罗杰斯，后来发展出极具影响力的非暴力沟通方法。并在2006年由于在促进人类和谐共处方面的突出成就，获得了地球村基金会颁发的和平之桥奖。他不仅教会人们如何使个人生活更加和谐美好，同时解决了众多世界范围内的冲突和争端。\r\n 这本书行文简单易学，列举了大量案例帮助我们理解和运用。被入选香港大学推荐的50本必读书籍之一。也是拆书帮大力推荐和多次拆解的书籍，\r\n 如果大家在现实生活中，也像我一样有遇到过沟通不畅的情况。例如，我明明表达的是这个意思，而对方却理解成另外的意思？再例如，我本想给对方提出善意的建议，然而对方却认为我在指责他。那么这本书就正好适合您。\r\n▼本次的拆解主题：今天，您会赞扬了吗？希望大家在跟随我完成本次RIA的现场学习后，能够拥有一双善于发现美的眼睛，会用非暴力沟通的方式来表达赞扬。\r\n 而非暴力沟通是马歇尔.卢森堡博士发现的一种沟通方式，依照它来谈话和聆听，能使人们情意相通，和谐相处。非暴力沟通模式包含4个要素：清楚的表达观察结果、表达","ratings_count":0,"texts":[{"id":3232,"quote":"\u003cp>\u003cstrong>对感激的渴望\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;虽然人们听到感激时会不太自在,但绝大多数的人渴望得到他人的肯定和感激。在一次聚会中，为了让来宾互相认识，我的一位年仅12岁的朋友建议大家一起做一个游戏。我们每个人写下一个问题，放在一个盒子里，然后，轮流取出一个问题并大声作答。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;在参加聚会前，我为一些社会工作者和公司职员提供了咨询服务，他们对感激的渴望深深触动了我。我常常听到这样的话；“不管你多努力工作，你都不会听到一句好话，但只要你犯了一点小错误，马上就会有人指责你。”于是，在聚会中，我写下了以下问题：“别人对你做的什么事表达感激，你会欣喜若狂？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;有位女士抽到了这个问题，读完之后，她哭了起来。这位女士负责管理一个妇女救助中心，这个机构为处于困境之中的妇女提供帮助。每个月，她都要精心制定工作计划，以使尽可能多的人得到帮助。然而在每一次提出工作计划时，她都会听到一些抱怨。她投入这么多精力制定工作计划，但她想不起来，有任何人肯定过她的努力。一看到我的问题，他就想起了这件事，对感激的渴望让她流下了眼泪。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;听了这位女士的故事之后，我的另一位朋友说他也想回答这个问题。接着，其他所有人也表示愿意回答这个问题。在他们依次回答这个问题时，有几个人感动得哭了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;对感激的渴望不仅存在于工作场合，而且也存在于家庭中。有一天晚上，当我向我的儿子布莱特指出他没做好家务活时，她反驳说：“爸爸，你想想，你是不是倾向于指出问题，而很少肯定我？”他的话在我脑海中盘旋了许久。我发现我总是想做得更好，却很少肯定已有的成绩。我刚刚结束一个有100多人参加的研讨班，除了一个人，其他人都高度评价这次的研讨班。然而，我牢记的却是那个人的不满。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;那天晚上，我意识到，在回顾个人经历时，我往往想到的时我做得不太好的2%，而不是做得不错的98%。我还想起了一位老师的教育方式。她的一位学生，因为没有做好考试准备，在一次考试中，写上名字后交了白卷。当卷子发下来时，学生很惊讶，他发现他得了14分（满分100）。于是，他就去问老师：“我怎么会有14分呢？”她回答说：“整洁。”这次，布莱特又提醒了我，从那以后，我就更加留意生活中积极的一面，并表达我的感激之情。\u003c/p>","explains":"\u003cp>片段一中给了我们两个信息：一是通过案例说明了大多数人对赞扬的渴望。二是要多留言生活中的积极面并表达赞扬。\u003cbr>&nbsp;&nbsp;&nbsp; 而大家在自己的生活中是如何看待赞扬的呢？你觉得表达赞扬重要吗？站在赞扬人的角度，想要表达赞扬一般的动机有：①表达自己的感激，不求回报。②通过赞扬来影响或操纵他人，希望通过赞扬来强化他人的行为，激励对方更加努力。站在被赞扬人的角度，如果自己的辛苦努力没有得到赞扬会怎样呢？他可能会感到气馁、失望，失落，不知道自己的作为，是否得到大家的肯定和认可，甚至会怀疑自己，影响积极性和自信心。由此可见，我们都是渴望赞扬的，因为①希望自己的努力能被看到，被认可，被肯定。②通过对方赞扬的反馈，知道自己哪方面给别人带来了益处。增强自己的信心，并激励自己做得更多更好。\u003cbr>&nbsp;&nbsp;&nbsp; 那大家可能会想难道赞扬就没有坏处了吗？当然不是，当我们在赞扬时，把自己放在裁判的位置去表述，“你真是个诗人！”“你太美了！”这样的夸奖听上去乏味，甚至虚假客套。而且当我们的赞扬是带着目的。希望员工更加卖力的工作；希望老公多多做家务和美味的饭菜。那当对方知道你的用意后，就可能适得其反啦。\u003c/p>","interaction":"\u003cp>接下来，大家反观一下自己，觉察一下自己的思维和表达模式。我是否善于发现自己或别人的优点和积极面？并及时表达自己的感激之情。在生活中是否有被别人抱怨总是批评人？请举出具体的案例来分享。例如，我总是特别关注自己做得不够好的地方。每次拆书结束后，我都渴望得到对方对我改善的建议。也会听回录音，寻找当中出现的各种失误。有时会因此而看不到自己的优点，而对自己感到沮丧和焦虑。例如，曾经在与婆婆的相处过程中，由于双方生活习惯和观念的不一样，会有一些磕磕碰碰，相处不是那么的舒服。而婆婆依然为了我们的小家，无怨无悔的付出。在我已经意识到老人需要我们的肯定和赞扬时，我却看不到婆婆身上的优点，不懂得表达赞扬。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 想想在我们周围是否有一个人，他默默的付出了很多，或很努力的做事想要被你看到和认可，可是你却很少向他表达感激，甚至还常常指出他做得不够好的地方。那我们试着找出他身上的3个优点或你想要感激的地方来与大家分享。例如，婆婆优点：朴实、勤劳、随和。\u003cbr>&nbsp; \u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3233,"quote":"\u003cp>\u003cstrong>非暴力沟通表达感激的方式\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;非暴力沟通表达感激的方式包含三个部分：\u003c/p>\u003cp>1.&nbsp;\u003cstrong>对方做了什么事情使我们的生活得到了改善；\u003c/strong>\u003c/p>\u003cp>2.&nbsp;\u003cstrong>我们有哪些需要得到了满足；\u003c/strong>\u003c/p>\u003cp>3.&nbsp;\u003cstrong>我们的心情怎么样？\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;在表达感激时，这三个部分的先后次序并不重要；有时，我们甚至可以通过微笑或说声“谢谢”来表达这三个部分。然而，如果我们要确保对方能够明白我们的意思，那么，用语言具体地描述这三个部分是值得的。以下是我和一个非暴力沟通研讨班参加者的一段对话。在对话中，我试图理解他为什么要赞扬我。\u003c/p>\u003cp>参加者：（在研讨班结束后走进我）“马歇尔，你真了不起！”\u003c/p>\u003cp>马歇尔：“我想知道你为什么这么说。”\u003c/p>\u003cp>参加者：“为什么呢？”\u003c/p>\u003cp>马歇尔：“在我的一生中，人们用各种各样的话来评价我。这对我并没有多大帮助。我需要更多的信息来理解你的评价。”\u003c/p>\u003cp>参加者：“什么样的信息？”\u003c/p>\u003cp>马歇尔：“首先，我想知道，我做了什么，你认为对你的生活有帮助？”\u003c/p>\u003cp>参加者：“哦，你聪明过人。”\u003c/p>\u003cp>马歇尔：“也许这又是一个评价。我还是不清楚我做了什么对你有益的事情。”\u003c/p>\u003cp>她想了想，然后拿出笔记本，指着其中的两段话说：“就是这两点。你今天在研讨班中提到他们。”\u003c/p>\u003cp>马歇尔：“哦，你很欣赏这两个观点。”\u003c/p>\u003cp>参加者：“是的。”\u003c/p>\u003cp>马歇尔：“听到这两个观点时，你的心情怎么样？”\u003c/p>\u003cp>参加者：“我感觉一阵轻松，对将来更有信心了。”\u003c/p>\u003cp>马歇尔：“现在，我想知道，这两个观点使你什么样的需要得到了满足？”\u003c/p>\u003cp>参加者：“我没法和儿子沟通。他今年18岁了。我一直盼着能有办法和他沟通，你今天的这两个观点给我很大的启发。”\u003c/p>\u003cp>这样，我就知道了我所做的事情、她的感受以及她的需要。我很高兴自己帮到了她。如果她一开始能够以非暴力沟通的方式表达感激，她也许就会说：“马歇尔，当你提到这两个观点时（让我看她的笔记本），我很欣喜，感到将来有盼头了，我一直在寻找和儿子沟通的办法，这两个观点给我很大的启发。”\u003c/p>","explains":"\u003cp>片段二中，作者给出了非暴力沟通方式下如何表达感激，这三个步骤其实对应了非暴力沟通的前三个要素：①表达你的观察结果②你的心情和感受③表达感受背后被满足的需求是什么。这三个步骤的表达无需考虑先后顺序。平时，我们常表达的可能会有第一个和第二个。但对于第三个感受、心情背后被满足的需求就鲜有表达。那其实这个是非常重要的。\u003cbr>&nbsp;&nbsp;&nbsp; 我举一个例子来让大家体会一下不同的赞扬表达方式，给你带来的感受有什么不一样呢？例如，最近工作上的一个项目非常棘手，我加班对应，根据烦乱的现状，理出了两种对策供上司来选择。第二天我将我的对策向上司做了汇报。上司听完以后给了第一种反馈：“小王，谢谢！辛苦啦！”第二种：“辛苦啦！你能按期完成我很高兴。”第三种反馈：“这件事情非常棘手，我看到你连续加了好几天班来积极对应。并给出了你的几个方案。我觉得很高兴和欣慰。谢谢你的积极努力对应。让我们这个项目能如期顺利推进。辛苦啦！”大家听完以后，会觉得那种比较赞呢？\u003c/p>","interaction":"\u003cp>接下来我要大家进行场景演练。场景是：两人扮演活动组织者，其他人扮演活动参与者。公司工会定期会举行各种活动邀请职员参加，可是每次活动组织完成后，都会收到参与者的各种投诉或抱怨。总之辛苦组织的活动很难得到大家的认可。组织者有点苦恼。在一次活动组织完毕后，又像往常一样收到了各种抱怨。两位组织者商量着，想要改变这种局面。于是他们决定从众多的抱怨中找到积极的一面，去向参与者表达感谢。参与者最终也理解了组织者，并通过赞扬表达了自己对组织方的认可。在表达感谢时请注意运用非暴力沟通表达赞扬的三要素进行。\u003cbr>5分钟演练，再当众演练。其他小组的观察员，可以对演练场景是否正确运用赞扬3步骤进行观察结果的分享。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 最后留给大家一个小作业：请用非暴力沟通的赞扬方式来向您的母亲表达感激之情。记录你的表达方式以及对方的反馈，在群里分享。\u003cbr>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475891510000,"updated_at":1475891510000,"ria":true},{"id":1043,"topic":"请求","learn_goal":"能够正确区分请求与命令，用正确的方式提出请求。","remark":"今天拆解的片段来自这本——《非暴力沟通》。从书名就可以看出它是一本提升沟通能力的书籍。关于沟通，在我们生活工作中，无处不在、不可或缺。大家也一定遇到过各种需要沟通的场景。比如：一天，你需要与某个人（上司、长辈、爱人、孩子、朋友等）甚至是一群人（学生、下属员工、家人、邻居等）去请求他们配合你或支持你完成一件事情。当时你是如何沟通的，效果如何呢？是失败了还是成功了？若失败了，现在回过头来看，是因为当时的沟通方式，还是态度还是其他您没想到的地方没有处理好导致的呢？当时那件事情由于没有得到他们的配合和支持，对你有什么影响呢？沟通的失败，是否一方面影响了那件事情的正常进展，甚至可能还影响到你和对方的关系","level":"TF2-4","duration":20,"status":0,"type":0,"chaishujia":{"username":"水澜色","city":"广州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家晚上好！我是二级拆书家水澜色。今天拆解的片段来自这本——《非暴力沟通》。从书名就可以看出它是一本提升沟通能力的书籍。关于沟通，在我们生活工作中，无处不在、不可或缺。大家也一定遇到过各种需要沟通的场景。比如：一天，你需要与某个人（上司、长辈、爱人、孩子、朋友等）甚至是一群人（学生、下属员工、家人、邻居等）去请求他们配合你或支持你完成一件事情。当时你是如何沟通的，效果如何呢？是失败了还是成功了？若失败了，现在回过头来看，是因为当时的沟通方式，还是态度还是其他您没想到的地方没有处理好导致的呢？当时那件事情由于没有得到他们的配合和支持，对你有什么影响呢？沟通的失败，是否一方面影响了那件事情的正常进展，甚至可能还影响到你和对方的关系呢？那在这本书中，作者马歇尔•卢森堡博士，就提出了非暴力沟通模式，其包含4个要素：清楚的表达观察结果、表达感受、哪些需求导致那些感受、提出具体的请求。依照它来谈话和聆听，能使人们情意相通，和谐相处，更容易达成你的沟通目的。","ratings_count":0,"texts":[{"id":3231,"quote":"\u003cp>\u003cstrong>请求与命令\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;一旦人们认为不答应我们就会受到惩罚，他们就会把我们的请求看作是命令。听到命令时，一个人只能听到两种选择：服从或反抗。不论如何，只要人们认为我们是在强迫他们，他们就不会乐于满足我们的需要。如果我们再过去常常指责他人，那么，我们的请求很可能就会被看作是命令。而一个经常受到指责的人也会倾向于将请求解读为命令。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;以下我们用一个例子来说明请求与命令的区别。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;如何区分命令和请求：请求没有得到满足时，提出请求的人如果批评和指责，那就是命令；如果想利用对方的内疚来达到目的，也是命令。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;杰克和他的朋友珍妮说：“我很孤单，希望今晚你能陪我聊聊。”这是请求还是命令呢？现在还不好说。我们需要根据珍妮没有同意时杰克的反应来作出判断。假定她回答说：“杰克，我今天很累。如果你想今晚有人陪你，你去找其他人好不好？”如果杰克接着说：“你这人真自私！”那么，他的提议实际上就是命令。因为他并没有重视珍妮休息的需要，而开始指责她。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;以下是对话以另一种方式展开：\u003c/p>\u003cp>杰克：“我很孤单，希望今晚你能陪我聊聊。”\u003c/p>\u003cp>珍妮：“杰克，我真的很累。如果你想今晚有人陪你，找别人好不好？”\u003c/p>\u003cp>杰克一声不吭走开了。\u003c/p>\u003cp>珍妮发现杰克不太高兴，就问他：“你怎么了？”\u003c/p>\u003cp>杰克：“没什么。”\u003c/p>\u003cp>珍妮：“我觉得你好像有心事。来，说说看。”\u003c/p>\u003cp>杰克：“你知道我孤单极了。你要是真爱我，今晚就会留下来陪我。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;在这段对话中，杰克仍然没有重视珍妮的需要，而是认为珍妮不再爱他。我们越是将他人的不顺从看作是对我们的排斥，我们所表达的愿望就越有可能被看作是命令。这将导致恶性循环，因为一旦人们认为我们是在强迫他们，他们就会不太想满足我们的愿望。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;反之，如果杰克尊重珍妮的感受和需要，那么他所表达的愿望就是请求而非命令。这时，杰克也许会说：“珍妮，你的意思是说，你已经很累了，今晚需要休息？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;在生活中，如果我们不想勉强人，那么，清楚地表明这一点是重要的——这有助于人们相信我们提出的是请求而非命令。例如，我们可以说：“帮我打开窗户好吗？”&nbsp;而不是说：”请打开窗户！”然而，在人们无法满足我们的愿望时，我们是否尊重他们的感受和需要最能体现我们提出的是请求还是命令。如果我们愿意去体会是什么使他们无法说“是”，那么，根据我的定义，我们提出的就是请求而非命令。选择通过请求而非命令来表达愿望，并不意味着，一旦人们说“不”，我们就不在去满足自己的需要。但它意味着，除非已经充分体会是什么妨碍了他人说：“是”，我们就不会试图说服他们。 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>","explains":"\u003cp>&nbsp;在读这个片段前，我相信大家对于什么是请求什么是命令，一定有自己的理解。我们可能会认为两者最大的区别是在于提请求时，我们说话的语气和方式。而阅读片段后，大家对于两者的区别是否有了不一样的认识呢？\u003cbr>&nbsp;&nbsp; 片段中关于如何区分请求与命令，有一个最关键的点，就是看当请求未得到满足时，提出请求人的反应是什么？①是批评、指责，例如“你这人真自私！”；②还是通过激将法，想利用对方的内疚来达到目的，例如“你要是真爱我，今晚就会留下来陪我。”还是③尊重对方的感受和需要。“你的意思是说，你已经很累了，今晚需要休息？”。那前两种反应都是属于没有重视对方的需要，把对方的拒绝、不顺从当做是对自己的排斥。那这就是命令。而最后一种，是尊重对方感受和需要的，不勉强他人，那就是请求。\u003cbr>&nbsp;&nbsp; 在比如，父母看到自己的小孩不好好吃饭时，可能会说“你再不吃饭，就打你！”“你真是个不听话的小孩！”“你看妈妈辛苦了几个小时给你做了这么多好吃的，你都不吃几口，你要是懂事，就乖乖把饭菜吃完。”那这些都是没有尊重小孩的感受和需要，只是批评、想让对方内疚从而达到目的，就都是属于命令。而如果这样表达：“宝宝，你不想吃饭，是因为之前吃了太多零食，现在还不饿是吗？”那这就尊重对方的感受和需要，不勉强宝宝一定要吃得和平时一样多。\u003cbr>&nbsp;&nbsp;&nbsp; 我们要如何来表达我们的请求，从而让对方能够更加愿意来满足我们的需要呢？有以下3个提请求的技巧、要点。\u003cbr>&nbsp;&nbsp;&nbsp; ①清楚告诉我们希望他们做什么，而非不做什么。eg1.“不要再喝酒了。”or“你是否可以告诉我，喝酒可以满足你什么需要？是否有别的方式可以满足你的那些需要呢？”eg2.“我希望你少花时间在工作上”or“我希望你每周至少有一个晚上在家陪我和孩子。”\u003cbr>&nbsp;&nbsp;&nbsp; ②提出的请求越具体越好。如果提出的请求意思含糊不清，别人就难以了解我们到底要什么。“我希望你能尊重我的个人隐私。”or“在进我的房间前，请您先敲门好吗？”\u003cbr>&nbsp;&nbsp;&nbsp; ③当无法确定对方是否已明白，我们可以请求反馈或者请对方重复他的理解。eg.“我的意思你理解吗？”\u003c/p>","interaction":"\u003cp>现在大家回忆一下我们过往的经历，当我们需要家人、同事、朋友配合、协助我们时，我们当时提出来的到底是命令还是请求呢？当时的对话是怎样的呢？比如，我曾经在组织科内同事对于职场满意度调查的会议上，向大家提出了这样的请求：“对于目前部门内开展的提升员工满意度的活动，请大家谈谈自己的看法。”结果收到的回复，是一片沉默，当时特别尴尬。心想，“大家怎么总是这么不积极，一到公开场合就都不愿意分享自己的想法呢？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 接下来，请大家根据过往经历或是未来很有可能会遇到的场景，自己编一个小故事或情节演练，几百字即可，请自行设计出人物、情节变化（包括：起因、经过、结果）、当时人物的对话、动作、表情等，其中对话部分请使用“提请求”的3个技巧。请将故事摘要写在纸上，时间5分钟，5分钟后我们请小伙伴来给我们分享他的故事剧本。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475889205000,"updated_at":1475889205000,"ria":true},{"id":1042,"topic":"倾听","learn_goal":"运用倾听技巧去体会对方的观察、感受、需要和请求","remark":"关于沟通，在我们生活工作中，无处不在、不可或缺。大家也一定遇到过各种需要沟通的场景。比如：朋友向你吐槽，家人的指责或不理解，或者是来自同事间的误会等。在这些情景下，你是如何倾听又是如何沟通的呢，当时效果如何？是成功化解了对方的情绪/误解？还是失败了呢？若失败了，现在回过头来看，是因为当时的沟通方式，还是态度还是其他您没想到的地方没有处理好导致的呢？当时那件事情对你有什么影响呢？是否还影响到你和对方的关系呢？那在这本书中，作者马歇尔•卢森堡博士，就提出了非暴力沟通模式，其包含4个要素：清楚的表达观察结果、表达感受、哪些需求导致那些感受、提出具体的请求。依照它来谈话和聆听，能使人们情意相通，和谐相","level":"TF3-1","duration":25,"status":0,"type":0,"chaishujia":{"username":"水澜色","city":"广州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家晚上好！我是二级拆书家水澜色。今天拆解的片段来自这本——《非暴力沟通》。从书名就可以看出它是一本提升沟通能力的书籍。关于沟通，在我们生活工作中，无处不在、不可或缺。大家也一定遇到过各种需要沟通的场景。比如：朋友向你吐槽，家人的指责或不理解，或者是来自同事间的误会等。在这些情景下，你是如何倾听又是如何沟通的呢，当时效果如何？是成功化解了对方的情绪/误解？还是失败了呢？若失败了，现在回过头来看，是因为当时的沟通方式，还是态度还是其他您没想到的地方没有处理好导致的呢？当时那件事情对你有什么影响呢？是否还影响到你和对方的关系呢？那在这本书中，作者马歇尔•卢森堡博士，就提出了非暴力沟通模式，其包含4个要素：清楚的表达观察结果、表达感受、哪些需求导致那些感受、提出具体的请求。依照它来谈话和聆听，能使人们情意相通，和谐相处，更容易达成你的沟通目的。而今天我要拆解的主题——如何更好的倾听？","ratings_count":0,"texts":[{"id":3230,"quote":"\u003cp>\u003cstrong>倾听使身心痊愈\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;一个人如果有机会倾听，会是怎样的感觉呢？卡尔.罗杰斯这样写道：“如果有人倾听你，不对你评头论足，不替你担惊受怕，也不想改变你，这多美好啊……每当我得到人们的倾听和理解，我就可以用新的眼光看世界，并继续前进……这真神奇啊！一旦有人倾听，看起来无法解决的问题就有了解决办法，千头万绪的思路也会变得清晰起来。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;安德森女士是一所实验小学的校长。有一天，她在午饭后回到办公室时，发现有位叫米丽的女生满脸沮丧地坐在那里等她。米丽一见到她就问道：“阿姨，你有时候会不会连续几天都做了别人不喜欢的事，而你并不是有意的？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;“是的，”安德森回答说：“我想我明白你的意思。”这时，她需要赶去参加一个十分重要的会议，她并不希望满屋子的人等他一个人。于是，她就直接问：“米丽，我能为你做什么吗？”米丽轻轻抱住了她，望着她的眼睛，恳求她：“阿姨，我不要你做任何事情，我只想你听我说。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;安德森后来回忆说，这是她人生最重要的时刻之一。她很感激她的学生给她的启发。她当时想：“如果时间来不及，就请满屋子的成年人等等吧！”她和米丽一起坐在了一张长椅上，她的手抱着米丽的肩膀，米丽依偎着她，搂着她的腰。她们就这样坐着，直到米丽说完她的心事，而时间并不算长。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;我的朋友劳伦斯也和我分享了她的一段经历。有一次，她和六岁的儿子谈话，话还没说完，儿子一不高兴就跑开了。这时，年仅十岁的女儿和她说：“妈妈，看起来你有一点生气，你希望他耐心地与你谈话，是吗？”听到女儿的话，劳伦斯大为惊讶，气也消了。儿子回来后，她也就能静下心来和他谈话。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;一位大学教师提到，一些教师通过倾听以及表达自己的需要，使师生关系得到了明显的改善。“”学生们越来越敞开心扉，告诉我们他们生活中的困难。他们对干扰学习的因素认识得越清楚，也就越能够提高学习的效率。虽然倾听他们占用了我们许多时间，但我们认为这是值得的。不幸的是，系主任对此感到了不安。她说，“我们并不是心理医生，我们应该多花时间在教学上，而不是与学生谈心。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;当我问他教师们怎么和系主任沟通时，他回答说：“我们用心倾听他的感受和需要。我们注意到，他有些担心，他希望我们不要介入到我们不擅长的领域中。我们还注意到，他希望我们能够告诉他，我们与学生谈心并不会影响教学。得到我们的反馈后，他看起来很欣慰。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;在组织机构中，我们在听到上级的意见时，经常会把它看作是命令或指示。倾听同事或下级比倾听上级要容易得多。在上级面前，我们有时可能会有点紧张，以致无法静下心来体会他们的感受和需要，并给予反馈。因此，我特别欣赏这些教师能像倾听学生那样倾听他们的系主任。\u003c/p>","explains":"\u003cp>阅读完后，请大家结合曾经倾听他人或是被倾听时的情景或是书中的案例，来说说倾听对被倾听者和倾听者的意义有哪些？（比如，使人情绪好转、改善双方关系，获得信任，/成就感，助人）\u003cbr>&nbsp;&nbsp; 既然好的倾听意义非凡，我们到底该如何倾听才能让人身心痊愈呢？\u003cbr>&nbsp;&nbsp; ①首先要放下已有的想法和判断，全神贯注地体会对方。通常我们在听完对方述说完自己的经历、感受或求助/听到对方对自己的抱怨后，我们通常会去怎么回应呢？比如，我又被老板批了~~~建议（我想你应该...），比较（这算不了什么，你听听我的经历...），说教（如果你这样做...，你将会得到更大的好处），安慰（这不是你的错，你已经尽最大努力了），否定（高兴一点，不要这样难过），同情（哦，你这可怜的人），询问（这种情况是什么时候开始的？），解释（我原想早点打电话给你，但昨晚...），纠正（事情的经过不是那样的...）\u003cbr>&nbsp;&nbsp; ②不论对方以什么样的方式来表达自己，我们都可以用心体会其中所包含的观察、感受、需要和请求。既不反驳也不自责。关于这一点，大家从片段的例子中，看看倾听者是如何做的？eg先生：和你说话有什么用？你从不好好听。正面：太太：“你不高兴，是因为你需要得到理解。”反面：太太“你生我的气吗？/你感到不高兴，是因为你觉得我不理解你？”（自责/只是关注他的想法而非需要）\u003cbr>&nbsp;&nbsp; ③在倾听他人的观察、感受、需要和请求之后，我们可以主动表达我们的理解。建议使用疑问句来给予反馈。在他人的观察、感受及需要、请求，这四个方面进行疑问反馈。判断以下反馈正确吗？例如，观察“上周我有三个晚上不在家，你说的是这回事吗？”——“你说的是什么事？”。感受/需要“你很灰心？你希望得到肯定是吗？”——“你现在心情如何？为什么会有那样的感觉？”请求“你是不是想请我帮你订酒店？”——“你希望我怎么做？”反面的例子无需用心体会他人。\u003cbr>反馈的时机：1.在对自己理解无把握时，2.他人有明显情绪时，通常希望得到反馈，3.即使你已理解，对方也很有可能希望你反馈，甚至会直接询问“你明白吗？”\u003cbr>&nbsp;&nbsp; ④在解决问题或询问他人的请求前，为他人的充分表达创造条件。例如片段中的例一。如何判断对方已充分表达：1.他变得轻松了，你也感觉到轻松了。2.他停止谈话了。\u003c/p>","interaction":"\u003cp>场景（家庭：与父母）你今年已经30了，却还没有男/女朋友，父母非常着急，不管是电话、见面，话题都是催着找对象结婚，为此，你们吵过好几次并影响到你和父母间的关系。你很苦恼，想有所改善。而这周末你又要去见父母了，你已经预想到父母又会对你唠叨了。但这次你打算尝试用倾听的技巧来回应他们。经过与父母的谈话和倾听，不但化解了父母的担心，你也重新认识到这个问题并决心要认真对待。请在小组内讨论并分享你们的场景演练。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 今天已经学习了倾听的技巧，请在本周内，抓住一次倾听他人的机会，去尝试运用倾听的技巧回应对方。记录下你们的对话，并仔细体会你们的对话，在倾听技巧方面，哪些已经运用，哪些仍难以改变惯有的习惯，并思考可以做何种改善并在我们的群内分享。\u003cbr>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475889098000,"updated_at":1475889098000,"ria":true},{"id":1041,"topic":"我的生活我做主","learn_goal":"过级","remark":"今天拆解的片段来自这本——《非暴力沟通》。从书名就可以看出它是一本提升沟通能力的书籍。关于沟通，在我们生活工作中，无处不在、不可或缺。大家也一定遇到过面对不同对象的各种沟通场景。比如：遇到朋友的误会，家人的抱怨，或寻求同事的协助等。在这些情景下，你是如何沟通的呢，当时效果如何？是成功化解了对方的情绪/误解？还是失败了呢？若失败了，现在回过头来看，是因为当时的沟通方式，还是态度还是其他您没想到的地方没有处理好导致的呢？当时那件事情对你有什么影响呢？是否还影响到你和对方的关系呢？\r\n    那在这本书中，作者马歇尔•卢森堡博士，就提出了非暴力沟通模式，其包含4个要素：清楚的表达观察结果、表达感受、哪","level":"TF3-2","duration":60,"status":0,"type":0,"chaishujia":{"username":"水澜色","city":"广州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家晚上好！我是二级拆书家水澜色。今天拆解的片段来自这本——《非暴力沟通》。从书名就可以看出它是一本提升沟通能力的书籍。关于沟通，在我们生活工作中，无处不在、不可或缺。大家也一定遇到过面对不同对象的各种沟通场景。比如：遇到朋友的误会，家人的抱怨，或寻求同事的协助等。在这些情景下，你是如何沟通的呢，当时效果如何？是成功化解了对方的情绪/误解？还是失败了呢？若失败了，现在回过头来看，是因为当时的沟通方式，还是态度还是其他您没想到的地方没有处理好导致的呢？当时那件事情对你有什么影响呢？是否还影响到你和对方的关系呢？\r\n 那在这本书中，作者马歇尔•卢森堡博士，就提出了非暴力沟通模式，其包含4个要素：清楚的表达观察结果、表达感受、哪些需求导致那些感受、提出具体的请求。依照它来谈话和聆听，可以发展友谊，促进家庭和睦，改善工作交流及推动政治和解。\r\n 而你知道吗？非暴力沟通最重要的应用还包含——爱自己爱生活。而我今天我要拆解的主题——我的生活我做主。","ratings_count":0,"texts":[{"id":3228,"quote":"\u003cp>\u003cstrong>回避责任\u003c/strong>&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;我们对自己的思想、情感和行动负有责任。可是，人们广泛使用“不得不”这一短语。例如：“不管你是否喜欢，有些事你不得不做。”显然，这种表达方式淡化了个人责任。“你让我”是人们常用的另一短语，例如：“你让我伤透了心。”此时，我们的表达方式忽视了我们情感的内在根源。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;在《艾希曼在耶路撒冷》一书中，作者汉娜.阿伦特记录了审判纳粹战犯阿道夫.艾希曼的过程。据她记载，艾希曼及其同事借助“Amtssprache”回避责任。\u003c/p>\u003cp>“Amtssprache”大意是“办公室语言”或“行政命令”。例如，如果问他为什么采取了某种行动，他也许会说：“我不得不做。”如果追问为什么“不得不做”，他就会答道，“长官命令”、“公司政策”或“法律规定”。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;有一次，在与家长和老师讨论回避责任所带来的危险时，一位女士气馁地说：“但有些事，你确实不得不做，不管你是否喜欢！我认为告诉孩子有些事他们也不得不做，并没有什么不对。”于是，我请她举例说明什么事她“不得不”做，她有点不屑地回答：“这太容易了！今晚离开这里后，我不得不做饭。我讨厌做饭！我早就受够了！但二十年来，每天我都不得不做饭。即使有时累得像一条狗。因为这是你不得不做的事情。”我告诉她，听到她长期做自己讨厌的事情，我很难过。我很希望非暴力沟通能帮她找到解决办法。很希望非暴力沟通能帮她找到解决办法。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;很快，她从学习中找到了灵感。研讨班一结束，她就告诉家人，她不想再做饭。三个星期后，她的两个儿子参加了一个研讨班，这让我们有机会了解他们怎么看母亲的决定。大儿子叹道：“马歇尔，我刚和自己说,”感谢上帝！”看到我困惑的表情，他解释说：“也许她终于可以不在吃饭时发牢骚了！”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;还有一次，我为一个学区的老师提供咨询服务。一位老师说道：“我讨厌评级。这样做不仅没用，而且学生会很紧张。但我不得不评级。因为这是学区政策。”此前，我们刚刚练习如何以负责任的方式来表达自己。我建议这位老师用以下的方式来表达：“我选择评级。因为我想…”。她脱口而出：“我选择评级。因为我想保住工作。”她赶紧补充了一句：“我不喜欢这样说。这让我觉得我负有不可推卸的责任。”我回答说：“这正是我建议你这样表达的原因。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;法国作家乔治.贝尔纳诺斯有段话引起了我的共鸣：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;“我常常想，如果有一天，技术的进步最终被用来摧毁人类，那么，并非是暴行导致人类的灭亡，当然，更不能说是复仇行为使人类灭亡……人类的灭亡，却是因为现代人唯唯诺诺、缺乏责任感，毕恭毕敬地服从各种命令。我们所看到的悲剧和马上就要看到的更大悲剧，并非是世界上反抗的人、不服从的人增多了，而是惟命是从的人、听话的人越来越多。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;一旦意识不到我们是自己的主人，我们就成了危险人物。\u003c/p>","explains":"\u003cp>在阅读片段前，大家对于“回避责任”是如何理解的呢？觉得哪些情况属于回避责任呢？（行为方面：做错事情要勇于承认和承担、多一事不如少一事等）。读完片段后，大家对于回避责任有哪些新的认识呢？什么叫回避责任？（非暴力沟通中认为，我们对自己的思想、情感和行动负有责任。换句话说，如果我们忽视自己的真实想法/需要、忽视情感的内在根源，而把我们的行为动机归为外界的环境、人、规则、不明驱动力等原因就是在回避责任。）\u003cbr>&nbsp;&nbsp;&nbsp; 回避责任常见的表达方式：“不得不、你让我”。比如，我不得不每天打扫房间；你让我太伤心了。大家可以尝试回想一下，我们曾经是否有这样表达过呢？当我们这样去表达的时候，我们内心会有什么感受，这样表达的原因？我不得不每天打扫房间（烦、苦恼）；我是一个母亲我必须照顾我的孩子（无奈）；假如我的身体不允许我喝酒，却说，聚会时我的朋友都喝酒了，我不得不喝（避免悔恨、内疚）；孩子太调皮了，我不得不打他（我没有做错）；老板让我这么做的（免责）；假如我需要控制体重，蛋糕太诱人了，我控制不住要去吃（为自己的行为寻找理由）。\u003cbr>&nbsp;&nbsp;&nbsp; 当这种表达变成一种习惯的时候，我们就会习惯性的服从、唯唯诺诺、不敢承担责任，忽视自己情感的内在根源。从而使生活缺乏乐趣，充满负能量，觉得自己不是生活的主人。而对于和我们共处的人来说，他们会有怎样的感受呢？从我们身上感受到的也是负面的能量，会容易产生冲突、矛盾，导致关系不佳。如片段中的例二，当妈妈主动提出不想做饭了，儿子的反馈是感谢上帝！\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp; \u003cbr>\u003c/p>","interaction":"\u003cp>刚刚我们已经认识到什么叫做回避责任，以及了解到回避责任给我们可能带来的不良影响，那我们自己平时的行为动机是什么呢？是否也有回避责任的情况呢？以下这个测试量表可以帮你了解自己的行为动机，请仔细阅读下列每句话的描述，根据自己的实际情况，按照1~6分的标准为自己打分。（1表示很不符合，6表示非常符合）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 大家的测试结果如何呢？（10分~60分），有没有30分以下的朋友？分数越高代表你平时行为动机中回避责任的倾向越大。你也可以在本次拆书结束后，把这个测试题当做一种提醒，或定期测试，回顾自己行为的动机是否有所改变。我们是否会越来越少回避责任，而是主动根据需要和价值观来选择生活。那大家现在一定非常关心，我们到底要如何改变我们的行为动机呢？别着急，我们先来阅读片段二，稍后我会告诉大家具体的行动步骤。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3229,"quote":"\u003cp>\u003cstrong>“不要做任何没有乐趣的事情！”\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;我想强调的是，我们行为的动机反映了我们是否爱惜自己。当我建议“不要做任何没有乐趣的事情”时，有些人觉得我很极端，甚至精神不正常。然而，我深信，出于对生命纯洁的爱，而不是出于恐惧、内疚、羞愧、职责或义务来选择生活，是爱惜自己的重要体现。如果我们致力于满足他人及自己健康成长的需要，那么，即使艰难的工作也不乏乐趣。反之，如果我们的行为是出于义务、职责、恐惧、内疚和羞愧，那么，即使有意思的事情也会变得枯燥无味。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>","explains":"\u003cp>为什么我们有时会觉得生活没有乐趣，或是生活中总有那么一两件事情让你觉得无趣、无奈却又不得不做呢？那刚刚这个片段给了我们一个很重要的提醒：我们关注自己的行为动机，动机会影响到我们做事情的乐趣，甚至是反映了我们是否是爱惜自己的。当时我读后觉得作者的观点非常有启发，我相信我们一定很少去往这个方面思考，更多的可能只是回避责任，只是觉得无奈。比如，我们可能为了收入做着一份让自己觉得超级无趣的工作。或者我们为了养育孩子，不得不每天做着很琐碎的各种杂事。\u003cbr>&nbsp;&nbsp;&nbsp; \u003cbr>\u003c/p>","interaction":"\u003cp>首先每人请在小组内分享：你生活中有哪些事情让你觉得缺少乐趣却又不得不做呢？（分享完后）请每个小组选出一个典型案例（觉得困扰自己很长时间，很痛苦的一件事），按照我刚刚发下来的问题列表大家一起帮助当事人进行深入讨论和反思以下几点：①这件事不得不做的理由（其它成员充分倾听）。②当充分了解到理由后，要求当事人“请告诉你自己你做这些事情是因为你选择了做它们，而不是因为你不得不做。请你重新说这句话：我选择做...”③“请思考：我选择做…，是因为我想….”（其它成员通过询问来引导对方找到自己做这件事情是为了满足自己的什么需要）来帮助咨询者深入理解自己的人生选择，并重新找到快乐的生活方式。结果可以是因为了解了事情真正的动机后，转变了对这件事情的看法，看到了他的价值，从而不再觉得苦恼。或者是大家一起帮他找到了具体的方法或对策来取代他之前不得不做的事情。最后请小组代表来分享你们的解决成果。\u003cbr>&nbsp;&nbsp;&nbsp; 那刚刚大家帮助当事人反思不得不做的理由，以及帮助他转变动机“不得不”转为“我选择做...&quot;,并帮他找到了做这件事的需要。那这三个步骤就是我们改变行为动机的过程，我们可以看到，通过这三个步骤我们可以改变行为动机，让我们原本苦恼的事，变得不再可怕，我们找到了更好的方式或我们找到了新的激情，让我们觉得生活又恢复了乐趣和热情。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 那在我们的生活中，其实或多或少都会存在行为动机是回避责任的情况。但有时我们自己都没有留意到。那么请在本周内留意你生活、工作中做事情的动机是否存在回避责任的情况。比如，有没有在内心里觉得这件事情不是我们想做，但又不得不做、别人让我们做的事情，请记录下来。然后尝试用三步骤来重新深入理解自己的人生选择，重新找到快乐的生活方式。并在群内分享你应用的感受和收获。如果你应用后依然没有找到你背后的需要，也可以在群内分享，和其他小伙伴一起讨论，帮助你重新理解自己的选择。\u003cbr>&nbsp;&nbsp;&nbsp; 那比如，我自己就曾经苦恼与每周都要打扫、整理房间，每次在做的时候都觉得毫无乐趣可言，只有累和烦。但又觉得自己不得不做，不做有时候还会被老公说，你怎么看到脏了也不清扫一下。那后来我分析了一下自己不得不做的原因：逃避指责。 后来当我改成，我选择做家务整理，是因为我希望有一个更加整洁、舒适的家居环境。我开始把着眼点放在了家居环境的改善上，我开始关注断舍离，开始关注家居整理等相关信息和书籍，并着手去实施，现在一到休息在家，我就忍不住要去实践我的整理方案。期待早一点看到家居环境大改善的那一天。\u003cbr>&nbsp;&nbsp;&nbsp; \u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475888771000,"updated_at":1475888771000,"ria":true}]};